type State struct {
	Revision                int                             `json:"revision"`
	NetworkRevision         int                             `json:"networkRevision"`
	ServiceabilityVersion   int                             `json:"serviceabilityVersion"`
	NextEventID             int64                           `json:"nextEventId"`
	NextTimelineEventID     int                             `json:"nextTimelineEventId"`
	NextAssignmentSeq       int64                           `json:"nextAssignmentSeq"`
	IneligibleAttempts      int                             `json:"ineligibleAttempts"`
	Users                   map[string]*models.User         `json:"users"`
	Sessions                map[string]*models.Session      `json:"sessions"`
	SampleTypes             map[string]*models.SampleType   `json:"sampleTypes"`
	Locations               map[string]*models.Location     `json:"locations"`
	Connections             map[string]*models.Connection   `json:"connections"`
	LabAcceptances          map[string]*models.LabAcceptance `json:"labAcceptances"`
	Samples                 map[string]*models.Sample       `json:"samples"`
	Journeys                map[string]*models.Journey      `json:"journeys"`
	Assignments             map[string]*models.Assignment   `json:"assignments"`
	Reservations            map[string]*models.CapacityReservation `json:"reservations"`
	Handoffs                map[string]*models.Handoff      `json:"handoffs"`
	Checkpoints             map[string]*models.Checkpoint   `json:"checkpoints"`
	Exceptions              map[string]*models.ExceptionRecord `json:"exceptions"`
	Disruptions             map[string]*models.DisruptionRecord `json:"disruptions"`
	ServiceabilitySnapshot  *models.ServiceabilitySnapshot  `json:"serviceabilitySnapshot"`
	Idempotency             map[string]*models.IdempotencyRecord `json:"idempotency"`
	AuditLog                []*models.AuditEntry            `json:"auditLog"`
	Events                  []*models.RealtimeEvent         `json:"events"`
}

func NewEmptyState() *State {
	s := &State{
		Revision:              1,
		NetworkRevision:       0,
		ServiceabilityVersion: 1,
		NextEventID:           1,
		NextTimelineEventID:   1,
		NextAssignmentSeq:     1,
		Users:                 make(map[string]*models.User),
		Sessions:              make(map[string]*models.Session),
		SampleTypes:           make(map[string]*models.SampleType),
		Locations:             make(map[string]*models.Location),
		Connections:           make(map[string]*models.Connection),
		LabAcceptances:        make(map[string]*models.LabAcceptance),
		Samples:               make(map[string]*models.Sample),
		Journeys:              make(map[string]*models.Journey),
		Assignments:           make(map[string]*models.Assignment),
		Reservations:          make(map[string]*models.CapacityReservation),
		Handoffs:              make(map[string]*models.Handoff),
		Checkpoints:           make(map[string]*models.Checkpoint),
		Exceptions:            make(map[string]*models.ExceptionRecord),
		Disruptions:           make(map[string]*models.DisruptionRecord),
		Idempotency:           make(map[string]*models.IdempotencyRecord),
		AuditLog:              make([]*models.AuditEntry, 0),
		Events:                make([]*models.RealtimeEvent, 0),
	}
	s.SeedDefaults()
	return s
}

const (
	DefaultAmberID  = "00000000-0000-4000-8000-000000000001"
	DefaultIndigoID = "00000000-0000-4000-8000-000000000002"
	DefaultFrostID  = "00000000-0000-4000-8000-000000000003"
	DefaultPulseID  = "00000000-0000-4000-8000-000000000004"
)

func (s *State) SeedDefaults() {
	if len(s.SampleTypes) == 0 {
		s.SampleTypes[DefaultAmberID] = &models.SampleType{
			SampleTypeID:               DefaultAmberID,
			Name:                       "Amber",
			QualifiedCollectorRequired: true,
			RequiredQualification:      "Amber",
			ContainerType:              "amber-vial",
			TemperatureMinC:            2,
			TemperatureMaxC:            8,
			IncompatibleSampleTypes:    []string{DefaultIndigoID},
			RequiresCooledRoute:        false,
			BatchingAllowed:            true,
		}
		s.SampleTypes[DefaultIndigoID] = &models.SampleType{
			SampleTypeID:               DefaultIndigoID,
			Name:                       "Indigo",
			QualifiedCollectorRequired: true,
			RequiredQualification:      "Indigo",
			ContainerType:              "indigo-tube",
			TemperatureMinC:            2,
			TemperatureMaxC:            8,
			IncompatibleSampleTypes:    []string{DefaultAmberID},
			RequiresCooledRoute:        false,
			BatchingAllowed:            true,
		}
		s.SampleTypes[DefaultFrostID] = &models.SampleType{
			SampleTypeID:               DefaultFrostID,
			Name:                       "Frost",
			QualifiedCollectorRequired: true,
			RequiredQualification:      "Frost",
			ContainerType:              "cryo-tube",
			TemperatureMinC:            -20,
			TemperatureMaxC:            4,
			IncompatibleSampleTypes:    []string{},
			RequiresCooledRoute:        true,
			BatchingAllowed:            true,
		}
		s.SampleTypes[DefaultPulseID] = &models.SampleType{
			SampleTypeID:               DefaultPulseID,
			Name:                       "Pulse",
			QualifiedCollectorRequired: true,
			RequiredQualification:      "Pulse",
			ContainerType:              "stat-tube",
			TemperatureMinC:            2,
			TemperatureMaxC:            8,
			IncompatibleSampleTypes:    []string{},
			RequiresCooledRoute:        false,
			BatchingAllowed:            false,
		}
	}
	if s.ServiceabilitySnapshot == nil {
		s.ServiceabilitySnapshot = &models.ServiceabilitySnapshot{
			Version:                    1,
			Status:                     "complete",
			ComputedAt:                 models.FormatTime(time.Now()),
			NetworkRevision:            0,
			Regions:                    []models.ServiceabilityRegion{},
			ActiveCollectionPointCount: 0,
		}
	}
}

func HashPassword(pw string) string {
	sum := sha256.Sum256([]byte("labsample-salt:" + pw))
	return hex.EncodeToString(sum[:])
}

type Store struct {
	mu          sync.RWMutex
	pool        *pgxpool.Pool
	state       *State
	subscribers map[chan *models.RealtimeEvent]struct{}
	subMu       sync.Mutex
}

