func ConnectPool(ctx context.Context) (*pgxpool.Pool, error) {
	dbURL := os.Getenv("DATABASE_URL")
	if dbURL == "" {
		dbURL = "postgresql://arena:arena@127.0.0.1:5432/arena?sslmode=disable"
	}
	return pgxpool.New(ctx, dbURL)
}

func ResetDatabase(ctx context.Context, pool *pgxpool.Pool) error {
	if _, err := pool.Exec(ctx, dropSQL); err != nil {
		return fmt.Errorf("drop tables: %w", err)
	}
	if _, err := pool.Exec(ctx, schemaSQL); err != nil {
		return fmt.Errorf("create schema: %w", err)
	}
	s := NewEmptyState()
	ensureInitialAdmin(s)
	return persistStateToDB(ctx, pool, s)
}

func ensureInitialAdmin(s *State) bool {
	if len(s.Users) > 0 {
		return false
	}
	adminUser := strings.TrimSpace(os.Getenv("ADMIN_USERNAME"))
	adminPass := os.Getenv("ADMIN_PASSWORD")
	if adminUser == "" || adminPass == "" {
		return false
	}
	uid := uuid.NewString()
	nowStr := models.FormatTime(time.Now())
	u := &models.User{
		UserID:         uid,
		Username:       adminUser,
		PasswordHash:   HashPassword(adminPass),
		FullName:       "System Administrator",
		Roles:          []string{"administrator"},
		Qualifications: []string{},
		Certifications: []models.Certification{},
		Active:         true,
		Available:      true,
		CapacityUnits:  10,
		CreatedAt:      nowStr,
	}
	s.Users[uid] = u
	return true
}

func NewStore(ctx context.Context, pool *pgxpool.Pool) (*Store, error) {
	if _, err := pool.Exec(ctx, schemaSQL); err != nil {
		return nil, fmt.Errorf("materialize schema: %w", err)
	}
	st := &Store{
		pool:        pool,
		subscribers: make(map[chan *models.RealtimeEvent]struct{}),
	}
	if err := st.loadFromDB(ctx); err != nil {
		return nil, err
	}
	return st, nil
}

func (st *Store) loadFromDB(ctx context.Context) error {
	st.mu.Lock()
	defer st.mu.Unlock()

	var raw []byte
	err := st.pool.QueryRow(ctx, `SELECT data FROM app_state WHERE id = 1`).Scan(&raw)
	if err == pgx.ErrNoRows {
		s := NewEmptyState()
		ensureInitialAdmin(s)
		st.state = s
		return persistStateToDB(ctx, st.pool, s)
	}
	if err != nil {
		return fmt.Errorf("load app_state: %w", err)
	}

	var s State
	if err := json.Unmarshal(raw, &s); err != nil {
		return fmt.Errorf("unmarshal app_state: %w", err)
	}
	ensureMaps(&s)
	s.SeedDefaults()
	if ensureInitialAdmin(&s) {
		if err := persistStateToDB(ctx, st.pool, &s); err != nil {
			return err
		}
	}
	st.state = &s
	return nil
}

func ensureMaps(s *State) {
	if s.Users == nil {
		s.Users = make(map[string]*models.User)
	}
	if s.Sessions == nil {
		s.Sessions = make(map[string]*models.Session)
	}
	if s.SampleTypes == nil {
		s.SampleTypes = make(map[string]*models.SampleType)
	}
	if s.Locations == nil {
		s.Locations = make(map[string]*models.Location)
	}
	if s.Connections == nil {
