type APIError struct {
	Status  int
	Code    string
	Message string
}

func (e *APIError) Error() string {
	return e.Code + ": " + e.Message
}

func NewErr(status int, code, msg string) *APIError {
	return &APIError{Status: status, Code: code, Message: msg}
}

func WriteJSON(w http.ResponseWriter, status int, payload interface{}) {
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(status)
	_ = json.NewEncoder(w).Encode(payload)
}

func WriteData(w http.ResponseWriter, status int, data interface{}) {
	WriteJSON(w, status, map[string]interface{}{"data": data})
}

func WriteError(w http.ResponseWriter, err error) {
	var apiErr *APIError
	if errors.As(err, &apiErr) {
		WriteJSON(w, apiErr.Status, map[string]string{
			"error": apiErr.Message,
			"code":  apiErr.Code,
		})
		return
	}
	WriteJSON(w, http.StatusInternalServerError, map[string]string{
		"error": err.Error(),
		"code":  "internal_error",
	})
}

func DecodeStrictJSON(r *http.Request, dst interface{}) ([]byte, *APIError) {
	body, err := io.ReadAll(r.Body)
	if err != nil {
		return nil, NewErr(http.StatusBadRequest, "invalid_json", "failed to read request body")
	}
	if len(bytes.TrimSpace(body)) == 0 {
		return nil, NewErr(http.StatusBadRequest, "invalid_json", "empty request body")
	}
	dec := json.NewDecoder(bytes.NewReader(body))
	dec.DisallowUnknownFields()
	if err := dec.Decode(dst); err != nil {
		return body, NewErr(http.StatusBadRequest, "invalid_json", "invalid json body: "+err.Error())
	}
	if dec.More() {
		return body, NewErr(http.StatusBadRequest, "invalid_json", "unexpected trailing json content")
	}
	return body, nil
}

func ParseTime(val string) (time.Time, bool) {
	val = strings.TrimSpace(val)
	if val == "" {
		return time.Time{}, false
	}
	if t, err := time.Parse(time.RFC3339Nano, val); err == nil {
		return t.UTC(), true
	}
	if t, err := time.Parse(time.RFC3339, val); err == nil {
		return t.UTC(), true
	}
	return time.Time{}, false
}

func ValidCoordinate(c models.Coordinate) bool {
	if math.IsNaN(c.Latitude) || math.IsNaN(c.Longitude) || math.IsInf(c.Latitude, 0) || math.IsInf(c.Longitude, 0) {
		return false
	}
	if c.Latitude < -90 || c.Latitude > 90 || c.Longitude < -180 || c.Longitude > 180 {
		return false
	}
	// Reject 0,0 if both are exactly 0? Wait: 0,0 is a valid coordinate on Earth unless out of range, so [-90,90] and [-180,180] is standard.
	return true
}

func DistanceKm(a, b models.Coordinate) float64 {
	const earthRadiusKm = 6371.0
	lat1 := a.Latitude * math.Pi / 180.0
	lat2 := b.Latitude * math.Pi / 180.0
	dLat := (b.Latitude - a.Latitude) * math.Pi / 180.0
	dLon := (b.Longitude - a.Longitude) * math.Pi / 180.0

	sinDLat := math.Sin(dLat / 2.0)
	sinDLon := math.Sin(dLon / 2.0)
	h := sinDLat*sinDLat + math.Cos(lat1)*math.Cos(lat2)*sinDLon*sinDLon
	if h > 1.0 {
		h = 1.0
	}
	if h < 0.0 {
		h = 0.0
	}
	return 2.0 * earthRadiusKm * math.Asin(math.Sqrt(h))
}

