func ExtractBearerToken(r *http.Request) string {
	auth := strings.TrimSpace(r.Header.Get("Authorization"))
	if strings.HasPrefix(strings.ToLower(auth), "bearer ") {
		return strings.TrimSpace(auth[7:])
	}
	if proto := strings.TrimSpace(r.Header.Get("Sec-WebSocket-Protocol")); proto != "" {
		parts := strings.Split(proto, ",")
		for _, p := range parts {
			p = strings.TrimSpace(p)
			if strings.HasPrefix(p, "bearer.") {
				return strings.TrimPrefix(p, "bearer.")
			}
			if strings.HasPrefix(strings.ToLower(p), "bearer ") {
				return strings.TrimSpace(p[7:])
			}
			if p != "" && p != "json" && p != "realtime" {
				return p
			}
		}
	}
	if tok := strings.TrimSpace(r.URL.Query().Get("token")); tok != "" {
		return tok
	}
	return ""
}

func AuthenticateSession(s *db.State, r *http.Request) (*models.User, *models.Session, *APIError) {
	token := ExtractBearerToken(r)
	if token == "" {
		return nil, nil, NewErr(http.StatusUnauthorized, "unauthorized", "missing bearer token")
	}
	sess, ok := s.Sessions[token]
	if !ok {
		return nil, nil, NewErr(http.StatusUnauthorized, "unauthorized", "invalid session token")
	}
	u, ok := s.Users[sess.UserID]
	if !ok || !u.Active {
		return nil, nil, NewErr(http.StatusUnauthorized, "unauthorized", "user not found or inactive")
	}
	return u, sess, nil
}

func RequireActiveRole(s *db.State, u *models.User, sess *models.Session, action, entityType, entityID string, allowRoleNotSelected409 bool, allowedRoles ...string) (string, *APIError) {
	role := sess.ActiveRole
	if role == "" {
		if len(u.Roles) == 1 {
			role = u.Roles[0]
			sess.ActiveRole = role
		} else {
			RecordAudit(s, u.UserID, "", "permission_check", entityType, entityID, false, models.FormatTime(time.Now()), map[string]interface{}{
				"attemptedAction": action,
				"reason":          "role_not_selected",
			})
			if allowRoleNotSelected409 {
				return "", NewErr(http.StatusConflict, "role_not_selected", "must explicitly select an active role before performing this action")
			}
			return "", NewErr(http.StatusForbidden, "forbidden", "must select an active role")
		}
	}
	// Verify user still holds this role
	holds := false
	for _, r := range u.Roles {
		if r == role {
			holds = true
			break
		}
	}
	if !holds {
		RecordAudit(s, u.UserID, role, "permission_check", entityType, entityID, false, models.FormatTime(time.Now()), map[string]interface{}{
			"attemptedAction": action,
			"reason":          "role_not_held",
		})
		return "", NewErr(http.StatusForbidden, "forbidden", "active role is no longer held by user")
	}
	if len(allowedRoles) > 0 {
		allowed := false
		for _, ar := range allowedRoles {
			if ar == role {
				allowed = true
				break
			}
		}
		if !allowed {
			RecordAudit(s, u.UserID, role, "permission_check", entityType, entityID, false, models.FormatTime(time.Now()), map[string]interface{}{
				"attemptedAction": action,
				"requiredRoles":   allowedRoles,
				"activeRole":      role,
			})
			return "", NewErr(http.StatusForbidden, "forbidden", "role not permitted for this action")
		}
	}
	return role, nil
}

func RecordAudit(s *db.State, actorID, role, action, entityType, entityID string, success bool, occurredAt string, details map[string]interface{}) models.TimelineEntry {
	if occurredAt == "" {
		occurredAt = models.FormatTime(time.Now())
	}
	if details == nil {
		details = map[string]interface{}{}
	}
	if actorID == "" {
		actorID = "anonymous"
	}
	if role == "" {
		role = "none"
	}
	if entityType == "" {
		entityType = "system"
	}
	if entityID == "" {
		entityID = "system"
	}
	seq := int64(len(s.AuditLog) + 1)
	auditID := uuid.NewString()
	entry := &models.AuditEntry{
		Seq:         seq,
		AuditID:     auditID,
		Audit_ID:    auditID,
		ActorID:     actorID,
		Actor_ID:    actorID,
		Role:        role,
