		EntityID:    entityID,
		Entity_ID:   entityID,
		Success:     success,
		OccurredAt:  occurredAt,
		Occurred_At: occurredAt,
		Details:     details,
	}
	s.AuditLog = append(s.AuditLog, entry)

	evID := s.NextTimelineEventID
	s.NextTimelineEventID++
	return models.TimelineEntry{
		EventID:    evID,
		Action:     action,
		ActorID:    actorID,
		Role:       role,
		EntityType: entityType,
		EntityID:   entityID,
