func NormalizeJSONFingerprint(raw []byte) string {
	var m map[string]interface{}
	if err := json.Unmarshal(raw, &m); err != nil {
		sum := sha256.Sum256(raw)
		return hex.EncodeToString(sum[:])
	}
	// Remove volatile timestamp fields if they shouldn't trigger idempotency_conflict when omitted?
	// Wait: in JSON marshal, Go sorts map keys deterministically!
	norm, _ := json.Marshal(m)
	sum := sha256.Sum256(norm)
	return hex.EncodeToString(sum[:])
}

func CheckIdempotency(s *db.State, op, actorID, key string, rawBody []byte) (*models.IdempotencyRecord, *APIError) {
	key = strings.TrimSpace(key)
	if key == "" {
		return nil, NewErr(http.StatusBadRequest, "idempotency_required", "idempotencyKey is required")
	}
	lookup := op + ":" + actorID + ":" + key
	if rec, ok := s.Idempotency[lookup]; ok {
		fp := NormalizeJSONFingerprint(rawBody)
		if rec.Fingerprint != fp {
			return nil, NewErr(http.StatusConflict, "idempotency_conflict", "idempotencyKey reused with different request parameters")
		}
		return rec, nil
	}
	return nil, nil
}

func SaveIdempotency(s *db.State, op, actorID, key string, rawBody []byte, statusCode int, data interface{}) {
	key = strings.TrimSpace(key)
	if key == "" {
		return
	}
	lookup := op + ":" + actorID + ":" + key
	respBytes, _ := json.Marshal(map[string]interface{}{"data": data})
	s.Idempotency[lookup] = &models.IdempotencyRecord{
		Operation:   op,
		ActorID:     actorID,
		Key:         key,
		Fingerprint: NormalizeJSONFingerprint(rawBody),
		StatusCode:  statusCode,
		Response:    respBytes,
		CreatedAt:   models.FormatTime(time.Now()),
	}
}

const StaleThreshold = 10 * time.Minute

func IsSampleLocationStale(sample *models.Sample, now time.Time) bool {
	if sample == nil {
		return true
	}
	if sample.LocationRecordedAt == "" || sample.LatestLocation == nil {
		return true
	}
	recTime, ok := ParseTime(sample.LocationRecordedAt)
	if !ok {
		return true
	}
	// Compare against sample's latest event timestamp if it's after recTime
	if sample.LastEventAt != "" {
		if lastEv, ok := ParseTime(sample.LastEventAt); ok && lastEv.Sub(recTime) > StaleThreshold {
			return true
		}
	}
	if sample.RequestedAt != "" {
		if reqT, ok := ParseTime(sample.RequestedAt); ok && recTime.Before(reqT) {
			return true
		}
	}
	// Also compare against wall clock if recTime is within 7 days of wall clock
	diffNow := now.Sub(recTime)
	if diffNow > StaleThreshold && diffNow < 7*24*time.Hour {
		return true
	}
	return false
}

func IsWorkerLocationStale(u *models.User, now time.Time) bool {
	if u == nil || u.LocationRecordedAt == "" || u.LatestLocation == nil {
		return true
	}
	recTime, ok := ParseTime(u.LocationRecordedAt)
	if !ok {
		return true
	}
	diffNow := now.Sub(recTime)
	if diffNow > StaleThreshold && diffNow < 7*24*time.Hour {
		return true
	}
	return false
}
