func AreSampleTypesIncompatible(s *db.State, st1, st2 *models.SampleType, samp1, samp2 *models.Sample) bool {
	if st1 == nil || st2 == nil {
		return false
	}
	// Named rule: Indigo must not share a container/batch with an Amber sample
	if (strings.EqualFold(st1.Name, "Amber") && strings.EqualFold(st2.Name, "Indigo")) ||
		(strings.EqualFold(st1.Name, "Indigo") && strings.EqualFold(st2.Name, "Amber")) {
