	for _, id := range st2.IncompatibleSampleTypes {
		if id == st1.SampleTypeID {
			return true
		}
	}
	if samp1 != nil && samp2 != nil {
		for _, id := range samp1.IncompatibleSampleTypes {
			if id == samp2.SampleTypeID {
				return true
			}
		}
		for _, id := range samp2.IncompatibleSampleTypes {
			if id == samp1.SampleTypeID {
				return true
			}
		}
		// Check overlapping temperature range
		minT := math.Max(samp1.TemperatureMinC, samp2.TemperatureMinC)
		maxT := math.Min(samp1.TemperatureMaxC, samp2.TemperatureMaxC)
		if minT > maxT {
