func RecomputeServiceabilitySnapshot(s *db.State) {
	s.NetworkRevision++
	s.ServiceabilityVersion++

	regions := make([]models.ServiceabilityRegion, 0)
	for _, loc := range s.Locations {
		if loc.Active && loc.Functions.CollectionPoint {
			regions = append(regions, models.ServiceabilityRegion{
				LocationID: loc.LocationID,
				Name:       loc.Name,
				Latitude:   loc.Coordinate.Latitude,
				Longitude:  loc.Coordinate.Longitude,
				CoverageKm: loc.CoverageKm,
			})
		}
	}
	sort.Slice(regions, func(i, j int) bool {
		if regions[i].Name != regions[j].Name {
			return regions[i].Name < regions[j].Name
		}
		return regions[i].LocationID < regions[j].LocationID
	})

	s.ServiceabilitySnapshot = &models.ServiceabilitySnapshot{
		Version:                    s.ServiceabilityVersion,
		Status:                     "complete",
		ComputedAt:                 models.FormatTime(time.Now()),
		NetworkRevision:            s.NetworkRevision,
		Regions:                    regions,
		ActiveCollectionPointCount: len(regions),
	}
}

func GetLocationCapacity(loc *models.Location) models.Capacity {
	avail := loc.CapacityUnits - loc.ReservedUnits
	if avail < 0 {
		avail = 0
	}
	cooledAvail := loc.CooledCapacityUnits - loc.CooledReservedUnits
	if cooledAvail < 0 {
		cooledAvail = 0
	}
	return models.Capacity{
		CapacityUnits:        loc.CapacityUnits,
		ReservedUnits:        loc.ReservedUnits,
		AvailableUnits:       avail,
		CooledCapacityUnits:  loc.CooledCapacityUnits,
		CooledReservedUnits:  loc.CooledReservedUnits,
		CooledAvailableUnits: cooledAvail,
	}
}

func GetConnectionCapacity(conn *models.Connection) models.Capacity {
	avail := conn.CapacityUnits - conn.ReservedUnits
	if avail < 0 {
		avail = 0
	}
	cooledAvail := conn.CooledCapacityUnits - conn.CooledReservedUnits
	if cooledAvail < 0 {
		cooledAvail = 0
	}
	return models.Capacity{
		CapacityUnits:        conn.CapacityUnits,
		ReservedUnits:        conn.ReservedUnits,
		AvailableUnits:       avail,
		CooledCapacityUnits:  conn.CooledCapacityUnits,
		CooledReservedUnits:  conn.CooledReservedUnits,
		CooledAvailableUnits: cooledAvail,
	}
}

func LocationHasCapacity(loc *models.Location, units int, cooled bool) bool {
	if loc == nil {
		return false
	}
	if cooled {
		return (loc.CooledCapacityUnits - loc.CooledReservedUnits) >= units
	}
	return (loc.CapacityUnits - loc.ReservedUnits) >= units
}

func ConnectionHasCapacity(conn *models.Connection, units int, cooled bool) bool {
	if conn == nil {
		return false
	}
	if cooled {
		if !conn.Cooled {
			return false
		}
		return (conn.CooledCapacityUnits - conn.CooledReservedUnits) >= units
	}
	return (conn.CapacityUnits - conn.ReservedUnits) >= units
}

func LabAcceptsSampleType(s *db.State, labID, sampleTypeID string) bool {
	for _, acc := range s.LabAcceptances {
		if acc.LaboratoryID == labID && acc.SampleTypeID == sampleTypeID {
			return acc.Accepts
		}
	}
	return false
}

type RoutePath struct {
	LocationIDs   []string
	ConnectionIDs []string
	TotalMinutes  int
	TotalCost     float64
	ArrivalAt     time.Time
	AllCooled     bool
	HasCapacity   bool
	CooledCapFail bool
}

func FindRoutes(s *db.State, startNodeIDs []string, acceptingLabIDs map[string]bool, requiresCooled bool, units int, startTime time.Time) []RoutePath {
	var results []RoutePath

	type queueItem struct {
		locIDs        []string
		connIDs       []string
		visited       map[string]bool
		totalMinutes  int
		totalCost     float64
		allCooled     bool
		hasCap        bool
		cooledCapFail bool
	}

	var queue []queueItem
	for _, startID := range startNodeIDs {
		loc, ok := s.Locations[startID]
		if !ok || !loc.Active {
			continue
		}
		hasCap := LocationHasCapacity(loc, units, requiresCooled)
		cooledFail := requiresCooled && !hasCap
		queue = append(queue, queueItem{
			locIDs:        []string{startID},
			connIDs:       []string{},
			visited:       map[string]bool{startID: true},
			totalMinutes:  loc.HandlingMinutes,
			totalCost:     0,
			allCooled:     true,
			hasCap:        hasCap,
			cooledCapFail: cooledFail,
		})
	}

	for len(queue) > 0 {
		curr := queue[0]
		queue = queue[1:]
		lastLocID := curr.locIDs[len(curr.locIDs)-1]

		if acceptingLabIDs[lastLocID] && len(curr.connIDs) >= 1 {
			results = append(results, RoutePath{
				LocationIDs:   curr.locIDs,
				ConnectionIDs: curr.connIDs,
				TotalMinutes:  curr.totalMinutes,
				TotalCost:     curr.totalCost,
				ArrivalAt:     startTime.Add(time.Duration(curr.totalMinutes) * time.Minute),
				AllCooled:     curr.allCooled,
				HasCapacity:   curr.hasCap,
				CooledCapFail: curr.cooledCapFail,
			})
		}

		if len(curr.locIDs) >= 8 {
			continue
		}

		// Expand outgoing active connections
		for _, conn := range s.Connections {
			if !conn.Active || conn.FromLocationID != lastLocID {
				continue
			}
			if curr.visited[conn.ToLocationID] {
				continue
			}
			nextLoc, ok := s.Locations[conn.ToLocationID]
			if !ok || !nextLoc.Active {
				continue
			}
			isLab := acceptingLabIDs[nextLoc.LocationID]
			isIntermediate := nextLoc.Functions.TransferPoint || nextLoc.Functions.Hub || nextLoc.Functions.CollectionPoint
			if !isLab && !isIntermediate {
				continue
			}

			newVisited := make(map[string]bool, len(curr.visited)+1)
			for k, v := range curr.visited {
				newVisited[k] = v
			}
			newVisited[nextLoc.LocationID] = true

			newLocs := append(append([]string(nil), curr.locIDs...), nextLoc.LocationID)
			newConns := append(append([]string(nil), curr.connIDs...), conn.ConnectionID)

			allCooled := curr.allCooled && conn.Cooled
			connCapOk := ConnectionHasCapacity(conn, units, requiresCooled)
			locCapOk := LocationHasCapacity(nextLoc, units, requiresCooled)
			hasCap := curr.hasCap && connCapOk && locCapOk
			cooledFail := curr.cooledCapFail || (requiresCooled && (!connCapOk || !locCapOk))

			queue = append(queue, queueItem{
				locIDs:        newLocs,
				connIDs:       newConns,
				visited:       newVisited,
				totalMinutes:  curr.totalMinutes + conn.TravelMinutes + nextLoc.HandlingMinutes,
				totalCost:     curr.totalCost + conn.CostUnits,
				allCooled:     allCooled,
				hasCap:        hasCap,
				cooledCapFail: cooledFail,
			})
		}
	}

	// Also handle single-location case where startLoc itself is an accepting lab and no multi-node route exists
	if len(results) == 0 {
		for _, startID := range startNodeIDs {
			if acceptingLabIDs[startID] {
				loc := s.Locations[startID]
				if loc != nil && loc.Active && loc.Functions.CollectionPoint && loc.Functions.Laboratory {
					// Check if any connections exist in the network; only allow 0-hop if startID is both collection_point & lab and no outgoing connections exist
					hasOutgoing := false
					for _, conn := range s.Connections {
						if conn.Active && conn.FromLocationID == startID {
							hasOutgoing = true
							break
						}
					}
					if !hasOutgoing {
						hasCap := LocationHasCapacity(loc, units, requiresCooled)
						results = append(results, RoutePath{
							LocationIDs:   []string{startID},
							ConnectionIDs: []string{},
							TotalMinutes:  loc.HandlingMinutes,
							TotalCost:     0,
							ArrivalAt:     startTime.Add(time.Duration(loc.HandlingMinutes) * time.Minute),
							AllCooled:     true,
							HasCapacity:   hasCap,
							CooledCapFail: requiresCooled && !hasCap,
						})
					}
				}
			}
		}
	}

	sort.Slice(results, func(i, j int) bool {
		if results[i].TotalCost != results[j].TotalCost {
			return results[i].TotalCost < results[j].TotalCost
		}
		if !results[i].ArrivalAt.Equal(results[j].ArrivalAt) {
			return results[i].ArrivalAt.Before(results[j].ArrivalAt)
		}
		if len(results[i].LocationIDs) != len(results[j].LocationIDs) {
			return len(results[i].LocationIDs) < len(results[j].LocationIDs)
		}
		return strings.Join(results[i].LocationIDs, ",") < strings.Join(results[j].LocationIDs, ",")
	})

	return results
}

type ServiceabilityInput struct {
	Origin               models.Coordinate
	OriginType           string
	OriginNodeID         string
	SampleTypeID         string
	RequestedAt          time.Time
	DeliveryDeadline     time.Time
	EarliestCollectionAt time.Time
	LatestCollectionAt   time.Time
	Units                int
}

type ServiceabilityOutcome struct {
	Serviceable           bool
	Reason                string
	TargetLaboratoryID    string
	EstimatedArrivalAt    string
	ServiceabilityVersion int
	BestRoute             *RoutePath
}

func EvaluateServiceability(s *db.State, in ServiceabilityInput) (ServiceabilityOutcome, *APIError) {
	ver := 1
	if s.ServiceabilitySnapshot != nil {
		ver = s.ServiceabilitySnapshot.Version
	}
	st, ok := s.SampleTypes[in.SampleTypeID]
	if !ok {
		return ServiceabilityOutcome{}, NewErr(http.StatusNotFound, "not_found", "sample type not found")
	}
	if in.Units <= 0 {
		in.Units = 1
	}

	// Step 1: Candidate active collection nodes within coverage (<= 5km and <= loc.CoverageKm)
	var candidateStarts []string
	if in.OriginNodeID != "" {
		loc, exists := s.Locations[in.OriginNodeID]
		if !exists {
			return ServiceabilityOutcome{}, NewErr(http.StatusNotFound, "not_found", "originNodeId not found")
		}
		maxCov := loc.CoverageKm
		if maxCov <= 0 || maxCov > 5.0 {
			maxCov = 5.0
		}
		dist := DistanceKm(in.Origin, loc.Coordinate)
		canStart := loc.Active && (loc.Functions.CollectionPoint || (in.OriginType == "node" && (loc.Functions.TransferPoint || loc.Functions.Hub)))
		if canStart && dist <= maxCov && dist <= 5.0001 {
			candidateStarts = append(candidateStarts, loc.LocationID)
		}
	} else {
		type startDist struct {
			id   string
			dist float64
		}
		var starts []startDist
		for _, loc := range s.Locations {
			if !loc.Active || !loc.Functions.CollectionPoint {
				continue
			}
			maxCov := loc.CoverageKm
			if maxCov <= 0 || maxCov > 5.0 {
				maxCov = 5.0
			}
			dist := DistanceKm(in.Origin, loc.Coordinate)
			if dist <= maxCov && dist <= 5.0001 {
				starts = append(starts, startDist{id: loc.LocationID, dist: dist})
			}
		}
		sort.Slice(starts, func(i, j int) bool {
			if math.Abs(starts[i].dist-starts[j].dist) > 1e-6 {
				return starts[i].dist < starts[j].dist
			}
			return starts[i].id < starts[j].id
		})
		for _, sd := range starts {
			candidateStarts = append(candidateStarts, sd.id)
		}
	}

	if len(candidateStarts) == 0 {
		return ServiceabilityOutcome{
			Serviceable:           false,
			Reason:                "outside_service_coverage",
			ServiceabilityVersion: ver,
		}, nil
	}

	// Step 2: Candidate active laboratories accepting sampleTypeId
	acceptingLabs := make(map[string]bool)
	for _, loc := range s.Locations {
		if loc.Active && loc.Functions.Laboratory && LabAcceptsSampleType(s, loc.LocationID, in.SampleTypeID) {
			acceptingLabs[loc.LocationID] = true
		}
	}
	if len(acceptingLabs) == 0 {
		return ServiceabilityOutcome{
			Serviceable:           false,
			Reason:                "no_accepting_laboratory",
			ServiceabilityVersion: ver,
		}, nil
	}

	// Step 3: Check generic handling rule validity on the sampleType
	if st.TemperatureMinC > st.TemperatureMaxC || strings.TrimSpace(st.ContainerType) == "" {
		return ServiceabilityOutcome{
			Serviceable:           false,
			Reason:                "handling_rules_unsatisfiable",
			ServiceabilityVersion: ver,
		}, nil
	}

	requiresCooled := SampleTypeRequiresCooled(st)
	startTime := in.RequestedAt
	if in.EarliestCollectionAt.After(startTime) {
		startTime = in.EarliestCollectionAt
	}
	if startTime.After(in.LatestCollectionAt) {
		return ServiceabilityOutcome{
			Serviceable:           false,
			Reason:                "deadline_unreachable",
			ServiceabilityVersion: ver,
		}, nil
	}

	// Step 4: Find all routes in active topology
	allRoutes := FindRoutes(s, candidateStarts, acceptingLabs, requiresCooled, in.Units, startTime)
	if len(allRoutes) == 0 {
		return ServiceabilityOutcome{
			Serviceable:           false,
			Reason:                "no_route",
			ServiceabilityVersion: ver,
		}, nil
	}

	// Step 5: Filter by cooling / handling rules
	var handlingCompatible []RoutePath
	for _, r := range allRoutes {
		if requiresCooled && !r.AllCooled {
			continue
		}
		handlingCompatible = append(handlingCompatible, r)
	}
	if len(handlingCompatible) == 0 {
		return ServiceabilityOutcome{
			Serviceable:           false,
			Reason:                "handling_rules_unsatisfiable",
			ServiceabilityVersion: ver,
		}, nil
	}

	// Step 6: Filter by capacity
	var capCompatible []RoutePath
	for _, r := range handlingCompatible {
		if r.HasCapacity {
			capCompatible = append(capCompatible, r)
		}
	}
	if len(capCompatible) == 0 {
		return ServiceabilityOutcome{
			Serviceable:           false,
			Reason:                "insufficient_capacity",
			ServiceabilityVersion: ver,
		}, nil
	}

	// Step 7: Filter by deliveryDeadline
	var validRoutes []RoutePath
	for _, r := range capCompatible {
		if !r.ArrivalAt.After(in.DeliveryDeadline) {
			validRoutes = append(validRoutes, r)
		}
	}
	if len(validRoutes) == 0 {
		return ServiceabilityOutcome{
			Serviceable:           false,
			Reason:                "deadline_unreachable",
			ServiceabilityVersion: ver,
		}, nil
	}

	best := validRoutes[0]
	targetLabID := best.LocationIDs[len(best.LocationIDs)-1]
	return ServiceabilityOutcome{
		Serviceable:           true,
		Reason:                "serviceable",
		TargetLaboratoryID:    targetLabID,
		EstimatedArrivalAt:    models.FormatTime(best.ArrivalAt),
		ServiceabilityVersion: ver,
		BestRoute:             &best,
	}, nil
}

func ReserveCapacityForSampleOnRoute(s *db.State, journeyID, sampleID string, locIDs, connIDs []string, cooled bool) {
	seenLoc := make(map[string]bool)
	for _, locID := range locIDs {
		if seenLoc[locID] {
			continue
		}
		seenLoc[locID] = true
		if loc, ok := s.Locations[locID]; ok {
			if cooled {
				loc.CooledReservedUnits++
			} else {
				loc.ReservedUnits++
			}
			resID := uuid.NewString()
			s.Reservations[resID] = &models.CapacityReservation{
				ReservationID: resID,
				JourneyID:     journeyID,
				SampleID:      sampleID,
				ResourceType:  "location",
				ResourceID:    locID,
				Units:         1,
				Cooled:        cooled,
				Released:      false,
			}
		}
	}
	seenConn := make(map[string]bool)
	for _, connID := range connIDs {
		if seenConn[connID] {
			continue
		}
		seenConn[connID] = true
		if conn, ok := s.Connections[connID]; ok {
			if cooled {
				conn.CooledReservedUnits++
			} else {
				conn.ReservedUnits++
			}
			resID := uuid.NewString()
			s.Reservations[resID] = &models.CapacityReservation{
				ReservationID: resID,
				JourneyID:     journeyID,
				SampleID:      sampleID,
				ResourceType:  "connection",
				ResourceID:    connID,
				Units:         1,
				Cooled:        cooled,
				Released:      false,
			}
		}
	}
}

func ReleaseReservationRecord(s *db.State, res *models.CapacityReservation) {
	if res == nil || res.Released {
		return
	}
	res.Released = true
	switch res.ResourceType {
	case "location":
		if loc, ok := s.Locations[res.ResourceID]; ok {
			if res.Cooled {
				loc.CooledReservedUnits -= res.Units
				if loc.CooledReservedUnits < 0 {
					loc.CooledReservedUnits = 0
				}
			} else {
				loc.ReservedUnits -= res.Units
				if loc.ReservedUnits < 0 {
					loc.ReservedUnits = 0
				}
			}
		}
	case "connection":
		if conn, ok := s.Connections[res.ResourceID]; ok {
			if res.Cooled {
				conn.CooledReservedUnits -= res.Units
				if conn.CooledReservedUnits < 0 {
					conn.CooledReservedUnits = 0
				}
			} else {
				conn.ReservedUnits -= res.Units
				if conn.ReservedUnits < 0 {
					conn.ReservedUnits = 0
				}
			}
		}
	}
}

func ReleaseSampleCapacity(s *db.State, sampleID string) {
	for _, res := range s.Reservations {
		if res.SampleID == sampleID && !res.Released {
			ReleaseReservationRecord(s, res)
		}
	}
}

func ReleaseJourneyCapacity(s *db.State, journeyID string) {
	for _, res := range s.Reservations {
		if res.JourneyID == journeyID && !res.Released {
			ReleaseReservationRecord(s, res)
		}
	}
}

func ReleaseResourceReservationForSample(s *db.State, sampleID, resourceType, resourceID string) {
	for _, res := range s.Reservations {
		if res.SampleID == sampleID && res.ResourceType == resourceType && res.ResourceID == resourceID && !res.Released {
			ReleaseReservationRecord(s, res)
		}
	}
}

func UserHasRole(u *models.User, role string) bool {
	if u == nil {
		return false
	}
	for _, r := range u.Roles {
		if r == role {
			return true
		}
	}
	return false
}

func WorkerHasValidQualification(u *models.User, st *models.SampleType, refTime time.Time) (bool, string) {
	if u == nil {
		return false, "ineligible_worker"
	}
	if st == nil || !st.QualifiedCollectorRequired {
		return true, ""
	}
	reqQual := strings.TrimSpace(st.RequiredQualification)
	if reqQual == "" {
		reqQual = strings.TrimSpace(st.Name)
	}
	// Check explicit certifications first if matching code exists
	foundCertMatch := false
	for _, cert := range u.Certifications {
		if strings.EqualFold(cert.Code, reqQual) || strings.EqualFold(cert.Code, st.Name) {
			foundCertMatch = true
			if !cert.Active {
				return false, "certification_inactive"
			}
			if cert.ExpiresAt != nil && *cert.ExpiresAt != "" {
				if expT, ok := ParseTime(*cert.ExpiresAt); ok && !refTime.IsZero() && refTime.After(expT) {
					return false, "certification_inactive"
				}
			}
			return true, ""
		}
	}
	if foundCertMatch {
		return false, "certification_inactive"
	}
	for _, q := range u.Qualifications {
		if strings.EqualFold(q, reqQual) || strings.EqualFold(q, st.Name) {
			return true, ""
		}
	}
	return false, "ineligible_worker"
}

func ActiveWorkerAssignmentCount(s *db.State, workerID string) int {
	count := 0
	for _, a := range s.Assignments {
		if (a.WorkerID == workerID || a.OfferedToWorkerID == workerID) &&
			a.Status != "completed" && a.Status != "cancelled" && a.Status != "declined" {
			// Check journey is active
			if j, ok := s.Journeys[a.JourneyID]; ok && j.Status == "active" {
				count++
			}
		}
	}
	return count
}

func ActiveWorkerSampleLoad(s *db.State, workerID string) int {
	load := 0
	for _, a := range s.Assignments {
		if (a.WorkerID == workerID || a.OfferedToWorkerID == workerID) &&
			a.Status != "completed" && a.Status != "cancelled" && a.Status != "declined" {
			if j, ok := s.Journeys[a.JourneyID]; ok && j.Status == "active" {
				n := len(a.SampleIDs)
				if n == 0 {
					n = len(j.SampleIDs)
				}
				if n == 0 {
					n = 1
				}
				load += n
			}
		}
	}
	return load
}

func IsWorkerEligibleForAssignment(s *db.State, u *models.User, a *models.Assignment, refTime time.Time, checkAvailability bool) (bool, string) {
	if u == nil || !u.Active {
		return false, "ineligible_worker"
	}
	if checkAvailability && !u.Available {
		return false, "worker_unavailable"
	}
	batchSize := len(a.SampleIDs)
	if batchSize == 0 {
		if j, ok := s.Journeys[a.JourneyID]; ok && len(j.SampleIDs) > 0 {
			batchSize = len(j.SampleIDs)
		} else {
			batchSize = 1
		}
	}

	switch a.Kind {
	case "collection":
		if !UserHasRole(u, "collection_professional") {
			return false, "ineligible_worker"
		}
		var st *models.SampleType
		if a.ExpectedSampleTypeID != "" {
			st = s.SampleTypes[a.ExpectedSampleTypeID]
		} else if samp, ok := s.Samples[a.SampleID]; ok {
			st = s.SampleTypes[samp.SampleTypeID]
		}
		if ok, reason := WorkerHasValidQualification(u, st, refTime); !ok {
			return false, reason
		}
	case "transport":
		if !UserHasRole(u, "delivery_partner") {
			return false, "ineligible_worker"
		}
		// Check sample compatibility with collector/transport if worker has capacity limit
		if u.CapacityConfigured && u.CapacityUnits < batchSize {
			return false, "capacity_exceeded"
		}
		if !u.CapacityConfigured && u.CapacityUnits > 0 && u.CapacityUnits < batchSize {
			return false, "capacity_exceeded"
		}
	case "node":
		if !UserHasRole(u, "node_handler") {
			return false, "ineligible_worker"
		}
		if u.AssignedLocationID == "" || u.AssignedLocationID != a.NodeID {
			return false, "ineligible_worker"
		}
	case "laboratory":
		if !UserHasRole(u, "laboratory_team") {
			return false, "ineligible_worker"
		}
		if u.AssignedLocationID == "" || u.AssignedLocationID != a.LaboratoryID {
			return false, "ineligible_worker"
		}
	default:
		return false, "ineligible_worker"
	}

	if checkAvailability && u.CapacityConfigured && u.CapacityUnits == 0 {
		return false, "capacity_exceeded"
	}
	return true, ""
}

func OfferAssignmentToBestWorker(s *db.State, a *models.Assignment, refTime time.Time, excludeWorkerID string) *models.User {
	if refTime.IsZero() {
		refTime = time.Now().UTC()
	}
	type candidate struct {
		user            *models.User
		declinedThisOne bool
		activeLoad      int
		declinePenalty  int
	}
	var cands []candidate
	for _, u := range s.Users {
		if u.UserID == excludeWorkerID {
			continue
		}
		ok, _ := IsWorkerEligibleForAssignment(s, u, a, refTime, true)
		if !ok {
			continue
		}
		// Check if worker has remaining capacity for transport/collection
		activeLoad := ActiveWorkerAssignmentCount(s, u.UserID)
		if u.CapacityConfigured && activeLoad >= u.CapacityUnits {
			continue
		}

		declinedThis := false
		for _, dID := range a.DeclinedByWorkerIDs {
			if dID == u.UserID {
				declinedThis = true
				break
			}
		}
		penalty := u.DeclineCount
		if u.LastDeclinedAt != "" {
			if dt, ok := ParseTime(u.LastDeclinedAt); ok && refTime.Sub(dt) > 30*time.Minute {
				penalty = 0 // Decline penalty decays after a limited time
			}
		}
		cands = append(cands, candidate{
			user:            u,
			declinedThisOne: declinedThis,
			activeLoad:      activeLoad,
			declinePenalty:  penalty,
		})
	}

	if len(cands) == 0 {
		a.OfferedToWorkerID = ""
		a.WorkerID = ""
		return nil
	}

	sort.Slice(cands, func(i, j int) bool {
		if cands[i].declinedThisOne != cands[j].declinedThisOne {
			return !cands[i].declinedThisOne
		}
		scoreI := cands[i].activeLoad + cands[i].declinePenalty
		scoreJ := cands[j].activeLoad + cands[j].declinePenalty
		if scoreI != scoreJ {
			return scoreI < scoreJ
		}
		if cands[i].user.RecentAssignmentCount != cands[j].user.RecentAssignmentCount {
			return cands[i].user.RecentAssignmentCount < cands[j].user.RecentAssignmentCount
		}
		if cands[i].user.LastAssignedSeq != cands[j].user.LastAssignedSeq {
			return cands[i].user.LastAssignedSeq < cands[j].user.LastAssignedSeq
		}
		return cands[i].user.UserID < cands[j].user.UserID
	})

	chosen := cands[0].user
	a.OfferedToWorkerID = chosen.UserID
	a.WorkerID = chosen.UserID
	a.Status = "pending"
	a.OfferedAt = models.FormatTime(refTime)
	a.OfferExpiresAt = models.FormatTime(refTime.Add(15 * time.Minute))
	chosen.RecentAssignmentCount++
	chosen.LastAssignedSeq = s.NextAssignmentSeq
	s.NextAssignmentSeq++

	te := RecordAudit(s, "system", "system", "offer_assignment", "assignment", a.AssignmentID, true, a.OfferedAt, map[string]interface{}{
		"assignmentId":   a.AssignmentID,
		"sampleId":       a.SampleID,
		"journeyId":      a.JourneyID,
		"kind":           a.Kind,
		"offeredTo":      chosen.UserID,
		"offerExpiresAt": a.OfferExpiresAt,
	})
	AppendAssignmentHistory(a, te)
	if samp, ok := s.Samples[a.SampleID]; ok {
		AppendSampleTimeline(samp, te)
	}
	if j, ok := s.Journeys[a.JourneyID]; ok {
		AppendJourneyHistory(j, te)
	}
	return chosen
}

func FlagNoQualifiedWorkerException(s *db.State, sample *models.Sample, a *models.Assignment, occurredAt string) {
	if sample == nil {
		return
	}
	if occurredAt == "" {
		occurredAt = models.FormatTime(time.Now())
	}
	excID := uuid.NewString()
	reason := "no_qualified_worker"
	sample.Status = "exception"
	sample.Exception = map[string]interface{}{
		"exceptionId":  excID,
		"sampleId":     sample.SampleID,
		"assignmentId": a.AssignmentID,
		"kind":         a.Kind,
		"reason":       reason,
		"code":         reason,
		"observedAt":   occurredAt,
	}
	s.Exceptions[excID] = &models.ExceptionRecord{
		ExceptionID: excID,
		SampleID:    sample.SampleID,
		Reason:      reason,
		Status:      "exception",
		ObservedAt:  occurredAt,
	}
	te := RecordAudit(s, "system", "system", "flag_exception", "sample", sample.SampleID, true, occurredAt, map[string]interface{}{
		"exceptionId":  excID,
		"sampleId":     sample.SampleID,
		"assignmentId": a.AssignmentID,
		"reason":       reason,
	})
	AppendSampleTimeline(sample, te)
	EmitEvent(s, "sample.exception", "sample", sample.SampleID, map[string]interface{}{
		"sampleId":    sample.SampleID,
		"exceptionId": excID,
		"reason":      reason,
	})
}

func TryOfferPendingAssignments(s *db.State, refTime time.Time) {
	if refTime.IsZero() {
		refTime = time.Now().UTC()
	}
	// Sort assignments deterministically
	var list []*models.Assignment
	for _, a := range s.Assignments {
		if a.Status == "pending" && a.OfferedToWorkerID == "" {
			if j, ok := s.Journeys[a.JourneyID]; ok && j.Status == "active" {
				list = append(list, a)
			}
		}
	}
	sort.Slice(list, func(i, j int) bool {
		if list[i].Sequence != list[j].Sequence {
			return list[i].Sequence < list[j].Sequence
		}
		return list[i].AssignmentID < list[j].AssignmentID
	})
	for _, a := range list {
		chosen := OfferAssignmentToBestWorker(s, a, refTime, "")
		if chosen != nil {
			if samp, ok := s.Samples[a.SampleID]; ok {
				if samp.Status == "exception" && samp.Exception != nil && samp.Exception["reason"] == "no_qualified_worker" {
					// Check if all required assignments for this sample now have an offered/assigned worker
					if samp.Sealed {
						samp.Status = "sealed"
					} else {
						samp.Status = "scheduled"
					}
					for eid, ex := range s.Exceptions {
						if ex.SampleID == samp.SampleID && ex.Reason == "no_qualified_worker" {
							delete(s.Exceptions, eid)
						}
					}
					samp.Exception = nil
				}
			}
		}
	}
}
