{"file_text":"package api

import (
	"time"

	"github.com/google/uuid"
	"labsample/internal/db"
	"labsample/internal/models"
)

func BuildJourneyFromRoute(s *db.State, sample *models.Sample, route RoutePath, startTime time.Time, includeCollection bool, registeringUser *models.User, registeringRole string) *models.Journey {
	journeyID := uuid.NewString()
	st := s.SampleTypes[sample.SampleTypeID]
	cooled := SampleTypeRequiresCooled(st)

	// Build orderedStops
	stops := make([]models.JourneyStop, 0, len(route.LocationIDs)+1)
	elapsedMin := 0
	for i, locID := range route.LocationIDs {
		loc := s.Locations[locID]
		if i > 0 {
			conn := s.Connections[route.ConnectionIDs[i-1]]
			if conn != nil {
				elapsedMin += conn.TravelMinutes
			}
		}
		dwell := 0
		var coord *models.Coordinate
		if loc != nil {
			dwell = loc.HandlingMinutes
			c := loc.Coordinate
			coord = &c
		}
		elapsedMin += dwell
		estStr := models.FormatTime(startTime.Add(time.Duration(elapsedMin) * time.Minute))
		stopType := "handoff"
		if i == 0 {
			stopType = "pickup"
		} else if i == len(route.LocationIDs)-1 {
			stopType = "delivery"
		}
		dwellCopy := dwell
		stops = append(stops, models.JourneyStop{
			StopID:       uuid.NewString(),
			LocationID:   locID,
			Location_ID:  locID,
			StopType:     stopType,
			Stop_Type:    stopType,
			Sequence:     i + 1,
			EstimatedAt:  estStr,
			Estimated_At: estStr,
			DwellMinutes: &dwellCopy,
			Coordinate:   coord,
		})
	}
	if len(route.LocationIDs) == 1 {
		locID := route.LocationIDs[0]
		loc := s.Locations[locID]
		dwell := 0
		var coord *models.Coordinate
		if loc != nil {
			dwell = loc.HandlingMinutes
			c := loc.Coordinate
			coord = &c
		}
		estStr := models.FormatTime(startTime.Add(time.Duration(elapsedMin) * time.Minute))
		dwellCopy := dwell
		stops = append(stops, models.JourneyStop{
			StopID:       uuid.NewString(),
			LocationID:   locID,
			Location_ID:  locID,
			StopType:     "delivery",
			Stop_Type:    "delivery",
			Sequence:     2,
			EstimatedAt:  estStr,
			Estimated_At: estStr,
			DwellMinutes: &dwellCopy,
			Coordinate:   coord,
		})
	}

	routeMode := "direct"
	if len(route.ConnectionIDs) > 1 {
		routeMode = "multi_stop"
	}

	targetLabID := route.LocationIDs[len(route.LocationIDs)-1]
	capAvail := 100
	if lab, ok := s.Locations[targetLabID]; ok {
		c := GetLocationCapacity(lab)
		if cooled {
			capAvail = c.CooledAvailableUnits
		} else {
			capAvail = c.AvailableUnits
		}
	}

	j := &models.Journey{
		JourneyID:               journeyID,
		PlanVersion:             1,
		RouteMode:               routeMode,
		Status:                  "active",
		EstimatedDeliveryAt:     models.FormatTime(route.ArrivalAt),
		TotalCostUnits:          route.TotalCost,
		CapacityUsed:            1,
		CapacityAvailable:       capAvail,
		SampleIDs:               []string{sample.SampleID},
		OrderedStops:            stops,
		AssignmentIDs:           []string{},
		LegAssignmentIDs:        []string{},
		CollectionAssignmentIDs: []string{},
		NodeAssignmentIDs:       []string{},
		LaboratoryAssignmentIDs: []string{},
		TargetLaboratoryID:      targetLabID,
		Cooled:                  cooled,
		History:                 []models.TimelineEntry{},
	}
	s.Journeys[journeyID] = j

	// Reserve capacity on locations and connections
	ReserveCapacityForSampleOnRoute(s, journeyID, sample.SampleID, route.LocationIDs, route.ConnectionIDs, cooled)
	if lab, ok := s.Locations[targetLabID]; ok {
		c := GetLocationCapacity(lab)
		if cooled {
			j.CapacityAvailable = c.CooledAvailableUnits
		} else {
			j.CapacityAvailable = c.AvailableUnits
		}
	}

	seq := 1
	startLocID := route.LocationIDs[0]

	// 1. Collection assignment (only when not pre-sealed)
	if includeCollection {
		collAssign := &models.Assignment{
			AssignmentID:         uuid.NewString(),
			Kind:                 "collection",
			JourneyID:            journeyID,
			SampleID:             sample.SampleID,
			SampleIDs:            []string{sample.SampleID},
			Sequence:             seq,
			Status:               "pending",
			FromLocationID:       startLocID,
			ToLocationID:         startLocID,
			ExpectedSampleTypeID: sample.SampleTypeID,
			DeclinedByWorkerIDs:  []string{},
			History:              []models.TimelineEntry{},
		}
		seq++
		s.Assignments[collAssign.AssignmentID] = collAssign
		j.AssignmentIDs = append(j.AssignmentIDs, collAssign.AssignmentID)
		j.CollectionAssignmentIDs = append(j.CollectionAssignmentIDs, collAssign.AssignmentID)
		chosen := OfferAssignmentToBestWorker(s, collAssign, startTime, "")
		if chosen == nil {
			FlagNoQualifiedWorkerException(s, sample, collAssign, models.FormatTime(startTime))
		}
	} else if registeringUser != nil && registeringRole == "node_handler" && registeringUser.AssignedLocationID == startLocID {
		// Pre-sealed registered by a node handler at startLocID
		outLoc := targetLabID
		if len(route.LocationIDs) > 1 {
			outLoc = route.LocationIDs[1]
		}
		nodeAssign := &models.Assignment{
			AssignmentID:           uuid.NewString(),
			Kind:                   "node",
			JourneyID:              journeyID,
			SampleID:               sample.SampleID,
			SampleIDs:              []string{sample.SampleID},
			Sequence:               seq,
			Status:                 "accepted",
			NodeID:                 startLocID,
			FromLocationID:         startLocID,
			ToLocationID:           startLocID,
			IncomingFromLocationID: startLocID,
			OutgoingToLocationID:   outLoc,
			WorkerID:               registeringUser.UserID,
			OfferedToWorkerID:      registeringUser.UserID,
			AcceptedAt:             models.FormatTime(startTime),
			DeclinedByWorkerIDs:    []string{},
			History:                []models.TimelineEntry{},
		}
		seq++
		s.Assignments[nodeAssign.AssignmentID] = nodeAssign
		j.AssignmentIDs = append(j.AssignmentIDs, nodeAssign.AssignmentID)
		j.NodeAssignmentIDs = append(j.NodeAssignmentIDs, nodeAssign.AssignmentID)
	}

	// Check if startLocID has a node_handler when there are no intermediate nodes
	if len(route.LocationIDs) == 2 && len(j.NodeAssignmentIDs) == 0 {
		hasStartNodeHandler := false
		for _, u := range s.Users {
			if u.Active && UserHasRole(u, "node_handler") && u.AssignedLocationID == startLocID {
				hasStartNodeHandler = true
				break
			}
		}
		if hasStartNodeHandler {
			nodeAssign := &models.Assignment{
				AssignmentID:           uuid.NewString(),
				Kind:                   "node",
				JourneyID:              journeyID,
				SampleID:               sample.SampleID,
				SampleIDs:              []string{sample.SampleID},
				Sequence:               seq,
				Status:                 "pending",
				NodeID:                 startLocID,
				FromLocationID:         startLocID,
				ToLocationID:           startLocID,
				IncomingFromLocationID: startLocID,
				OutgoingToLocationID:   route.LocationIDs[1],
				DeclinedByWorkerIDs:    []string{},
				History:                []models.TimelineEntry{},
			}
			seq++
			s.Assignments[nodeAssign.AssignmentID] = nodeAssign
			j.AssignmentIDs = append(j.AssignmentIDs, nodeAssign.AssignmentID)
			j.NodeAssignmentIDs = append(j.NodeAssignmentIDs, nodeAssign.AssignmentID)
			OfferAssignmentToBestWorker(s, nodeAssign, startTime, "")
		}
	}

	// 2. Transport legs and intermediate node assignments
	for i := 0; i < len(route.ConnectionIDs); i++ {
		fromLoc := route.LocationIDs[i]
		toLoc := route.LocationIDs[i+1]
		connID := route.ConnectionIDs[i]

		legAssign := &models.Assignment{
			AssignmentID:        uuid.NewString(),
			Kind:                "transport",
			JourneyID:           journeyID,
			SampleID:            sample.SampleID,
			SampleIDs:           []string{sample.SampleID},
			Sequence:            seq,
			LegSequence:         i + 1,
			Status:              "pending",
			FromLocationID:      fromLoc,
			ToLocationID:        toLoc,
			ConnectionID:        connID,
			DeclinedByWorkerIDs: []string{},
			History:             []models.TimelineEntry{},
		}
		seq++
		s.Assignments[legAssign.AssignmentID] = legAssign
		j.AssignmentIDs = append(j.AssignmentIDs, legAssign.AssignmentID)
		j.LegAssignmentIDs = append(j.LegAssignmentIDs, legAssign.AssignmentID)

		if !includeCollection && i == 0 && registeringUser != nil && registeringRole == "delivery_partner" {
			legAssign.WorkerID = registeringUser.UserID
			legAssign.OfferedToWorkerID = registeringUser.UserID
			legAssign.Status = "accepted"
			legAssign.AcceptedAt = models.FormatTime(startTime)
		} else {
			OfferAssignmentToBestWorker(s, legAssign, startTime, "")
		}

		// If toLoc is an intermediate node (not the final laboratory), create a node assignment
		if i+1 < len(route.LocationIDs)-1 {
			nextOutLoc := route.LocationIDs[i+2]
			nodeAssign := &models.Assignment{
				AssignmentID:           uuid.NewString(),
				Kind:                   "node",
				JourneyID:              journeyID,
				SampleID:               sample.SampleID,
				SampleIDs:              []string{sample.SampleID},
				Sequence:               seq,
				Status:                 "pending",
				NodeID:                 toLoc,
				FromLocationID:         toLoc,
				ToLocationID:           toLoc,
				IncomingFromLocationID: fromLoc,
				OutgoingToLocationID:   nextOutLoc,
				DeclinedByWorkerIDs:    []string{},
				History:                []models.TimelineEntry{},
			}
			seq++
			s.Assignments[nodeAssign.AssignmentID] = nodeAssign
			j.AssignmentIDs = append(j.AssignmentIDs, nodeAssign.AssignmentID)
			j.NodeAssignmentIDs = append(j.NodeAssignmentIDs, nodeAssign.AssignmentID)
			OfferAssignmentToBestWorker(s, nodeAssign, startTime, "")
		}
	}

	// If single-node route (0 connections), create 1 direct transport leg if needed
	if len(route.ConnectionIDs) == 0 {
		legAssign := &models.Assignment{
			AssignmentID:        uuid.NewString(),
			Kind:                "transport",
			JourneyID:           journeyID,
			SampleID:            sample.SampleID,
			SampleIDs:           []string{sample.SampleID},
			Sequence:            seq,
			LegSequence:         1,
			Status:              "pending",
			FromLocationID:      startLocID,
			ToLocationID:        targetLabID,
			DeclinedByWorkerIDs: []string{},
			History:             []models.TimelineEntry{},
		}
		seq++
		s.Assignments[legAssign.AssignmentID] = legAssign
		j.AssignmentIDs = append(j.AssignmentIDs, legAssign.AssignmentID)
		j.LegAssignmentIDs = append(j.LegAssignmentIDs, legAssign.AssignmentID)
		OfferAssignmentToBestWorker(s, legAssign, startTime, "")
	}

	// 3. Laboratory assignment at targetLabID
	labAssign := &models.Assignment{
		AssignmentID:         uuid.NewString(),
		Kind:                 "laboratory",
		JourneyID:            journeyID,
		SampleID:             sample.SampleID,
		SampleIDs:            []string{sample.SampleID},
		Sequence:             seq,
		Status:               "pending",
		LaboratoryID:         targetLabID,
		FromLocationID:       targetLabID,
		ToLocationID:         targetLabID,
		ExpectedSampleTypeID: sample.SampleTypeID,
		DeclinedByWorkerIDs:  []string{},
		History:              []models.TimelineEntry{},
	}
	s.Assignments[labAssign.AssignmentID] = labAssign
	j.AssignmentIDs = append(j.AssignmentIDs, labAssign.AssignmentID)
	j.LaboratoryAssignmentIDs = append(j.LaboratoryAssignmentIDs, labAssign.AssignmentID)
	if !includeCollection && registeringUser != nil && registeringRole == "laboratory_team" && registeringUser.AssignedLocationID == targetLabID {
		labAssign.WorkerID = registeringUser.UserID
		labAssign.OfferedToWorkerID = registeringUser.UserID
		labAssign.Status = "accepted"
		labAssign.AcceptedAt = models.FormatTime(startTime)
	} else {
		OfferAssignmentToBestWorker(s, labAssign, startTime, "")
	}

	return j
}

func SampleActiveAssignmentIDs(s *db.State, sample *models.Sample) []string {
	if sample == nil || sample.ActiveJourneyID == "" {
		return []string{}
	}
	j, ok := s.Journeys[sample.ActiveJourneyID]
	if !ok {
		return []string{}
	}
	res := make([]string, 0, len(j.AssignmentIDs))
	for _, aid := range j.AssignmentIDs {
		if a, exists := s.Assignments[aid]; exists && a.Status != "cancelled" && a.Status != "declined" {
			res = append(res, aid)
		}
	}
	return res
}

func BuildJourneyLegObject(a *models.Assignment, idx int) map[string]interface{} {
	seq := a.LegSequence
	if seq <= 0 {
		seq = idx + 1
	}
	leg := map[string]interface{}{
		"assignmentId":  a.AssignmentID,
		"assignment_id": a.AssignmentID,
		"sequence":      seq,
		"status":        a.Status,
	}
	if a.FromLocationID != "" {
		leg["fromLocationId"] = a.FromLocationID
		leg["from_location_id"] = a.FromLocationID
	}
	if a.ToLocationID != "" {
		leg["toLocationId"] = a.ToLocationID
		leg["to_location_id"] = a.ToLocationID
	}
	if a.WorkerID != "" {
		leg["workerId"] = a.WorkerID
		leg["worker_id"] = a.WorkerID
	}
	if a.SampleID != "" {
		leg["sampleId"] = a.SampleID
	}
	return leg
}

func BuildJourneyPlanResponse(s *db.State, j *models.Journey) map[string]interface{} {
	if j == nil {
		return nil
	}
	legs := make([]map[string]interface{}, 0, len(j.LegAssignmentIDs))
	for idx, aid := range j.LegAssignmentIDs {
		if a, ok := s.Assignments[aid]; ok {
			legs = append(legs, BuildJourneyLegObject(a, idx))
		}
	}

	workerSet := make(map[string]bool)
	assignedWorkerIDs := make([]string, 0)
	for _, aid := range j.AssignmentIDs {
		if a, ok := s.Assignments[aid]; ok && a.WorkerID != "" && a.Status != "cancelled" {
			if !workerSet[a.WorkerID] {
				workerSet[a.WorkerID] = true
				assignedWorkerIDs = append(assignedWorkerIDs, a.WorkerID)
			}
		}
	}

	capAvail := j.CapacityAvailable
	if j.TargetLaboratoryID != "" {
		if lab, ok := s.Locations[j.TargetLaboratoryID]; ok {
			c := GetLocationCapacity(lab)
			if j.Cooled {
				capAvail = c.CooledAvailableUnits
			} else {
				capAvail = c.AvailableUnits
			}
		}
	}

	stops := j.OrderedStops
	if stops == nil {
		stops = []models.JourneyStop{}
	}
	sampleIDs := j.SampleIDs
	if sampleIDs == nil {
		sampleIDs = []string{}
	}
	collIDs := j.CollectionAssignmentIDs
	if collIDs == nil {
		collIDs = []string{}
	}
	nodeIDs := j.NodeAssignmentIDs
	if nodeIDs == nil {
		nodeIDs = []string{}
	}
	labIDs := j.LaboratoryAssignmentIDs
	if labIDs == nil {
		labIDs = []string{}
	}

	plan := map[string]interface{}{
		"journeyId":               j.JourneyID,
		"planVersion":             j.PlanVersion,
		"routeMode":               j.RouteMode,
		"status":                  j.Status,
		"estimatedDeliveryAt":     j.EstimatedDeliveryAt,
		"totalCostUnits":          j.TotalCostUnits,
		"capacityUsed":            len(sampleIDs),
		"capacityAvailable":       capAvail,
		"sampleIds":               sampleIDs,
		"orderedStops":            stops,
		"legs":                    legs,
		"assignedWorkerIds":       assignedWorkerIDs,
		"collectionAssignmentIds": collIDs,
		"nodeAssignmentIds":       nodeIDs,
		"laboratoryAssignmentIds": labIDs,
		"valid":                   j.Status == "active" || j.Status == "completed",
	}
	if j.ParentJourneyID != "" {
		plan["parentJourneyId"] = j.ParentJourneyID
	}
	if len(collIDs) > 0 {
		plan["collectionAssignmentId"] = collIDs[0]
	}
	if len(j.LegAssignmentIDs) >= 1 {
		plan["firstTransportAssignmentId"] = j.LegAssignmentIDs[0]
		plan["finalTransportAssignmentId"] = j.LegAssignmentIDs[len(j.LegAssignmentIDs)-1]
	}
	if len(j.LegAssignmentIDs) >= 3 {
		plan["middleTransportAssignmentId"] = j.LegAssignmentIDs[1]
	} else if len(j.LegAssignmentIDs) == 2 {
		plan["middleTransportAssignmentId"] = j.LegAssignmentIDs[0]
	}
	if j.ReplanStatus != "" {
		plan["replanStatus"] = j.ReplanStatus
	}
	if j.SplitJourneyID != "" {
		if sj, ok := s.Journeys[j.SplitJourneyID]; ok && sj.JourneyID != j.JourneyID {
			plan["splitJourney"] = BuildJourneyPlanResponseWithoutNesting(s, sj)
		}
	}
	if j.ReplacementJourneyID != "" {
		if rj, ok := s.Journeys[j.ReplacementJourneyID]; ok && rj.JourneyID != j.JourneyID {
			plan["replacementJourney"] = BuildJourneyPlanResponseWithoutNesting(s, rj)
		}
	}
	return plan
}

func BuildJourneyPlanResponseWithoutNesting(s *db.State, j *models.Journey) map[string]interface{} {
	cp := *j
	cp.SplitJourneyID = ""
	cp.ReplacementJourneyID = ""
	return BuildJourneyPlanResponse(s, &cp)
}

func BuildRequesterJourneyPlanResponse(s *db.State, j *models.Journey, requesterID string) map[string]interface{} {
	legs := make([]map[string]interface{}, 0, len(j.LegAssignmentIDs))
	for idx, aid := range j.LegAssignmentIDs {
		if a, ok := s.Assignments[aid]; ok {
			seq := a.LegSequence
			if seq <= 0 {
				seq = idx + 1
			}
			leg := map[string]interface{}{
				"assignmentId":   a.AssignmentID,
				"sequence":       seq,
				"status":         a.Status,
				"fromLocationId": a.FromLocationID,
				"toLocationId":   a.ToLocationID,
			}
			legs = append(legs, leg)
		}
	}
	ownSamples := make([]string, 0)
	for _, sid := range j.SampleIDs {
		if samp, ok := s.Samples[sid]; ok && samp.RequesterID == requesterID {
			ownSamples = append(ownSamples, sid)
		}
	}
	if len(ownSamples) == 0 {
		ownSamples = j.SampleIDs
	}
	stops := j.OrderedStops
	if stops == nil {
		stops = []models.JourneyStop{}
	}
	plan := map[string]interface{}{
		"journeyId":           j.JourneyID,
		"planVersion":         j.PlanVersion,
