func BuildWorkerJourneyPlanResponse(s *db.State, j *models.Journey, workerID string) map[string]interface{} {
	workerAssignIDs := make([]string, 0)
	workerLegs := make([]map[string]interface{}, 0)
	stopLocSet := make(map[string]bool)

	for _, aid := range j.AssignmentIDs {
		a, ok := s.Assignments[aid]
		if !ok {
			continue
		}
		if a.WorkerID == workerID || a.OfferedToWorkerID == workerID {
			workerAssignIDs = append(workerAssignIDs, a.AssignmentID)
			if a.FromLocationID != "" {
				stopLocSet[a.FromLocationID] = true
			}
			if a.ToLocationID != "" {
				stopLocSet[a.ToLocationID] = true
			}
			if a.NodeID != "" {
				stopLocSet[a.NodeID] = true
			}
			if a.LaboratoryID != "" {
				stopLocSet[a.LaboratoryID] = true
			}
		}
	}

	for idx, aid := range j.LegAssignmentIDs {
		if a, ok := s.Assignments[aid]; ok {
			if a.WorkerID == workerID || a.OfferedToWorkerID == workerID {
				workerLegs = append(workerLegs, BuildJourneyLegObject(a, idx))
			}
		}
	}

	workerStops := make([]models.JourneyStop, 0)
	for _, st := range j.OrderedStops {
		if stopLocSet[st.LocationID] {
			workerStops = append(workerStops, st)
		}
	}
	if len(workerStops) == 0 && len(j.OrderedStops) > 0 {
		workerStops = j.OrderedStops[:1]
	}

	plan := map[string]interface{}{
		"journeyId":           j.JourneyID,
		"planVersion":         j.PlanVersion,
		"routeMode":           j.RouteMode,
		"status":              j.Status,
		"estimatedDeliveryAt": j.EstimatedDeliveryAt,
		"scope":               "assigned_legs",
		"assignmentIds":       workerAssignIDs,
		"sampleIds":           j.SampleIDs,
		"legs":                workerLegs,
		"orderedStops":        workerStops,
		"assignedWorkerIds":   []string{workerID},
	}
	if j.ParentJourneyID != "" {
		plan["parentJourneyId"] = j.ParentJourneyID
	}
	return plan
}
