func (srv *Server) handleAuthenticateUser(w http.ResponseWriter, r *http.Request) {
	var req struct {
		Username string `json:"username"`
		Password string `json:"password"`
	}
	if _, apiErr := DecodeStrictJSON(r, &req); apiErr != nil {
		WriteError(w, apiErr)
		return
	}

	var respData map[string]interface{}
	err := srv.store.Write(r.Context(), func(s *db.State) error {
		nowStr := models.FormatTime(time.Now())
		var found *models.User
		for _, u := range s.Users {
			if u.Username == req.Username {
				found = u
				break
			}
		}
		if found == nil || !found.Active || found.PasswordHash != db.HashPassword(req.Password) {
			actorID := "anonymous"
			if found != nil {
				actorID = found.UserID
			}
			RecordAudit(s, actorID, "none", "authenticate_user", "user", actorID, false, nowStr, map[string]interface{}{
				"username": req.Username,
				"reason":   "invalid_credentials",
			})
			return NewErr(http.StatusUnauthorized, "invalid_credentials", "invalid username or password")
		}

		activeRole := ""
		explicit := false
		if len(found.Roles) == 1 {
			activeRole = found.Roles[0]
			explicit = true
		}

		token := uuid.NewString()
		s.Sessions[token] = &models.Session{
			Token:                  token,
			UserID:                 found.UserID,
			ActiveRole:             activeRole,
			RoleExplicitlySelected: explicit,
			CreatedAt:              nowStr,
		}

		RecordAudit(s, found.UserID, activeRole, "authenticate_user", "user", found.UserID, true, nowStr, map[string]interface{}{
			"username":   found.Username,
			"roles":      found.Roles,
			"activeRole": activeRole,
		})

		roles := found.Roles
		if roles == nil {
			roles = []string{}
		}
		respData = map[string]interface{}{
			"sessionToken": token,
			"userId":       found.UserID,
			"roles":        roles,
			"activeRole":   activeRole,
		}
		return nil
	})
	if err != nil {
		WriteError(w, err)
		return
	}
	WriteData(w, http.StatusOK, respData)
}

func (srv *Server) handleSelectActiveRole(w http.ResponseWriter, r *http.Request) {
	var req struct {
		Role string `json:"role"`
	}
	if _, apiErr := DecodeStrictJSON(r, &req); apiErr != nil {
		WriteError(w, apiErr)
		return
	}

	var respData map[string]interface{}
	err := srv.store.Write(r.Context(), func(s *db.State) error {
		u, sess, apiErr := AuthenticateSession(s, r)
		if apiErr != nil {
			return apiErr
		}
		nowStr := models.FormatTime(time.Now())
		if !ValidRoles[req.Role] {
			RecordAudit(s, u.UserID, sess.ActiveRole, "select_active_role", "user", u.UserID, false, nowStr, map[string]interface{}{
				"requestedRole": req.Role,
				"reason":        "invalid_role",
			})
			return NewErr(http.StatusBadRequest, "invalid_role", "invalid role")
		}
		if !UserHasRole(u, req.Role) {
			RecordAudit(s, u.UserID, sess.ActiveRole, "select_active_role", "user", u.UserID, false, nowStr, map[string]interface{}{
				"requestedRole": req.Role,
				"reason":        "role_not_held",
			})
			return NewErr(http.StatusForbidden, "role_not_held", "user does not hold requested role")
		}

		sess.ActiveRole = req.Role
		sess.RoleExplicitlySelected = true

		RecordAudit(s, u.UserID, req.Role, "select_active_role", "user", u.UserID, true, nowStr, map[string]interface{}{
			"activeRole": req.Role,
			"roles":      u.Roles,
		})

		respData = map[string]interface{}{
			"activeRole": sess.ActiveRole,
			"roles":      u.Roles,
		}
		return nil
	})
	if err != nil {
		WriteError(w, err)
		return
	}
	WriteData(w, http.StatusOK, respData)
