func validateCertifications(certs []models.Certification) *APIError {
	for _, c := range certs {
		if strings.TrimSpace(c.Code) == "" {
			return NewErr(http.StatusBadRequest, "invalid_certification", "certification code cannot be empty")
		}
		if c.ExpiresAt != nil && *c.ExpiresAt != "" {
			if _, ok := ParseTime(*c.ExpiresAt); !ok {
				return NewErr(http.StatusBadRequest, "invalid_certification", "invalid certification expiresAt timestamp")
			}
		}
	}
	return nil
}

