			return NewErr(http.StatusBadRequest, "invalid_json", "userId, roles, and active are required")
		}
		for _, rl := range req.Roles {
			if !ValidRoles[rl] {
				return NewErr(http.StatusBadRequest, "invalid_json", "invalid role: "+rl)
			}
		}
		if req.Certifications != nil {
			if apiErr := validateCertifications(*req.Certifications); apiErr != nil {
				return apiErr
			}
		}
		target, ok := s.Users[req.UserID]
		if !ok {
			return NewErr(http.StatusNotFound, "not_found", "user not found")
		}

		target.Roles = req.Roles
		target.Active = *req.Active
		if req.Qualifications != nil {
			target.Qualifications = *req.Qualifications
		}
		if req.Certifications != nil {
			target.Certifications = *req.Certifications
		}
		if req.AssignedLocationID != nil {
			target.AssignedLocationID = *req.AssignedLocationID
		}

		// Update any existing sessions for this user if their activeRole is no longer held
		for _, usess := range s.Sessions {
			if usess.UserID == target.UserID {
				if !UserHasRole(target, usess.ActiveRole) {
					if len(target.Roles) == 1 {
						usess.ActiveRole = target.Roles[0]
					} else {
						usess.ActiveRole = ""
						usess.RoleExplicitlySelected = false
					}
				} else if len(target.Roles) > 1 && !usess.RoleExplicitlySelected {
					usess.ActiveRole = ""
				}
			}
		}

		now := time.Now().UTC()
		nowStr := models.FormatTime(now)
		RecordAudit(s, u.UserID, role, "update_user_access", "user", target.UserID, true, nowStr, map[string]interface{}{
			"userId":             target.UserID,
			"roles":              target.Roles,
			"qualifications":     target.Qualifications,
			"certifications":     target.Certifications,
			"active":             target.Active,
			"assignedLocationId": target.AssignedLocationID,
		})
		EmitEvent(s, "user.updated", "user", target.UserID, map[string]interface{}{
			"userId": target.UserID,
			"roles":  target.Roles,
			"active": target.Active,
		})

		TryOfferPendingAssignments(s, now)

		respData = map[string]interface{}{
			"userId":         target.UserID,
			"roles":          target.Roles,
			"qualifications": target.Qualifications,
			"certifications": target.Certifications,
			"active":         target.Active,
