func (srv *Server) handleReadUser(w http.ResponseWriter, r *http.Request) {
	userID := strings.TrimPrefix(r.URL.Path, "/api/read-user/")
	userID = strings.TrimSpace(userID)

	var respData map[string]interface{}
	var handlerErr error
	srv.store.Read(func(s *db.State) {
		u, sess, apiErr := AuthenticateSession(s, r)
		if apiErr != nil {
			handlerErr = apiErr
			return
		}
		role := sess.ActiveRole
		if role == "" && len(u.Roles) == 1 {
			role = u.Roles[0]
		}
		if role == "" {
			handlerErr = NewErr(http.StatusForbidden, "forbidden", "role not selected")
			return
		}
		if role != "administrator" && role != "dispatcher" && u.UserID != userID {
			handlerErr = NewErr(http.StatusForbidden, "forbidden", "cannot read other user")
			return
		}
		target, ok := s.Users[userID]
		if !ok {
			handlerErr = NewErr(http.StatusNotFound, "not_found", "user not found")
			return
		}
		respData = buildUserResponse(target)
	})
	if handlerErr != nil {
		WriteError(w, handlerErr)
		return
	}
	WriteData(w, http.StatusOK, respData)
}

func parseLocationFunctions(funcs []string) (models.LocationFunctionStates, *APIError) {
	if len(funcs) == 0 {
		return models.LocationFunctionStates{}, NewErr(http.StatusBadRequest, "invalid_location_function", "at least one location function is required")
	}
	var st models.LocationFunctionStates
	for _, f := range funcs {
		switch f {
		case "collection_point":
			st.CollectionPoint = true
		case "transfer_point":
			st.TransferPoint = true
		case "hub":
			st.Hub = true
		case "laboratory":
			st.Laboratory = true
		default:
			return models.LocationFunctionStates{}, NewErr(http.StatusBadRequest, "invalid_location_function", "invalid location function: "+f)
		}
	}
	return st, nil
}

