func (srv *Server) handleCreateConnection(w http.ResponseWriter, r *http.Request) {
	var req struct {
		FromLocationID string   `json:"fromLocationId"`
		ToLocationID   string   `json:"toLocationId"`
		TravelMinutes  *int     `json:"travelMinutes"`
		CostUnits      *float64 `json:"costUnits"`
		Cooled         *bool    `json:"cooled"`
		Active         *bool    `json:"active"`
	}
	if _, apiErr := DecodeStrictJSON(r, &req); apiErr != nil {
		WriteError(w, apiErr)
		return
	}

	var respData map[string]interface{}
	err := srv.store.Write(r.Context(), func(s *db.State) error {
		u, sess, apiErr := AuthenticateSession(s, r)
		if apiErr != nil {
			return apiErr
		}
		role, apiErr := RequireActiveRole(s, u, sess, "create_connection", "connection", req.FromLocationID+"->"+req.ToLocationID, true, "administrator")
		if apiErr != nil {
			return apiErr
		}
		if req.FromLocationID == "" || req.ToLocationID == "" || req.TravelMinutes == nil || req.CostUnits == nil || req.Active == nil {
			return NewErr(http.StatusBadRequest, "invalid_json", "fromLocationId, toLocationId, travelMinutes, costUnits, and active are required")
		}
		if req.FromLocationID == req.ToLocationID || *req.TravelMinutes < 1 || *req.CostUnits < 0 {
			return NewErr(http.StatusBadRequest, "invalid_connection", "invalid connection parameters")
		}
		if _, ok := s.Locations[req.FromLocationID]; !ok {
			return NewErr(http.StatusBadRequest, "invalid_connection", "fromLocationId does not exist")
		}
		if _, ok := s.Locations[req.ToLocationID]; !ok {
			return NewErr(http.StatusBadRequest, "invalid_connection", "toLocationId does not exist")
		}

		cooled := false
		if req.Cooled != nil {
			cooled = *req.Cooled
		}
		cooledCap := 0
		if cooled {
			cooledCap = 100
		}

		conn := &models.Connection{
			ConnectionID:        uuid.NewString(),
			FromLocationID:      req.FromLocationID,
			ToLocationID:        req.ToLocationID,
			TravelMinutes:       *req.TravelMinutes,
			CostUnits:           *req.CostUnits,
			Cooled:              cooled,
			Active:              *req.Active,
			CapacityConfigured:  false,
			CapacityUnits:       100,
			ReservedUnits:       0,
			CooledCapacityUnits: cooledCap,
			CooledReservedUnits: 0,
		}
		s.Connections[conn.ConnectionID] = conn
		RecomputeServiceabilitySnapshot(s)

		nowStr := models.FormatTime(time.Now())
		RecordAudit(s, u.UserID, role, "create_connection", "connection", conn.ConnectionID, true, nowStr, map[string]interface{}{
			"connectionId":   conn.ConnectionID,
			"fromLocationId": conn.FromLocationID,
			"toLocationId":   conn.ToLocationID,
			"travelMinutes":  conn.TravelMinutes,
			"costUnits":      conn.CostUnits,
			"cooled":         conn.Cooled,
			"active":         conn.Active,
		})
		EmitEvent(s, "connection.created", "connection", conn.ConnectionID, map[string]interface{}{
			"connectionId": conn.ConnectionID,
			"active":       conn.Active,
		})

		respData = map[string]interface{}{
			"connectionId":   conn.ConnectionID,
			"fromLocationId": conn.FromLocationID,
			"toLocationId":   conn.ToLocationID,
			"travelMinutes":  conn.TravelMinutes,
			"costUnits":      conn.CostUnits,
			"cooled":         conn.Cooled,
			"active":         conn.Active,
		}
		return nil
	})
	if err != nil {
		WriteError(w, err)
		return
	}
	WriteData(w, http.StatusCreated, respData)
}

