func (srv *Server) handleCreateSampleType(w http.ResponseWriter, r *http.Request) {
	var req struct {
		Name                       string    `json:"name"`
		QualifiedCollectorRequired *bool     `json:"qualifiedCollectorRequired"`
		RequiredQualification      string    `json:"requiredQualification"`
		ContainerType              string    `json:"containerType"`
		TemperatureMinC            *float64  `json:"temperatureMinC"`
		TemperatureMaxC            *float64  `json:"temperatureMaxC"`
		IncompatibleSampleTypes    *[]string `json:"incompatibleSampleTypes"`
		RequiresCooledRoute        *bool     `json:"requiresCooledRoute"`
		BatchingAllowed            *bool     `json:"batchingAllowed"`
	}
	if _, apiErr := DecodeStrictJSON(r, &req); apiErr != nil {
		WriteError(w, apiErr)
		return
	}

	var respData *models.SampleType
	err := srv.store.Write(r.Context(), func(s *db.State) error {
		u, sess, apiErr := AuthenticateSession(s, r)
		if apiErr != nil {
			return apiErr
		}
		role, apiErr := RequireActiveRole(s, u, sess, "create_sample_type", "sample_type", req.Name, true, "administrator")
		if apiErr != nil {
			return apiErr
		}
		if strings.TrimSpace(req.Name) == "" || strings.TrimSpace(req.ContainerType) == "" || req.TemperatureMinC == nil || req.TemperatureMaxC == nil {
			return NewErr(http.StatusBadRequest, "invalid_handling_rule", "name, containerType, temperatureMinC, and temperatureMaxC are required")
		}
		if *req.TemperatureMinC > *req.TemperatureMaxC {
			return NewErr(http.StatusBadRequest, "invalid_handling_rule", "temperatureMinC cannot exceed temperatureMaxC")
		}

		incompat := []string{}
		if req.IncompatibleSampleTypes != nil {
			for _, id := range *req.IncompatibleSampleTypes {
				if _, exists := s.SampleTypes[id]; !exists {
					return NewErr(http.StatusBadRequest, "invalid_handling_rule", "incompatible sampleTypeId not found: "+id)
				}
				incompat = append(incompat, id)
			}
		}

		isNamedBuiltIn := strings.EqualFold(req.Name, "Amber") ||
			strings.EqualFold(req.Name, "Indigo") ||
			strings.EqualFold(req.Name, "Frost") ||
			strings.EqualFold(req.Name, "Pulse")

		qualReq := false
		if req.QualifiedCollectorRequired != nil {
			qualReq = *req.QualifiedCollectorRequired
		} else if isNamedBuiltIn {
			qualReq = true
		}

		reqQual := req.RequiredQualification
		if qualReq && reqQual == "" {
			reqQual = req.Name
		}

		cooled := false
		if req.RequiresCooledRoute != nil {
			cooled = *req.RequiresCooledRoute
		} else if strings.EqualFold(req.Name, "Frost") {
			cooled = true
		}

		batchAllowed := true
		if req.BatchingAllowed != nil {
			batchAllowed = *req.BatchingAllowed
		} else if strings.EqualFold(req.Name, "Pulse") {
			batchAllowed = false
		}

		st := &models.SampleType{
			SampleTypeID:               uuid.NewString(),
			Name:                       req.Name,
			QualifiedCollectorRequired: qualReq,
			RequiredQualification:      reqQual,
			ContainerType:              req.ContainerType,
			TemperatureMinC:            *req.TemperatureMinC,
			TemperatureMaxC:            *req.TemperatureMaxC,
			IncompatibleSampleTypes:    incompat,
			RequiresCooledRoute:        cooled,
			BatchingAllowed:            batchAllowed,
		}
		s.SampleTypes[st.SampleTypeID] = st

		// Maintain symmetric incompatibility
		for _, otherID := range incompat {
			if other, ok := s.SampleTypes[otherID]; ok {
				has := false
				for _, x := range other.IncompatibleSampleTypes {
					if x == st.SampleTypeID {
						has = true
						break
					}
				}
				if !has {
					other.IncompatibleSampleTypes = append(other.IncompatibleSampleTypes, st.SampleTypeID)
				}
			}
		}

		RecomputeServiceabilitySnapshot(s)

		nowStr := models.FormatTime(time.Now())
		RecordAudit(s, u.UserID, role, "create_sample_type", "sample_type", st.SampleTypeID, true, nowStr, map[string]interface{}{
			"sampleTypeId": st.SampleTypeID,
			"name":         st.Name,
		})

		respData = st
		return nil
	})
	if err != nil {
		WriteError(w, err)
		return
	}
	WriteData(w, http.StatusCreated, respData)
}

