func (srv *Server) handleConfigureCapacity(w http.ResponseWriter, r *http.Request) {
	var req struct {
		ResourceID          string `json:"resourceId"`
		CapacityUnits       *int   `json:"capacityUnits"`
		CooledCapacityUnits *int   `json:"cooledCapacityUnits"`
	}
	if _, apiErr := DecodeStrictJSON(r, &req); apiErr != nil {
		WriteError(w, apiErr)
		return
	}

	var respData map[string]interface{}
	err := srv.store.Write(r.Context(), func(s *db.State) error {
		u, sess, apiErr := AuthenticateSession(s, r)
		if apiErr != nil {
			return apiErr
		}
		role, apiErr := RequireActiveRole(s, u, sess, "configure_capacity", "capacity", req.ResourceID, true, "administrator", "node_handler", "laboratory_team")
		if apiErr != nil {
			return apiErr
		}
		if req.ResourceID == "" || req.CapacityUnits == nil {
			return NewErr(http.StatusBadRequest, "invalid_json", "resourceId and capacityUnits are required")
		}
		cooledUnits := 0
		if req.CooledCapacityUnits != nil {
			cooledUnits = *req.CooledCapacityUnits
		}
		if *req.CapacityUnits < 0 || cooledUnits < 0 {
			return NewErr(http.StatusBadRequest, "invalid_capacity", "capacity cannot be negative")
		}

		nowStr := models.FormatTime(time.Now())
		if loc, ok := s.Locations[req.ResourceID]; ok {
			if role == "node_handler" || role == "laboratory_team" {
				if u.AssignedLocationID != loc.LocationID {
					RecordAudit(s, u.UserID, role, "configure_capacity", "location", req.ResourceID, false, nowStr, map[string]interface{}{
						"reason":             "wrong_location",
						"assignedLocationId": u.AssignedLocationID,
					})
					return NewErr(http.StatusForbidden, "forbidden", "worker can only configure capacity for their assigned location")
				}
			}
			if *req.CapacityUnits < loc.ReservedUnits || (req.CooledCapacityUnits != nil && cooledUnits < loc.CooledReservedUnits) || (*req.CapacityUnits == 0 && loc.CooledReservedUnits > 0 && cooledUnits < loc.CooledReservedUnits) {
				RecordAudit(s, u.UserID, role, "configure_capacity", "location", req.ResourceID, false, nowStr, map[string]interface{}{
					"reason":              "capacity_reserved",
					"reservedUnits":       loc.ReservedUnits,
					"cooledReservedUnits": loc.CooledReservedUnits,
				})
				return NewErr(http.StatusConflict, "capacity_reserved", "cannot reduce capacity below currently reserved units")
			}
			loc.CapacityConfigured = true
			loc.CapacityUnits = *req.CapacityUnits
			loc.CooledCapacityUnits = cooledUnits
			RecomputeServiceabilitySnapshot(s)

			RecordAudit(s, u.UserID, role, "configure_capacity", "location", loc.LocationID, true, nowStr, map[string]interface{}{
				"resourceId":          loc.LocationID,
				"capacityUnits":       loc.CapacityUnits,
				"cooledCapacityUnits": loc.CooledCapacityUnits,
			})
			EmitEvent(s, "capacity.configured", "location", loc.LocationID, map[string]interface{}{
				"resourceId":          loc.LocationID,
				"capacityUnits":       loc.CapacityUnits,
				"cooledCapacityUnits": loc.CooledCapacityUnits,
			})
			respData = map[string]interface{}{
				"resourceId":          loc.LocationID,
				"capacityUnits":       loc.CapacityUnits,
				"cooledCapacityUnits": loc.CooledCapacityUnits,
			}
			return nil
		}

		if conn, ok := s.Connections[req.ResourceID]; ok {
			if role != "administrator" {
				RecordAudit(s, u.UserID, role, "configure_capacity", "connection", req.ResourceID, false, nowStr, map[string]interface{}{
					"reason": "forbidden",
				})
				return NewErr(http.StatusForbidden, "forbidden", "only administrator can configure connection capacity")
			}
			if *req.CapacityUnits < conn.ReservedUnits || (req.CooledCapacityUnits != nil && cooledUnits < conn.CooledReservedUnits) || (*req.CapacityUnits == 0 && conn.CooledReservedUnits > 0 && cooledUnits < conn.CooledReservedUnits) {
				return NewErr(http.StatusConflict, "capacity_reserved", "cannot reduce capacity below currently reserved units")
			}
			conn.CapacityConfigured = true
			conn.CapacityUnits = *req.CapacityUnits
			if req.CooledCapacityUnits != nil {
				conn.CooledCapacityUnits = cooledUnits
			} else if conn.Cooled && *req.CapacityUnits > 0 {
				conn.CooledCapacityUnits = *req.CapacityUnits
				cooledUnits = conn.CooledCapacityUnits
			} else {
				conn.CooledCapacityUnits = 0
			}
			RecomputeServiceabilitySnapshot(s)

			RecordAudit(s, u.UserID, role, "configure_capacity", "connection", conn.ConnectionID, true, nowStr, map[string]interface{}{
				"resourceId":          conn.ConnectionID,
				"capacityUnits":       conn.CapacityUnits,
				"cooledCapacityUnits": cooledUnits,
			})
			EmitEvent(s, "capacity.configured", "connection", conn.ConnectionID, map[string]interface{}{
				"resourceId":          conn.ConnectionID,
				"capacityUnits":       conn.CapacityUnits,
				"cooledCapacityUnits": cooledUnits,
			})
			respData = map[string]interface{}{
				"resourceId":          conn.ConnectionID,
				"capacityUnits":       conn.CapacityUnits,
				"cooledCapacityUnits": cooledUnits,
			}
			return nil
		}

		return NewErr(http.StatusBadRequest, "invalid_capacity", "resource not found")
	})
	if err != nil {
		WriteError(w, err)
		return
	}
	WriteData(w, http.StatusOK, respData)
}

func (srv *Server) handleSetWorkerAvailability(w http.ResponseWriter, r *http.Request) {
	var req struct {
		WorkerID      string `json:"workerId"`
		Available     *bool  `json:"available"`
		CapacityUnits *int   `json:"capacityUnits"`
	}
	if _, apiErr := DecodeStrictJSON(r, &req); apiErr != nil {
		WriteError(w, apiErr)
		return
	}

	var respData map[string]interface{}
	err := srv.store.Write(r.Context(), func(s *db.State) error {
		u, sess, apiErr := AuthenticateSession(s, r)
		if apiErr != nil {
			return apiErr
		}
		role, apiErr := RequireActiveRole(s, u, sess, "set_worker_availability", "user", req.WorkerID, true)
		if apiErr != nil {
			return apiErr
		}
		if role != "administrator" && role != "dispatcher" && u.UserID != req.WorkerID {
			RecordAudit(s, u.UserID, role, "set_worker_availability", "user", req.WorkerID, false, models.FormatTime(time.Now()), map[string]interface{}{
				"reason": "forbidden",
			})
			return NewErr(http.StatusForbidden, "forbidden", "not allowed to change another worker's availability")
		}
		if req.WorkerID == "" || req.Available == nil || req.CapacityUnits == nil {
			return NewErr(http.StatusBadRequest, "invalid_json", "workerId, available, and capacityUnits are required")
		}
		if *req.CapacityUnits < 0 {
			return NewErr(http.StatusBadRequest, "invalid_capacity", "capacityUnits cannot be negative")
		}
		worker, ok := s.Users[req.WorkerID]
		if !ok {
			return NewErr(http.StatusNotFound, "not_found", "worker not found")
		}

		// Check if worker has accepted/in-progress assignments exceeding new capacity
		acceptedSampleLoad := 0
		for _, a := range s.Assignments {
			if a.WorkerID == worker.UserID && (a.Status == "accepted" || a.Status == "at_pickup" || a.Status == "picked_up" || a.Status == "in_transit" || a.Status == "arrived" || a.Status == "in_progress") {
				if j, ok := s.Journeys[a.JourneyID]; ok && j.Status == "active" {
					n := len(j.SampleIDs)
					if n == 0 {
						n = 1
					}
					acceptedSampleLoad += n
				}
			}
		}
		if acceptedSampleLoad > 0 && *req.CapacityUnits < acceptedSampleLoad {
			return NewErr(http.StatusConflict, "capacity_reserved", "worker has active reserved capacity exceeding requested capacityUnits")
		}

		worker.Available = *req.Available
		worker.CapacityUnits = *req.CapacityUnits
		worker.CapacityConfigured = true

		now := time.Now().UTC()
		nowStr := models.FormatTime(now)
		RecordAudit(s, u.UserID, role, "set_worker_availability", "user", worker.UserID, true, nowStr, map[string]interface{}{
			"workerId":      worker.UserID,
			"available":     worker.Available,
			"capacityUnits": worker.CapacityUnits,
		})
		EmitEvent(s, "worker.availability_changed", "user", worker.UserID, map[string]interface{}{
			"workerId":      worker.UserID,
			"available":     worker.Available,
			"capacityUnits": worker.CapacityUnits,
		})

		if worker.Available {
			TryOfferPendingAssignments(s, now)
		}

		respData = map[string]interface{}{
			"workerId":      worker.UserID,
			"available":     worker.Available,
			"capacityUnits": worker.CapacityUnits,
		}
		return nil
	})
	if err != nil {
		WriteError(w, err)
		return
	}
	// Avoid unused import warning for json if any
	_ = json.Marshal
	WriteData(w, http.StatusOK, respData)
}
"}

