func (srv *Server) handleCheckServiceability(w http.ResponseWriter, r *http.Request) {
	var req struct {
		Origin               *models.Coordinate `json:"origin"`
		OriginType           string             `json:"originType"`
		OriginNodeID         string             `json:"originNodeId"`
		SampleTypeID         string             `json:"sampleTypeId"`
		RequestedAt          string             `json:"requestedAt"`
		DeliveryDeadline     string             `json:"deliveryDeadline"`
		EarliestCollectionAt string             `json:"earliestCollectionAt"`
		LatestCollectionAt   string             `json:"latestCollectionAt"`
	}
	if _, apiErr := DecodeStrictJSON(r, &req); apiErr != nil {
		WriteError(w, apiErr)
		return
	}

	var respData map[string]interface{}
	var handlerErr error
	srv.store.Read(func(s *db.State) {
		u, sess, apiErr := AuthenticateSession(s, r)
		if apiErr != nil {
			handlerErr = apiErr
			return
		}
		role := sess.ActiveRole
		if role == "" {
			if len(u.Roles) == 1 {
				role = u.Roles[0]
			} else {
				handlerErr = NewErr(http.StatusConflict, "role_not_selected", "must select an active role")
				return
			}
		}
		if role != "requester" && role != "dispatcher" && role != "administrator" {
			handlerErr = NewErr(http.StatusForbidden, "forbidden", "role not allowed to check serviceability")
			return
		}
		if req.Origin == nil || req.SampleTypeID == "" || req.RequestedAt == "" || req.DeliveryDeadline == "" {
			handlerErr = NewErr(http.StatusBadRequest, "invalid_json", "origin, sampleTypeId, requestedAt, and deliveryDeadline are required")
			return
		}
		if !ValidCoordinate(*req.Origin) {
			handlerErr = NewErr(http.StatusBadRequest, "invalid_origin", "invalid origin coordinates")
			return
		}
		originType := req.OriginType
		if originType == "" {
			originType = "home"
		}
		if originType != "home" && originType != "clinic" && originType != "node" {
			handlerErr = NewErr(http.StatusBadRequest, "invalid_origin_type", "invalid originType")
			return
		}
		reqTime, ok1 := ParseTime(req.RequestedAt)
		deadline, ok2 := ParseTime(req.DeliveryDeadline)
		if !ok1 || !ok2 {
			handlerErr = NewErr(http.StatusBadRequest, "invalid_time", "invalid timestamp format")
			return
		}
		if !deadline.After(reqTime) {
			handlerErr = NewErr(http.StatusBadRequest, "invalid_deadline", "deliveryDeadline must be after requestedAt")
			return
		}
		earliest := reqTime
		if req.EarliestCollectionAt != "" {
			t, ok := ParseTime(req.EarliestCollectionAt)
			if !ok {
				handlerErr = NewErr(http.StatusBadRequest, "invalid_time", "invalid earliestCollectionAt")
				return
			}
			earliest = t
		}
		latest := deadline
		if req.LatestCollectionAt != "" {
			t, ok := ParseTime(req.LatestCollectionAt)
			if !ok {
				handlerErr = NewErr(http.StatusBadRequest, "invalid_time", "invalid latestCollectionAt")
				return
			}
			latest = t
		}
		if earliest.After(latest) || earliest.After(deadline) || latest.Before(reqTime) || earliest.Before(reqTime) || latest.After(deadline) {
			handlerErr = NewErr(http.StatusBadRequest, "invalid_collection_window", "invalid collection window")
			return
		}

		outcome, evalErr := EvaluateServiceability(s, ServiceabilityInput{
			Origin:               *req.Origin,
			OriginType:           originType,
			OriginNodeID:         req.OriginNodeID,
			SampleTypeID:         req.SampleTypeID,
			RequestedAt:          reqTime,
			DeliveryDeadline:     deadline,
			EarliestCollectionAt: earliest,
			LatestCollectionAt:   latest,
			Units:                1,
		})
		if evalErr != nil {
			handlerErr = evalErr
			return
		}

		respData = map[string]interface{}{
			"serviceable":           outcome.Serviceable,
			"reason":                outcome.Reason,
			"serviceabilityVersion": outcome.ServiceabilityVersion,
