func (srv *Server) createOrIngestSample(w http.ResponseWriter, r *http.Request, presealed bool) {
	var req struct {
		RequesterID             string             `json:"requesterId"`
		Origin                  *models.Coordinate `json:"origin"`
		OriginType              string             `json:"originType"`
		OriginNodeID            string             `json:"originNodeId"`
		RequestedAt             string             `json:"requestedAt"`
		DeliveryDeadline        string             `json:"deliveryDeadline"`
		EarliestCollectionAt    string             `json:"earliestCollectionAt"`
		LatestCollectionAt      string             `json:"latestCollectionAt"`
		SampleTypeID            string             `json:"sampleTypeId"`
		ContainerType           string             `json:"containerType"`
		TemperatureMinC         *float64           `json:"temperatureMinC"`
		TemperatureMaxC         *float64           `json:"temperatureMaxC"`
		IncompatibleSampleTypes []string           `json:"incompatibleSampleTypes"`
		IdempotencyKey          string             `json:"idempotencyKey"`
	}
	rawBody, apiErr := DecodeStrictJSON(r, &req)
	if apiErr != nil {
		WriteError(w, apiErr)
		return
	}

	opName := "create_collection_request"
	if presealed {
		opName = "ingest_presealed_sample"
	}

	var cached *models.IdempotencyRecord
	var respData map[string]interface{}
	err := srv.store.Write(r.Context(), func(s *db.State) error {
		u, sess, apiErr := AuthenticateSession(s, r)
		if apiErr != nil {
			return apiErr
		}
		var allowedRoles []string
		if presealed {
			allowedRoles = []string{"collection_professional", "delivery_partner", "node_handler", "laboratory_team"}
		} else {
			allowedRoles = []string{"requester", "dispatcher", "administrator"}
		}
		role, apiErr := RequireActiveRole(s, u, sess, opName, "sample", "", true, allowedRoles...)
		if apiErr != nil {
			return apiErr
		}

		if strings.TrimSpace(req.IdempotencyKey) != "" {
			rec, ierr := CheckIdempotency(s, opName, u.UserID, req.IdempotencyKey, rawBody)
			if ierr != nil {
				return ierr
			}
			if rec != nil {
				cached = rec
				return nil
			}
		}

		if req.Origin == nil || req.RequestedAt == "" || req.DeliveryDeadline == "" || req.SampleTypeID == "" || strings.TrimSpace(req.ContainerType) == "" || req.TemperatureMinC == nil || req.TemperatureMaxC == nil {
			return NewErr(http.StatusBadRequest, "invalid_json", "missing required fields")
		}
		if !ValidCoordinate(*req.Origin) {
			return NewErr(http.StatusBadRequest, "invalid_origin", "invalid origin coordinates")
		}

		originType := req.OriginType
		if originType == "" {
			if presealed {
				originType = "node"
			} else {
				originType = "home"
			}
		}
		if presealed {
			if originType != "clinic" && originType != "node" {
				return NewErr(http.StatusBadRequest, "invalid_origin_type", "pre-sealed sample origin must be clinic or node")
			}
		} else {
			if originType != "home" && originType != "clinic" && originType != "node" {
				return NewErr(http.StatusBadRequest, "invalid_origin_type", "invalid originType")
			}
		}

		if req.OriginNodeID != "" {
			nodeLoc, ok := s.Locations[req.OriginNodeID]
			if !ok {
				return NewErr(http.StatusNotFound, "not_found", "originNodeId not found")
			}
			if !nodeLoc.Active {
				return NewErr(http.StatusBadRequest, "invalid_origin_state", "origin node is inactive")
			}
		}

		if presealed {
			if (role == "node_handler" || role == "laboratory_team") && u.AssignedLocationID != "" && req.OriginNodeID != "" && u.AssignedLocationID != req.OriginNodeID {
				return NewErr(http.StatusBadRequest, "invalid_holder", "worker is not assigned to the specified origin node")
			}
			if !u.Available {
				return NewErr(http.StatusConflict, "worker_unavailable", "registering worker is unavailable")
			}
		}

		reqTime, ok1 := ParseTime(req.RequestedAt)
		deadline, ok2 := ParseTime(req.DeliveryDeadline)
		if !ok1 || !ok2 {
			return NewErr(http.StatusBadRequest, "invalid_time", "invalid timestamp format")
		}
		if !deadline.After(reqTime) {
			return NewErr(http.StatusBadRequest, "invalid_deadline", "deliveryDeadline must be after requestedAt")
		}

		earliest := reqTime
		if req.EarliestCollectionAt != "" {
			t, ok := ParseTime(req.EarliestCollectionAt)
			if !ok {
				return NewErr(http.StatusBadRequest, "invalid_time", "invalid earliestCollectionAt")
			}
			earliest = t
		}
		latest := deadline
		if req.LatestCollectionAt != "" {
			t, ok := ParseTime(req.LatestCollectionAt)
			if !ok {
				return NewErr(http.StatusBadRequest, "invalid_time", "invalid latestCollectionAt")
			}
			latest = t
		}
		if earliest.After(latest) || earliest.After(deadline) || latest.Before(reqTime) || earliest.Before(reqTime) || latest.After(deadline) {
			return NewErr(http.StatusBadRequest, "invalid_collection_window", "invalid collection window")
		}

		st, ok := s.SampleTypes[req.SampleTypeID]
		if !ok {
			return NewErr(http.StatusNotFound, "not_found", "sample type not found")
		}
		if *req.TemperatureMinC > *req.TemperatureMaxC {
			return NewErr(http.StatusBadRequest, "handling_mismatch", "temperatureMinC exceeds temperatureMaxC")
		}
		if req.ContainerType != st.ContainerType || *req.TemperatureMinC < st.TemperatureMinC || *req.TemperatureMaxC > st.TemperatureMaxC {
			return NewErr(http.StatusBadRequest, "handling_mismatch", "request handling attributes do not match sample type rules")
		}

		if presealed && role == "collection_professional" {
			if okQual, _ := WorkerHasValidQualification(u, st, reqTime); !okQual {
				return NewErr(http.StatusBadRequest, "invalid_holder", "collector lacks required qualification for pre-sealed sample")
			}
		}

		requesterID := u.UserID
		if req.RequesterID != "" {
			if role == "requester" && req.RequesterID != u.UserID {
				return NewErr(http.StatusForbidden, "forbidden", "requester cannot create request for another user")
			}
			requesterID = req.RequesterID
		}

		outcome, evalErr := EvaluateServiceability(s, ServiceabilityInput{
			Origin:               *req.Origin,
			OriginType:           originType,
			OriginNodeID:         req.OriginNodeID,
			SampleTypeID:         req.SampleTypeID,
			RequestedAt:          reqTime,
			DeliveryDeadline:     deadline,
			EarliestCollectionAt: earliest,
			LatestCollectionAt:   latest,
			Units:                1,
		})
		if evalErr != nil {
			return evalErr
		}

		if !outcome.Serviceable {
			// Check if failure is due to capacity exhaustion on an otherwise reachable route
			if outcome.Reason == "insufficient_capacity" {
				if SampleTypeRequiresCooled(st) {
					return NewErr(http.StatusConflict, "cooled_capacity_exhausted", "cooled capacity is exhausted on all valid routes")
				}
				return NewErr(http.StatusConflict, "capacity_exhausted", "regular capacity is exhausted on all valid routes")
			}
		}

		requestID := uuid.NewString()
		sampleID := uuid.NewString()
		incompat := req.IncompatibleSampleTypes
		if incompat == nil {
			incompat = append([]string(nil), st.IncompatibleSampleTypes...)
		}
		if incompat == nil {
			incompat = []string{}
		}

		earliestStr := models.FormatTime(earliest)
		latestStr := models.FormatTime(latest)
		originCopy := *req.Origin

		sample := &models.Sample{
			SampleID:                 sampleID,
			RequestID:                requestID,
			RequesterID:              requesterID,
			Origin:                   originCopy,
			OriginType:               originType,
			OriginNodeID:             req.OriginNodeID,
			RequestedAt:              req.RequestedAt,
			DeliveryDeadline:         req.DeliveryDeadline,
			EarliestCollectionAt:     earliestStr,
			LatestCollectionAt:       latestStr,
			SampleTypeID:             req.SampleTypeID,
			ContainerType:            req.ContainerType,
			TemperatureMinC:          *req.TemperatureMinC,
			TemperatureMaxC:          *req.TemperatureMaxC,
			IncompatibleSampleTypes:  incompat,
			Serviceability:           "unserviceable",
			ServiceabilityReason:     outcome.Reason,
			Status:                   "unserviceable",
			Sealed:                   presealed,
			AlreadySealed:            presealed,
			CompletedLegIDs:          []string{},
			ActiveReplacementPlanIDs: []string{},
			LatestLocation:           &originCopy,
			LocationRecordedAt:       req.RequestedAt,
			LastEventAt:              req.RequestedAt,
			Timeline:                 []models.TimelineEntry{},
		}
		if presealed {
			sample.SealedAt = req.RequestedAt
			sample.CurrentHolderID = u.UserID
		}

		s.Samples[sampleID] = sample

		startTime := reqTime
		if earliest.After(startTime) {
			startTime = earliest
		}

		if outcome.Serviceable && outcome.BestRoute != nil {
			sample.Serviceability = "serviceable"
			sample.ServiceabilityReason = "serviceable"
			if presealed {
				sample.Status = "sealed"
			} else {
				sample.Status = "scheduled"
			}
			sample.TargetLaboratoryID = outcome.TargetLaboratoryID

			j := BuildJourneyFromRoute(s, sample, *outcome.BestRoute, startTime, !presealed, u, role)
			sample.ActiveJourneyID = j.JourneyID

			te := RecordAudit(s, u.UserID, role, opName, "sample", sampleID, true, req.RequestedAt, map[string]interface{}{
				"requestId":          requestID,
				"sampleId":           sampleID,
				"journeyId":          j.JourneyID,
				"targetLaboratoryId": j.TargetLaboratoryID,
				"serviceability":     "serviceable",
				"originType":         originType,
				"alreadySealed":      presealed,
			})
			AppendSampleTimeline(sample, te)
			AppendJourneyHistory(j, te)
		} else {
			te := RecordAudit(s, u.UserID, role, opName, "sample", sampleID, true, req.RequestedAt, map[string]interface{}{
				"requestId":            requestID,
				"sampleId":             sampleID,
				"serviceability":       "unserviceable",
				"serviceabilityReason": outcome.Reason,
				"originType":           originType,
			})
			AppendSampleTimeline(sample, te)
		}

		activeAssigns := SampleActiveAssignmentIDs(s, sample)
		respData = map[string]interface{}{
			"requestId":            requestID,
			"sampleId":             sampleID,
			"serviceability":       sample.Serviceability,
			"serviceabilityReason": sample.ServiceabilityReason,
			"activeAssignmentIds":  activeAssigns,
			"earliestCollectionAt": earliestStr,
			"latestCollectionAt":   latestStr,
			"alreadySealed":        presealed,
			"originType":           originType,
		}
		if sample.ActiveJourneyID != "" {
			respData["journeyId"] = sample.ActiveJourneyID
		}
		if sample.TargetLaboratoryID != "" {
			respData["targetLaboratoryId"] = sample.TargetLaboratoryID
		}

		EmitEvent(s, "sample.created", "sample", sampleID, respData)
		if req.IdempotencyKey != "" {
			SaveIdempotency(s, opName, u.UserID, req.IdempotencyKey, rawBody, http.StatusCreated, respData)
		}
		return nil
	})
	if err != nil {
		WriteError(w, err)
		return
	}
	if cached != nil {
		w.Header().Set("Content-Type", "application/json")
		w.WriteHeader(cached.StatusCode)
		_, _ = w.Write(cached.Response)
		return
	}
	WriteData(w, http.StatusCreated, respData)
}

func (srv *Server) handleAcceptAssignment(w http.ResponseWriter, r *http.Request) {
	var req struct {
		AssignmentID   string `json:"assignmentId"`
		IdempotencyKey string `json:"idempotencyKey"`
	}
	rawBody, apiErr := DecodeStrictJSON(r, &req)
	if apiErr != nil {
		WriteError(w, apiErr)
		return
	}

	var cached *models.IdempotencyRecord
	var respData map[string]interface{}
	err := srv.store.Write(r.Context(), func(s *db.State) error {
		u, sess, apiErr := AuthenticateSession(s, r)
		if apiErr != nil {
			return apiErr
		}
		role, apiErr := RequireActiveRole(s, u, sess, "accept_assignment", "assignment", req.AssignmentID, true, "collection_professional", "delivery_partner", "node_handler", "laboratory_team")
		if apiErr != nil {
			return apiErr
		}
		if strings.TrimSpace(req.IdempotencyKey) == "" {
			return NewErr(http.StatusBadRequest, "idempotency_required", "idempotencyKey is required")
		}
		if req.AssignmentID == "" {
			return NewErr(http.StatusBadRequest, "invalid_json", "assignmentId is required")
		}
		rec, ierr := CheckIdempotency(s, "accept_assignment", u.UserID, req.IdempotencyKey, rawBody)
		if ierr != nil {
			return ierr
		}
		if rec != nil {
			cached = rec
			return nil
		}

		a, ok := s.Assignments[req.AssignmentID]
		if !ok {
			return NewErr(http.StatusNotFound, "not_found", "assignment not found")
		}
		now := time.Now().UTC()
		nowStr := models.FormatTime(now)

		if j, exists := s.Journeys[a.JourneyID]; !exists || j.Status != "active" {
			return NewErr(http.StatusConflict, "assignment_inactive", "journey is no longer active")
		}
		if a.Status == "cancelled" || a.Status == "completed" {
			return NewErr(http.StatusConflict, "assignment_inactive", "assignment is no longer active")
		}
		if a.Status == "accepted" || a.Status == "at_pickup" || a.Status == "picked_up" || a.Status == "in_transit" || a.Status == "arrived" || a.Status == "delivered" || a.Status == "in_progress" {
			if a.WorkerID != u.UserID {
				return NewErr(http.StatusConflict, "assignment_taken", "assignment is already accepted by another worker")
			}
			return NewErr(http.StatusConflict, "offer_not_available", "assignment was already accepted")
		}

		if !u.Available {
			return NewErr(http.StatusConflict, "worker_unavailable", "worker is currently unavailable")
		}

		// Check role matches assignment kind
		expectedRole := ""
		switch a.Kind {
		case "collection":
			expectedRole = "collection_professional"
		case "transport":
			expectedRole = "delivery_partner"
		case "node":
			expectedRole = "node_handler"
		case "laboratory":
			expectedRole = "laboratory_team"
		}
		if role != expectedRole {
			s.IneligibleAttempts++
			RecordAudit(s, u.UserID, role, "accept_assignment", "assignment", a.AssignmentID, false, nowStr, map[string]interface{}{
				"reason":       "ineligible_worker",
				"expectedRole": expectedRole,
			})
			return NewErr(http.StatusForbidden, "ineligible_worker", "active role is not eligible for this assignment kind")
		}

		if eligible, _ := IsWorkerEligibleForAssignment(s, u, a, now, true); !eligible {
			s.IneligibleAttempts++
			RecordAudit(s, u.UserID, role, "accept_assignment", "assignment", a.AssignmentID, false, nowStr, map[string]interface{}{
				"reason": "ineligible_worker",
			})
			return NewErr(http.StatusForbidden, "ineligible_worker", "worker is not eligible for this assignment")
		}

		// Must be the worker to whom it was offered
		if a.OfferedToWorkerID == "" {
			return NewErr(http.StatusConflict, "offer_not_offered", "assignment is not currently offered")
		}
		if a.OfferedToWorkerID != u.UserID {
			RecordAudit(s, u.UserID, role, "accept_assignment", "assignment", a.AssignmentID, false, nowStr, map[string]interface{}{
				"reason":    "offer_not_offered_to_caller",
				"offeredTo": a.OfferedToWorkerID,
			})
			return NewErr(http.StatusForbidden, "forbidden", "assignment was not offered to this worker")
		}

		a.Status = "accepted"
		a.WorkerID = u.UserID
		a.AcceptedAt = nowStr

		te := RecordAudit(s, u.UserID, role, "accept_assignment", "assignment", a.AssignmentID, true, nowStr, map[string]interface{}{
			"assignmentId": a.AssignmentID,
			"sampleId":     a.SampleID,
			"workerId":     u.UserID,
			"status":       "accepted",
		})
		AppendAssignmentHistory(a, te)
		if samp, ok := s.Samples[a.SampleID]; ok {
			AppendSampleTimeline(samp, te)
		}
		if j, ok := s.Journeys[a.JourneyID]; ok {
			AppendJourneyHistory(j, te)
		}

		respData = map[string]interface{}{
			"assignmentId": a.AssignmentID,
			"workerId":     u.UserID,
			"status":       "accepted",
		}
		EmitEvent(s, "assignment.accepted", "assignment", a.AssignmentID, respData)
		SaveIdempotency(s, "accept_assignment", u.UserID, req.IdempotencyKey, rawBody, http.StatusCreated, respData)
		return nil
	})
	if err != nil {
		WriteError(w, err)
		return
	}
	if cached != nil {
		w.Header().Set("Content-Type", "application/json")
		w.WriteHeader(cached.StatusCode)
		_, _ = w.Write(cached.Response)
		return
	}
	WriteData(w, http.StatusCreated, respData)
}

func (srv *Server) handleDeclineAssignment(w http.ResponseWriter, r *http.Request) {
	var req struct {
		AssignmentID   string `json:"assignmentId"`
		Reason         string `json:"reason"`
		DeclinedAt     string `json:"declinedAt"`
		IdempotencyKey string `json:"idempotencyKey"`
	}
	rawBody, apiErr := DecodeStrictJSON(r, &req)
	if apiErr != nil {
		WriteError(w, apiErr)
		return
	}

	var cached *models.IdempotencyRecord
	var respData map[string]interface{}
	err := srv.store.Write(r.Context(), func(s *db.State) error {
		u, sess, apiErr := AuthenticateSession(s, r)
		if apiErr != nil {
			return apiErr
		}
		role, apiErr := RequireActiveRole(s, u, sess, "decline_assignment", "assignment", req.AssignmentID, true, "collection_professional", "delivery_partner", "node_handler", "laboratory_team")
		if apiErr != nil {
			return apiErr
		}
		if strings.TrimSpace(req.IdempotencyKey) == "" {
			return NewErr(http.StatusBadRequest, "idempotency_required", "idempotencyKey is required")
		}
		if req.AssignmentID == "" {
			return NewErr(http.StatusBadRequest, "invalid_json", "assignmentId is required")
		}
		declinedTime := time.Now().UTC()
		if req.DeclinedAt != "" {
			t, ok := ParseTime(req.DeclinedAt)
			if !ok {
				return NewErr(http.StatusBadRequest, "invalid_time", "invalid declinedAt timestamp")
			}
			declinedTime = t
		}
		declinedAtStr := models.FormatTime(declinedTime)

		rec, ierr := CheckIdempotency(s, "decline_assignment", u.UserID, req.IdempotencyKey, rawBody)
		if ierr != nil {
			return ierr
		}
		if rec != nil {
			cached = rec
			return nil
		}

		a, ok := s.Assignments[req.AssignmentID]
		if !ok {
			return NewErr(http.StatusNotFound, "not_found", "assignment not found")
		}
		if a.Status != "pending" {
			return NewErr(http.StatusConflict, "offer_not_available", "assignment is not in pending offered state")
		}
		if a.OfferedToWorkerID != u.UserID {
			RecordAudit(s, u.UserID, role, "decline_assignment", "assignment", a.AssignmentID, false, declinedAtStr, map[string]interface{}{
				"reason":    "not_offered_to_caller",
				"offeredTo": a.OfferedToWorkerID,
			})
			return NewErr(http.StatusForbidden, "forbidden", "assignment was not offered to this worker")
		}

		u.DeclineCount++
		u.LastDeclinedAt = declinedAtStr
		alreadyListed := false
		for _, id := range a.DeclinedByWorkerIDs {
			if id == u.UserID {
				alreadyListed = true
				break
			}
		}
		if !alreadyListed {
			a.DeclinedByWorkerIDs = append(a.DeclinedByWorkerIDs, u.UserID)
		}

		te := RecordAudit(s, u.UserID, role, "decline_assignment", "assignment", a.AssignmentID, true, declinedAtStr, map[string]interface{}{
			"assignmentId": a.AssignmentID,
			"sampleId":     a.SampleID,
			"declinedBy":   u.UserID,
			"reason":       req.Reason,
		})
		AppendAssignmentHistory(a, te)
		if samp, ok := s.Samples[a.SampleID]; ok {
			AppendSampleTimeline(samp, te)
		}

		// Re-offer to next eligible worker (excluding the declining worker first; if none other exists, can still re-offer or flag exception)
		nextWorker := OfferAssignmentToBestWorker(s, a, declinedTime, u.UserID)
		if nextWorker == nil {
			// Check if any OTHER worker in the system is eligible at all; if the declining worker is still the only eligible one, keep them eligible for future work
			nextWorker = OfferAssignmentToBestWorker(s, a, declinedTime, "")
		}

		respData = map[string]interface{}{
			"assignmentId": a.AssignmentID,
			"status":       "pending",
			"declinedBy":   u.UserID,
			"declinedAt":   declinedAtStr,
		}
		if nextWorker != nil {
			respData["reofferedTo"] = nextWorker.UserID
		} else if samp, ok := s.Samples[a.SampleID]; ok {
			FlagNoQualifiedWorkerException(s, samp, a, declinedAtStr)
		}

		EmitEvent(s, "assignment.declined", "assignment", a.AssignmentID, respData)
		SaveIdempotency(s, "decline_assignment", u.UserID, req.IdempotencyKey, rawBody, http.StatusCreated, respData)
		return nil
	})
	if err != nil {
		WriteError(w, err)
		return
	}
	if cached != nil {
		w.Header().Set("Content-Type", "application/json")
		w.WriteHeader(cached.StatusCode)
		_, _ = w.Write(cached.Response)
		return
	}
	WriteData(w, http.StatusCreated, respData)
}

func (srv *Server) handleCollectAndSealSample(w http.ResponseWriter, r *http.Request) {
	var req struct {
		SampleID             string   `json:"sampleId"`
		AssignmentID         string   `json:"assignmentId"`
		CollectedAt          string   `json:"collectedAt"`
		ContainerType        string   `json:"containerType"`
		ObservedTemperatureC *float64 `json:"observedTemperatureC"`
		IdempotencyKey       string   `json:"idempotencyKey"`
	}
	rawBody, apiErr := DecodeStrictJSON(r, &req)
	if apiErr != nil {
		WriteError(w, apiErr)
		return
	}

	var cached *models.IdempotencyRecord
	var respData map[string]interface{}
	err := srv.store.Write(r.Context(), func(s *db.State) error {
		u, sess, apiErr := AuthenticateSession(s, r)
		if apiErr != nil {
			return apiErr
		}
		role, apiErr := RequireActiveRole(s, u, sess, "collect_and_seal_sample", "sample", req.SampleID, true, "collection_professional")
		if apiErr != nil {
			return apiErr
		}
		if strings.TrimSpace(req.IdempotencyKey) == "" {
			return NewErr(http.StatusBadRequest, "idempotency_required", "idempotencyKey is required")
		}
		if req.SampleID == "" || req.AssignmentID == "" || req.CollectedAt == "" || strings.TrimSpace(req.ContainerType) == "" || req.ObservedTemperatureC == nil {
			return NewErr(http.StatusBadRequest, "invalid_json", "missing required fields")
		}
		collectedTime, ok := ParseTime(req.CollectedAt)
		if !ok {
			return NewErr(http.StatusBadRequest, "invalid_time", "invalid collectedAt timestamp")
		}
		rec, ierr := CheckIdempotency(s, "collect_and_seal_sample", u.UserID, req.IdempotencyKey, rawBody)
		if ierr != nil {
			return ierr
		}
		if rec != nil {
			cached = rec
			return nil
		}

		sample, ok := s.Samples[req.SampleID]
		if !ok {
			return NewErr(http.StatusNotFound, "not_found", "sample not found")
		}
		a, ok := s.Assignments[req.AssignmentID]
		if !ok {
			return NewErr(http.StatusNotFound, "not_found", "assignment not found")
		}
		if a.SampleID != sample.SampleID || a.Kind != "collection" {
			return NewErr(http.StatusForbidden, "forbidden", "assignment is not the collection assignment for this sample")
		}
		if a.WorkerID != u.UserID {
			return NewErr(http.StatusForbidden, "forbidden", "assignment is not assigned to this collector")
		}
		if sample.Sealed || sample.Status == "received" || sample.Status == "cancelled" || sample.Status == "expired" {
			return NewErr(http.StatusConflict, "invalid_sample_state", "sample is already sealed or in terminal state")
		}
		if a.Status == "cancelled" || a.Status == "completed" {
			return NewErr(http.StatusConflict, "assignment_inactive", "collection assignment is inactive")
		}
		if a.Status != "accepted" && a.Status != "in_progress" && a.Status != "at_pickup" {
			return NewErr(http.StatusConflict, "collection_not_ready", "collection assignment must be accepted before collecting and sealing")
		}

		// Check certification active at collectedTime
		st := s.SampleTypes[sample.SampleTypeID]
		if okQual, reason := WorkerHasValidQualification(u, st, collectedTime); !okQual {
			if reason == "certification_inactive" {
				return NewErr(http.StatusConflict, "certification_inactive", "collector certification is inactive or expired")
			}
			return NewErr(http.StatusForbidden, "forbidden", "collector lacks required qualification")
		}

		// Check collection window & deadline
		reqTime, _ := ParseTime(sample.RequestedAt)
		deadline, _ := ParseTime(sample.DeliveryDeadline)
		earliest, _ := ParseTime(sample.EarliestCollectionAt)
		latest, _ := ParseTime(sample.LatestCollectionAt)

		if collectedTime.Before(earliest) || collectedTime.After(latest) {
			return NewErr(http.StatusConflict, "outside_collection_window", "collectedAt is outside the collection window")
		}
		if collectedTime.Before(reqTime) || collectedTime.After(deadline) {
			return NewErr(http.StatusConflict, "invalid_collection_time", "collectedAt is outside request timeframe")
		}

		// Check handling compliance
		temp := *req.ObservedTemperatureC
		compliant := req.ContainerType == sample.ContainerType && temp >= sample.TemperatureMinC && temp <= sample.TemperatureMaxC
		if !compliant {
			return NewErr(http.StatusBadRequest, "handling_noncompliant", "observed container or temperature does not satisfy sample handling rules")
		}

		collectedStr := models.FormatTime(collectedTime)
		sample.Sealed = true
		sample.SealedAt = collectedStr
		sample.Status = "sealed"
		sample.CurrentHolderID = u.UserID
		sample.CompletedLegIDs = append(sample.CompletedLegIDs, a.AssignmentID)
		a.Status = "completed"
		a.CompletedAt = collectedStr

		// Mark pickup stop as completed if present
		if j, exists := s.Journeys[a.JourneyID]; exists && len(j.OrderedStops) > 0 {
			if j.OrderedStops[0].StopType == "pickup" && j.OrderedStops[0].CompletedAt == "" {
				j.OrderedStops[0].CompletedAt = collectedStr
			}
		}

		te := RecordAudit(s, u.UserID, role, "collect_and_seal_sample", "sample", sample.SampleID, true, collectedStr, map[string]interface{}{
			"sampleId":             sample.SampleID,
			"assignmentId":         a.AssignmentID,
			"currentHolderId":      u.UserID,
			"containerType":        req.ContainerType,
			"observedTemperatureC": temp,
			"handlingCompliant":    true,
		})
		AppendSampleTimeline(sample, te)
		AppendAssignmentHistory(a, te)
		if j, exists := s.Journeys[a.JourneyID]; exists {
			AppendJourneyHistory(j, te)
		}

		respData = map[string]interface{}{
			"sampleId":          sample.SampleID,
			"status":            "sealed",
			"currentHolderId":   u.UserID,
			"sealedAt":          collectedStr,
			"handlingCompliant": true,
		}
		EmitEvent(s, "sample.sealed", "sample", sample.SampleID, respData)
		SaveIdempotency(s, "collect_and_seal_sample", u.UserID, req.IdempotencyKey, rawBody, http.StatusCreated, respData)
		return nil
	})
	if err != nil {
		WriteError(w, err)
		return
	}
	if cached != nil {
		w.Header().Set("Content-Type", "application/json")
		w.WriteHeader(cached.StatusCode)
		_, _ = w.Write(cached.Response)
		return
	}
	WriteData(w, http.StatusCreated, respData)
}

func assignmentEndLocation(a *models.Assignment) string {
	switch a.Kind {
	case "collection":
		return a.ToLocationID
	case "transport":
		return a.ToLocationID
	case "node":
		if a.NodeID != "" {
			return a.NodeID
		}
		return a.ToLocationID
	case "laboratory":
		if a.LaboratoryID != "" {
			return a.LaboratoryID
		}
		return a.ToLocationID
	}
	return a.ToLocationID
}

func assignmentStartLocation(a *models.Assignment) string {
	switch a.Kind {
	case "collection":
		return a.FromLocationID
	case "transport":
		return a.FromLocationID
	case "node":
		if a.NodeID != "" {
			return a.NodeID
		}
		return a.FromLocationID
	case "laboratory":
		if a.LaboratoryID != "" {
			return a.LaboratoryID
		}
		return a.FromLocationID
	}
	return a.FromLocationID
}

func (srv *Server) handleInitiateHandoff(w http.ResponseWriter, r *http.Request) {
	var req struct {
		SampleID         string `json:"sampleId"`
		FromAssignmentID string `json:"fromAssignmentId"`
		ToAssignmentID   string `json:"toAssignmentId"`
		ReceiverID       string `json:"receiverId"`
		InitiatedAt      string `json:"initiatedAt"`
		IdempotencyKey   string `json:"idempotencyKey"`
	}
	rawBody, apiErr := DecodeStrictJSON(r, &req)
	if apiErr != nil {
		WriteError(w, apiErr)
		return
	}

	var cached *models.IdempotencyRecord
	var respData map[string]interface{}
	err := srv.store.Write(r.Context(), func(s *db.State) error {
		u, sess, apiErr := AuthenticateSession(s, r)
		if apiErr != nil {
			return apiErr
		}
		role, apiErr := RequireActiveRole(s, u, sess, "initiate_handoff", "sample", req.SampleID, true, "collection_professional", "delivery_partner", "node_handler", "laboratory_team")
		if apiErr != nil {
			return apiErr
		}
		if strings.TrimSpace(req.IdempotencyKey) == "" {
			return NewErr(http.StatusBadRequest, "idempotency_required", "idempotencyKey is required")
		}
		if req.SampleID == "" || req.FromAssignmentID == "" || req.ToAssignmentID == "" || req.ReceiverID == "" || req.InitiatedAt == "" {
			return NewErr(http.StatusBadRequest, "invalid_json", "missing required fields")
		}
		initTime, ok := ParseTime(req.InitiatedAt)
		if !ok {
			return NewErr(http.StatusBadRequest, "invalid_time", "invalid initiatedAt timestamp")
		}
		rec, ierr := CheckIdempotency(s, "initiate_handoff", u.UserID, req.IdempotencyKey, rawBody)
		if ierr != nil {
			return ierr
		}
		if rec != nil {
			cached = rec
			return nil
		}

		sample, ok := s.Samples[req.SampleID]
		if !ok {
			return NewErr(http.StatusNotFound, "not_found", "sample not found")
		}
		fromA, ok1 := s.Assignments[req.FromAssignmentID]
		toA, ok2 := s.Assignments[req.ToAssignmentID]
		if !ok1 || !ok2 {
			return NewErr(http.StatusNotFound, "not_found", "assignment not found")
		}
		receiver, ok := s.Users[req.ReceiverID]
		if !ok {
			return NewErr(http.StatusBadRequest, "invalid_receiver", "receiver not found")
		}

		if fromA.WorkerID != u.UserID {
			RecordAudit(s, u.UserID, role, "initiate_handoff", "sample", sample.SampleID, false, req.InitiatedAt, map[string]interface{}{
				"reason": "sender_assignment_mismatch",
			})
			return NewErr(http.StatusForbidden, "sender_assignment_mismatch", "caller is not the assigned worker on fromAssignmentId")
		}
		if sample.CurrentHolderID != u.UserID {
			return NewErr(http.StatusConflict, "not_current_holder", "caller is not the current custodian of the sample")
		}
		if sample.PendingHandoffID != "" {
			if ph, exists := s.Handoffs[sample.PendingHandoffID]; exists && ph.Status == "pending" {
				return NewErr(http.StatusConflict, "pending_handoff_exists", "a pending handoff already exists for this sample")
			}
		}

		if fromA.JourneyID != sample.ActiveJourneyID || toA.JourneyID != sample.ActiveJourneyID {
			return NewErr(http.StatusConflict, "invalid_handoff_route", "assignments do not belong to the sample's active journey")
		}
		if fromA.Status == "cancelled" || toA.Status == "cancelled" {
			return NewErr(http.StatusConflict, "invalid_assignment_state", "assignment is cancelled")
		}
		if !sample.Sealed {
			return NewErr(http.StatusConflict, "prior_leg_incomplete", "sample must be collected and sealed before handoff")
		}

		// If fromA is a transport leg, it must have arrived or delivered at the handoff location
		if fromA.Kind == "transport" {
			if fromA.Status != "arrived" && fromA.Status != "delivered" && fromA.Status != "completed" {
				return NewErr(http.StatusConflict, "transport_leg_incomplete", "transport leg must arrive at destination before initiating handoff")
			}
		}

		// Check sequence and adjacency
		if toA.Sequence <= fromA.Sequence {
			return NewErr(http.StatusConflict, "invalid_handoff_route", "cannot hand off backwards in journey")
		}
		fromLoc := assignmentEndLocation(fromA)
		toLoc := assignmentStartLocation(toA)
		if fromLoc != toLoc {
			return NewErr(http.StatusConflict, "nonadjacent_handoff", "fromAssignment destination does not match toAssignment origin")
		}
		// Also check there is no intermediate transport leg between fromA and toA
		if j, exists := s.Journeys[sample.ActiveJourneyID]; exists {
			for _, aid := range j.LegAssignmentIDs {
				leg := s.Assignments[aid]
				if leg != nil && leg.Sequence > fromA.Sequence && leg.Sequence < toA.Sequence {
					return NewErr(http.StatusConflict, "nonadjacent_handoff", "cannot skip an intermediate transport leg")
				}
			}
		}

		// Check receiver and toAssignment state
		if toA.Status == "pending" {
			return NewErr(http.StatusConflict, "offer_not_available", "receiver has not accepted toAssignment yet")
		}
		if toA.WorkerID != receiver.UserID {
			return NewErr(http.StatusConflict, "receiver_assignment_mismatch", "receiverId does not match worker assigned to toAssignmentId")
		}
		if (toA.Kind == "node" && receiver.AssignedLocationID != toA.NodeID) ||
			(toA.Kind == "laboratory" && receiver.AssignedLocationID != toA.LaboratoryID) {
			return NewErr(http.StatusConflict, "node_assignment_mismatch", "receiver is not assigned to the handoff node/laboratory")
		}
		if !receiver.Active || !receiver.Available {
			return NewErr(http.StatusConflict, "receiver_unavailable", "receiver is currently unavailable")
		}

		// Validate initiatedAt is not before sample's last custody/progress timestamp
		if sample.SealedAt != "" {
			if st, ok := ParseTime(sample.SealedAt); ok && initTime.Before(st) {
				return NewErr(http.StatusConflict, "invalid_handoff_time", "initiatedAt cannot be before sample sealedAt")
			}
		}
		if fromA.LastProgressAt != "" {
			if pt, ok := ParseTime(fromA.LastProgressAt); ok && initTime.Before(pt) {
				return NewErr(http.StatusConflict, "invalid_handoff_time", "initiatedAt cannot be before last progress update")
			}
		}

		initStr := models.FormatTime(initTime)
		handoff := &models.Handoff{
			HandoffID:        uuid.NewString(),
			SampleID:         sample.SampleID,
			JourneyID:        sample.ActiveJourneyID,
			FromAssignmentID: fromA.AssignmentID,
			ToAssignmentID:   toA.AssignmentID,
			SenderID:         u.UserID,
			ReceiverID:       receiver.UserID,
			Status:           "pending",
			SenderConfirmed:  false,
			ReceiverConfirmed: false,
			InitiatedAt:      initStr,
		}
		s.Handoffs[handoff.HandoffID] = handoff
		sample.PendingHandoffID = handoff.HandoffID

		te := RecordAudit(s, u.UserID, role, "initiate_handoff", "sample", sample.SampleID, true, initStr, map[string]interface{}{
			"handoffId":        handoff.HandoffID,
			"sampleId":         sample.SampleID,
			"fromAssignmentId": fromA.AssignmentID,
			"toAssignmentId":   toA.AssignmentID,
			"senderId":         u.UserID,
			"receiverId":       receiver.UserID,
			"currentHolderId":  sample.CurrentHolderID,
		})
		AppendSampleTimeline(sample, te)
		AppendAssignmentHistory(fromA, te)
		AppendAssignmentHistory(toA, te)

		respData = map[string]interface{}{
			"handoffId":       handoff.HandoffID,
			"senderId":        handoff.SenderID,
			"receiverId":      handoff.ReceiverID,
			"currentHolderId": sample.CurrentHolderID,
			"status":          "pending",
		}
		EmitEvent(s, "handoff.initiated", "handoff", handoff.HandoffID, respData)
		SaveIdempotency(s, "initiate_handoff", u.UserID, req.IdempotencyKey, rawBody, http.StatusCreated, respData)
		return nil
	})
	if err != nil {
		WriteError(w, err)
		return
	}
	if cached != nil {
		w.Header().Set("Content-Type", "application/json")
		w.WriteHeader(cached.StatusCode)
		_, _ = w.Write(cached.Response)
		return
	}
	WriteData(w, http.StatusCreated, respData)
}

func (srv *Server) handleConfirmHandoff(w http.ResponseWriter, r *http.Request) {
	var req struct {
		HandoffID        string `json:"handoffId"`
		ConfirmationSide string `json:"confirmationSide"`
		ConfirmedAt      string `json:"confirmedAt"`
		IdempotencyKey   string `json:"idempotencyKey"`
	}
	rawBody, apiErr := DecodeStrictJSON(r, &req)
	if apiErr != nil {
		WriteError(w, apiErr)
		return
	}

	var cached *models.IdempotencyRecord
	var respData map[string]interface{}
	err := srv.store.Write(r.Context(), func(s *db.State) error {
		u, sess, apiErr := AuthenticateSession(s, r)
		if apiErr != nil {
			return apiErr
		}
		role, apiErr := RequireActiveRole(s, u, sess, "confirm_handoff", "handoff", req.HandoffID, false, "collection_professional", "delivery_partner", "node_handler", "laboratory_team")
		if apiErr != nil {
			return apiErr
		}
		if strings.TrimSpace(req.IdempotencyKey) == "" {
			return NewErr(http.StatusBadRequest, "idempotency_required", "idempotencyKey is required")
		}
		if req.HandoffID == "" || req.ConfirmedAt == "" {
			return NewErr(http.StatusBadRequest, "invalid_json", "handoffId, confirmationSide, and confirmedAt are required")
		}
		if req.ConfirmationSide != "sender" && req.ConfirmationSide != "receiver" {
			return NewErr(http.StatusBadRequest, "invalid_confirmation_side", "confirmationSide must be sender or receiver")
		}
		confTime, ok := ParseTime(req.ConfirmedAt)
		if !ok {
			return NewErr(http.StatusBadRequest, "invalid_time", "invalid confirmedAt timestamp")
		}
		rec, ierr := CheckIdempotency(s, "confirm_handoff", u.UserID, req.IdempotencyKey, rawBody)
		if ierr != nil {
			return ierr
		}
		if rec != nil {
			cached = rec
			return nil
		}

		h, ok := s.Handoffs[req.HandoffID]
		if !ok {
			return NewErr(http.StatusNotFound, "not_found", "handoff not found")
		}
		sample, ok := s.Samples[h.SampleID]
		if !ok {
			return NewErr(http.StatusNotFound, "not_found", "sample not found")
		}

		if req.ConfirmationSide == "sender" && u.UserID != h.SenderID {
			RecordAudit(s, u.UserID, role, "confirm_handoff", "handoff", h.HandoffID, false, req.ConfirmedAt, map[string]interface{}{
				"reason": "not_sender",
			})
			return NewErr(http.StatusForbidden, "forbidden", "caller is not the handoff sender")
		}
		if req.ConfirmationSide == "receiver" && u.UserID != h.ReceiverID {
			RecordAudit(s, u.UserID, role, "confirm_handoff", "handoff", h.HandoffID, false, req.ConfirmedAt, map[string]interface{}{
				"reason": "not_receiver",
			})
			return NewErr(http.StatusForbidden, "forbidden", "caller is not the handoff receiver")
		}

		if h.Status == "cancelled" {
			return NewErr(http.StatusConflict, "handoff_inactive", "handoff is cancelled")
		}
		if j, exists := s.Journeys[h.JourneyID]; !exists || j.Status == "cancelled" || j.Status == "replaced" {
			return NewErr(http.StatusConflict, "handoff_inactive", "journey for handoff is inactive")
		}

		initTime, _ := ParseTime(h.InitiatedAt)
		if confTime.Before(initTime) {
			return NewErr(http.StatusConflict, "invalid_confirmation_time", "confirmedAt cannot be before handoff initiatedAt")
		}

		confStr := models.FormatTime(confTime)

		// Handle repeated confirmation on an already-confirmed handoff without duplicate transfer
		if h.Status == "confirmed" {
			if sample.CurrentHolderID != h.ReceiverID {
				return NewErr(http.StatusConflict, "custody_conflict", "sample custody has already moved to another holder")
			}
			respData = map[string]interface{}{
				"handoffId":         h.HandoffID,
				"status":            "confirmed",
				"senderConfirmed":   true,
				"receiverConfirmed": true,
				"currentHolderId":   sample.CurrentHolderID,
			}
			SaveIdempotency(s, "confirm_handoff", u.UserID, req.IdempotencyKey, rawBody, http.StatusCreated, respData)
			return nil
		}

		if sample.CurrentHolderID != h.SenderID {
			return NewErr(http.StatusConflict, "custody_conflict", "sender no longer holds custody of sample")
		}

		if req.ConfirmationSide == "sender" {
			h.SenderConfirmed = true
			if h.SenderConfirmedAt == "" {
				h.SenderConfirmedAt = confStr
			}
		} else {
			h.ReceiverConfirmed = true
			if h.ReceiverConfirmedAt == "" {
				h.ReceiverConfirmedAt = confStr
			}
		}

		if h.SenderConfirmed && h.ReceiverConfirmed {
			h.Status = "confirmed"
			h.ConfirmedAt = confStr
			sample.CurrentHolderID = h.ReceiverID
			if sample.PendingHandoffID == h.HandoffID {
				sample.PendingHandoffID = ""
			}

			fromA := s.Assignments[h.FromAssignmentID]
			toA := s.Assignments[h.ToAssignmentID]
			if fromA != nil {
				fromA.Status = "completed"
				fromA.CompletedAt = confStr
				hasCompleted := false
				for _, cid := range sample.CompletedLegIDs {
					if cid == fromA.AssignmentID {
						hasCompleted = true
						break
					}
				}
				if !hasCompleted {
					sample.CompletedLegIDs = append(sample.CompletedLegIDs, fromA.AssignmentID)
				}
				if fromA.Kind == "transport" && fromA.ConnectionID != "" {
					ReleaseResourceReservationForSample(s, sample.SampleID, "connection", fromA.ConnectionID)
				}
				if fromA.Kind == "node" && fromA.NodeID != "" {
					ReleaseResourceReservationForSample(s, sample.SampleID, "location", fromA.NodeID)
				}
				if fromA.Kind == "collection" && fromA.FromLocationID != "" {
					// If leaving collection point directly to transport courier, release collection point capacity
					if toA != nil && toA.Kind == "transport" {
						ReleaseResourceReservationForSample(s, sample.SampleID, "location", fromA.FromLocationID)
					}
				}
			}
			if toA != nil {
				if toA.Status == "accepted" {
					if toA.Kind == "transport" {
						toA.Status = "at_pickup"
					} else {
						toA.Status = "in_progress"
					}
				}
				toA.LastProgressAt = confStr
				switch toA.Kind {
				case "transport":
					sample.Status = "in_transit"
				case "node":
					sample.Status = "at_node"
				case "laboratory":
					sample.Status = "at_laboratory"
				}
			}

			// Update stop completion & sample location at the handoff location
			handoffLocID := ""
			if fromA != nil {
				handoffLocID = assignmentEndLocation(fromA)
			}
			if handoffLocID != "" {
				if loc, exists := s.Locations[handoffLocID]; exists {
					c := loc.Coordinate
					sample.LatestLocation = &c
					sample.LocationRecordedAt = confStr
				}
				if j, exists := s.Journeys[h.JourneyID]; exists {
					for idx := range j.OrderedStops {
						if j.OrderedStops[idx].LocationID == handoffLocID && j.OrderedStops[idx].StopType != "delivery" && j.OrderedStops[idx].CompletedAt == "" {
							j.OrderedStops[idx].CompletedAt = confStr
							break
						}
					}
				}
			}

			te := RecordAudit(s, u.UserID, role, "confirm_handoff", "sample", sample.SampleID, true, confStr, map[string]interface{}{
				"handoffId":         h.HandoffID,
				"sampleId":          sample.SampleID,
				"confirmationSide":  req.ConfirmationSide,
				"status":            "confirmed",
				"previousHolderId":  h.SenderID,
				"currentHolderId":   h.ReceiverID,
				"senderConfirmed":   true,
				"receiverConfirmed": true,
			})
			AppendSampleTimeline(sample, te)
			if fromA != nil {
				AppendAssignmentHistory(fromA, te)
			}
			if toA != nil {
				AppendAssignmentHistory(toA, te)
			}
			if j, exists := s.Journeys[h.JourneyID]; exists {
				AppendJourneyHistory(j, te)
			}
		} else {
			te := RecordAudit(s, u.UserID, role, "confirm_handoff", "sample", sample.SampleID, true, confStr, map[string]interface{}{
				"handoffId":         h.HandoffID,
				"sampleId":          sample.SampleID,
				"confirmationSide":  req.ConfirmationSide,
				"status":            "pending",
				"currentHolderId":   sample.CurrentHolderID,
				"senderConfirmed":   h.SenderConfirmed,
				"receiverConfirmed": h.ReceiverConfirmed,
			})
			AppendSampleTimeline(sample, te)
		}

		respData = map[string]interface{}{
			"handoffId":         h.HandoffID,
			"status":            h.Status,
			"senderConfirmed":   h.SenderConfirmed,
			"receiverConfirmed": h.ReceiverConfirmed,
			"currentHolderId":   sample.CurrentHolderID,
		}
		EmitEvent(s, "handoff.updated", "handoff", h.HandoffID, respData)
		SaveIdempotency(s, "confirm_handoff", u.UserID, req.IdempotencyKey, rawBody, http.StatusCreated, respData)
		return nil
	})
	if err != nil {
		WriteError(w, err)
		return
	}
	if cached != nil {
		w.Header().Set("Content-Type", "application/json")
		w.WriteHeader(cached.StatusCode)
		_, _ = w.Write(cached.Response)
		return
	}
	WriteData(w, http.StatusCreated, respData)
}

var validProgressStatuses = map[string]bool{
	"at_pickup":   true,
	"picked_up":   true,
	"in_transit":  true,
	"arrived":     true,
	"delivered":   true,
	"in_progress": true,
	"completed":   true,
}

func transportStateOrder(st string) int {
	switch st {
	case "accepted":
		return 1
	case "at_pickup":
		return 2
	case "picked_up":
		return 3
	case "in_progress":
		return 4
	case "in_transit":
		return 4
	case "arrived":
		return 5
	case "delivered":
		return 6
	case "completed":
		return 7
	default:
		return 0
	}
}

func (srv *Server) handleUpdateAssignmentProgress(w http.ResponseWriter, r *http.Request) {
	var req struct {
		AssignmentID   string `json:"assignmentId"`
		Status         string `json:"status"`
		OccurredAt     string `json:"occurredAt"`
		IdempotencyKey string `json:"idempotencyKey"`
	}
	rawBody, apiErr := DecodeStrictJSON(r, &req)
	if apiErr != nil {
		WriteError(w, apiErr)
		return
	}

	var cached *models.IdempotencyRecord
	var respData map[string]interface{}
	err := srv.store.Write(r.Context(), func(s *db.State) error {
		u, sess, apiErr := AuthenticateSession(s, r)
		if apiErr != nil {
			return apiErr
		}
		role, apiErr := RequireActiveRole(s, u, sess, "update_assignment_progress", "assignment", req.AssignmentID, true, "collection_professional", "delivery_partner", "node_handler", "laboratory_team")
		if apiErr != nil {
			return apiErr
		}
		if strings.TrimSpace(req.IdempotencyKey) == "" {
			return NewErr(http.StatusBadRequest, "idempotency_required", "idempotencyKey is required")
		}
		if req.AssignmentID == "" || !validProgressStatuses[req.Status] || req.OccurredAt == "" {
			return NewErr(http.StatusBadRequest, "invalid_json", "invalid assignmentId, status, or occurredAt")
		}
		occTime, ok := ParseTime(req.OccurredAt)
		if !ok {
			return NewErr(http.StatusBadRequest, "invalid_time", "invalid occurredAt timestamp")
		}
		rec, ierr := CheckIdempotency(s, "update_assignment_progress", u.UserID, req.IdempotencyKey, rawBody)
		if ierr != nil {
			return ierr
		}
		if rec != nil {
			cached = rec
			return nil
		}

		a, ok := s.Assignments[req.AssignmentID]
		if !ok {
			return NewErr(http.StatusNotFound, "not_found", "assignment not found")
		}
		if a.WorkerID != u.UserID {
			return NewErr(http.StatusForbidden, "forbidden", "assignment does not belong to caller")
		}
		if eligible, _ := IsWorkerEligibleForAssignment(s, u, a, occTime, false); !eligible {
			return NewErr(http.StatusForbidden, "ineligible_worker", "worker is no longer eligible for this assignment")
		}
		if j, exists := s.Journeys[a.JourneyID]; !exists || j.Status != "active" {
			return NewErr(http.StatusConflict, "assignment_inactive", "journey is not active")
		}
		if a.Status == "cancelled" || a.Status == "completed" {
			return NewErr(http.StatusConflict, "assignment_inactive", "assignment is already completed or cancelled")
		}
		if a.Status == "pending" {
			return NewErr(http.StatusConflict, "assignment_not_ready", "assignment must be accepted before recording progress")
		}

		sample, ok := s.Samples[a.SampleID]
		if !ok {
			return NewErr(http.StatusNotFound, "not_found", "sample not found")
		}
		if sample.Status == "received" || sample.Status == "cancelled" || sample.Status == "expired" {
			return NewErr(http.StatusConflict, "invalid_sample_state", "sample is in terminal state")
		}

		if a.Kind != "collection" && !sample.Sealed {
			return NewErr(http.StatusConflict, "collection_required", "sample must be collected and sealed before transport progress")
		}

		// Check prior transport legs completed
		if j, exists := s.Journeys[a.JourneyID]; exists {
			for _, lid := range j.LegAssignmentIDs {
				leg := s.Assignments[lid]
				if leg != nil && leg.Sequence < a.Sequence && leg.Status != "completed" && leg.Status != "delivered" {
					return NewErr(http.StatusConflict, "prior_leg_incomplete", "prior transport leg is not yet completed")
				}
			}
		}

		// Custody requirement for transport progress beyond at_pickup
		if a.Kind == "transport" && req.Status != "at_pickup" {
			if sample.CurrentHolderID != u.UserID {
				return NewErr(http.StatusConflict, "custody_required", "worker must hold confirmed custody of sample before picking up or delivering")
			}
		}
		if (a.Kind == "node" || a.Kind == "laboratory") && sample.CurrentHolderID != u.UserID {
			return NewErr(http.StatusConflict, "custody_required", "worker must hold confirmed custody of sample")
		}

		// Check valid state transition for transport leg: pickup must happen before delivery
		if a.Kind == "transport" {
			curOrder := transportStateOrder(a.Status)
			nextOrder := transportStateOrder(req.Status)
			if nextOrder < curOrder {
				return NewErr(http.StatusConflict, "invalid_transition", "cannot transition backwards in transport leg progress")
			}
			if (req.Status == "delivered" || req.Status == "completed") && !a.PickedUpRecorded && a.Status != "picked_up" && a.Status != "in_transit" && a.Status != "arrived" {
				return NewErr(http.StatusConflict, "invalid_transition", "pickup must happen before delivery")
			}
		}

		// Timestamp checks
		if a.LastProgressAt != "" {
			if prevT, ok := ParseTime(a.LastProgressAt); ok && occTime.Before(prevT) {
				return NewErr(http.StatusConflict, "invalid_progress_time", "occurredAt cannot be earlier than previous progress update")
			}
		}
		if sample.SealedAt != "" {
			if st, ok := ParseTime(sample.SealedAt); ok && occTime.Before(st) {
				return NewErr(http.StatusConflict, "invalid_progress_time", "occurredAt cannot be earlier than sample sealedAt")
			}
		}
		if deadline, ok := ParseTime(sample.DeliveryDeadline); ok && occTime.After(deadline) {
			return NewErr(http.StatusConflict, "delivery_deadline_exceeded", "progress timestamp exceeds sample delivery deadline")
		}

		occStr := models.FormatTime(occTime)
		a.Status = req.Status
		a.LastProgressAt = occStr
		if req.Status == "picked_up" || req.Status == "in_transit" {
			a.PickedUpRecorded = true
			if a.FromLocationID != "" {
				ReleaseResourceReservationForSample(s, sample.SampleID, "location", a.FromLocationID)
			}
		}
		if req.Status == "arrived" || req.Status == "delivered" {
			a.ArrivedRecorded = true
			if a.ToLocationID != "" {
				if loc, exists := s.Locations[a.ToLocationID]; exists {
					c := loc.Coordinate
					sample.LatestLocation = &c
					sample.LocationRecordedAt = occStr
				}
			}
		}
		if req.Status == "completed" {
			a.CompletedAt = occStr
		}

		// Update all samples in the journey if batched
		var targetSamples []*models.Sample
		if j, exists := s.Journeys[a.JourneyID]; exists {
			for _, sid := range j.SampleIDs {
				if sp, ok := s.Samples[sid]; ok {
					targetSamples = append(targetSamples, sp)
				}
			}
		}
		if len(targetSamples) == 0 {
			targetSamples = []*models.Sample{sample}
		}

		te := RecordAudit(s, u.UserID, role, "update_assignment_progress", "assignment", a.AssignmentID, true, occStr, map[string]interface{}{
			"assignmentId": a.AssignmentID,
			"sampleId":     sample.SampleID,
			"status":       req.Status,
		})
		AppendAssignmentHistory(a, te)
		for _, sp := range targetSamples {
			if req.Status == "picked_up" || req.Status == "in_transit" {
				sp.Status = "in_transit"
			}
			AppendSampleTimeline(sp, te)
		}
		if j, exists := s.Journeys[a.JourneyID]; exists {
			AppendJourneyHistory(j, te)
		}

		respData = map[string]interface{}{
			"assignmentId": a.AssignmentID,
			"sampleId":     sample.SampleID,
			"status":       a.Status,
		}
		EmitEvent(s, "assignment.progress", "assignment", a.AssignmentID, respData)
		SaveIdempotency(s, "update_assignment_progress", u.UserID, req.IdempotencyKey, rawBody, http.StatusCreated, respData)
		return nil
	})
	if err != nil {
		WriteError(w, err)
		return
	}
	if cached != nil {
		w.Header().Set("Content-Type", "application/json")
		w.WriteHeader(cached.StatusCode)
		_, _ = w.Write(cached.Response)
		return
	}
	WriteData(w, http.StatusCreated, respData)
}

func (srv *Server) handleConfirmLaboratoryReceipt(w http.ResponseWriter, r *http.Request) {
	var req struct {
		SampleID       string `json:"sampleId"`
		LaboratoryID   string `json:"laboratoryId"`
		ReceivedAt     string `json:"receivedAt"`
		IdempotencyKey string `json:"idempotencyKey"`
	}
	rawBody, apiErr := DecodeStrictJSON(r, &req)
	if apiErr != nil {
		WriteError(w, apiErr)
		return
	}

	var cached *models.IdempotencyRecord
	var respData map[string]interface{}
	err := srv.store.Write(r.Context(), func(s *db.State) error {
		u, sess, apiErr := AuthenticateSession(s, r)
		if apiErr != nil {
			return apiErr
		}
		role, apiErr := RequireActiveRole(s, u, sess, "confirm_laboratory_receipt", "sample", req.SampleID, true, "laboratory_team")
		if apiErr != nil {
			return apiErr
		}
		if strings.TrimSpace(req.IdempotencyKey) == "" {
			return NewErr(http.StatusBadRequest, "idempotency_required", "idempotencyKey is required")
		}
		if req.SampleID == "" || req.LaboratoryID == "" || req.ReceivedAt == "" {
			return NewErr(http.StatusBadRequest, "invalid_json", "sampleId, laboratoryId, and receivedAt are required")
		}
		recTime, ok := ParseTime(req.ReceivedAt)
		if !ok {
			return NewErr(http.StatusBadRequest, "invalid_time", "invalid receivedAt timestamp")
		}
		rec, ierr := CheckIdempotency(s, "confirm_laboratory_receipt", u.UserID, req.IdempotencyKey, rawBody)
		if ierr != nil {
			return ierr
		}
		if rec != nil {
			cached = rec
			return nil
		}

		sample, ok := s.Samples[req.SampleID]
		if !ok {
			return NewErr(http.StatusNotFound, "not_found", "sample not found")
		}
		lab, ok := s.Locations[req.LaboratoryID]
		if !ok {
			return NewErr(http.StatusNotFound, "not_found", "laboratory not found")
		}
		if u.AssignedLocationID != req.LaboratoryID {
			RecordAudit(s, u.UserID, role, "confirm_laboratory_receipt", "sample", sample.SampleID, false, req.ReceivedAt, map[string]interface{}{
				"reason":             "wrong_laboratory_operator",
				"assignedLocationId": u.AssignedLocationID,
				"laboratoryId":       req.LaboratoryID,
			})
			return NewErr(http.StatusForbidden, "wrong_laboratory_operator", "operator is not assigned to this laboratory")
		}
		if !lab.Active || !lab.Functions.Laboratory || !LabAcceptsSampleType(s, req.LaboratoryID, sample.SampleTypeID) {
			return NewErr(http.StatusConflict, "laboratory_unavailable", "laboratory is inactive or does not accept this sample type")
		}
		if sample.PendingHandoffID != "" {
			if ph, exists := s.Handoffs[sample.PendingHandoffID]; exists && ph.Status == "pending" {
				return NewErr(http.StatusConflict, "pending_handoff_exists", "handoff to laboratory is still pending confirmation")
			}
		}
		if sample.CurrentHolderID != u.UserID {
			return NewErr(http.StatusConflict, "custody_conflict", "laboratory operator does not hold confirmed custody of sample")
		}
		if !sample.Sealed {
			return NewErr(http.StatusConflict, "receipt_not_ready", "sample is not sealed")
		}
		if j, exists := s.Journeys[sample.ActiveJourneyID]; exists {
			for _, lid := range j.LegAssignmentIDs {
				if leg, ok := s.Assignments[lid]; ok && leg.Status != "completed" {
					return NewErr(http.StatusConflict, "receipt_not_ready", "transport legs are not completed")
				}
			}
		}
		if sample.LastEventAt != "" {
			if lastT, ok := ParseTime(sample.LastEventAt); ok && recTime.Before(lastT) {
				return NewErr(http.StatusConflict, "invalid_receipt_time", "receivedAt cannot be earlier than last custody event")
			}
		}
		if deadline, ok := ParseTime(sample.DeliveryDeadline); ok && recTime.After(deadline) {
			return NewErr(http.StatusConflict, "delivery_deadline_exceeded", "receivedAt is after deliveryDeadline")
		}

		recStr := models.FormatTime(recTime)
		sample.Status = "received"
		sample.ReceivedLaboratoryID = req.LaboratoryID
		sample.ReceivedAt = recStr
		c := lab.Coordinate
		sample.LatestLocation = &c
		sample.LocationRecordedAt = recStr

		// Complete laboratory assignment and release capacity reservations for this sample
		ReleaseSampleCapacity(s, sample.SampleID)

		if j, exists := s.Journeys[sample.ActiveJourneyID]; exists {
			for _, aid := range j.LaboratoryAssignmentIDs {
				if la, ok := s.Assignments[aid]; ok {
					la.Status = "completed"
					la.CompletedAt = recStr
					sample.CompletedLegIDs = append(sample.CompletedLegIDs, la.AssignmentID)
				}
			}
			if len(j.OrderedStops) > 0 {
				j.OrderedStops[len(j.OrderedStops)-1].CompletedAt = recStr
			}
			allReceived := true
			for _, sid := range j.SampleIDs {
				if sp, ok := s.Samples[sid]; ok && sp.Status != "received" {
					allReceived = false
					break
				}
			}
			if allReceived {
				j.Status = "completed"
			}
		}

		te := RecordAudit(s, u.UserID, role, "confirm_laboratory_receipt", "sample", sample.SampleID, true, recStr, map[string]interface{}{
			"sampleId":     sample.SampleID,
			"laboratoryId": req.LaboratoryID,
			"status":       "received",
			"receivedAt":   recStr,
		})
		AppendSampleTimeline(sample, te)
		if j, exists := s.Journeys[sample.ActiveJourneyID]; exists {
			AppendJourneyHistory(j, te)
			for _, aid := range j.LaboratoryAssignmentIDs {
				if la, ok := s.Assignments[aid]; ok {
					AppendAssignmentHistory(la, te)
				}
			}
		}

		respData = map[string]interface{}{
			"sampleId":     sample.SampleID,
			"laboratoryId": req.LaboratoryID,
			"status":       "received",
			"receivedAt":   recStr,
		}
		EmitEvent(s, "sample.received", "sample", sample.SampleID, respData)
		SaveIdempotency(s, "confirm_laboratory_receipt", u.UserID, req.IdempotencyKey, rawBody, http.StatusCreated, respData)
		return nil
	})
	if err != nil {
		WriteError(w, err)
		return
	}
	if cached != nil {
		w.Header().Set("Content-Type", "application/json")
		w.WriteHeader(cached.StatusCode)
		_, _ = w.Write(cached.Response)
		return
	}
	WriteData(w, http.StatusCreated, respData)
}

func (srv *Server) handleRecordLaboratoryException(w http.ResponseWriter, r *http.Request) {
	var req struct {
		SampleID       string `json:"sampleId"`
		LaboratoryID   string `json:"laboratoryId"`
		Reason         string `json:"reason"`
		ObservedAt     string `json:"observedAt"`
		IdempotencyKey string `json:"idempotencyKey"`
	}
	rawBody, apiErr := DecodeStrictJSON(r, &req)
	if apiErr != nil {
		WriteError(w, apiErr)
		return
	}

	var cached *models.IdempotencyRecord
	var respData map[string]interface{}
	err := srv.store.Write(r.Context(), func(s *db.State) error {
		u, sess, apiErr := AuthenticateSession(s, r)
		if apiErr != nil {
			return apiErr
		}
		role, apiErr := RequireActiveRole(s, u, sess, "record_laboratory_exception", "sample", req.SampleID, true, "laboratory_team")
		if apiErr != nil {
			return apiErr
		}
		if strings.TrimSpace(req.IdempotencyKey) == "" {
			return NewErr(http.StatusBadRequest, "idempotency_required", "idempotencyKey is required")
		}
		if req.SampleID == "" || req.LaboratoryID == "" || strings.TrimSpace(req.Reason) == "" || req.ObservedAt == "" {
			return NewErr(http.StatusBadRequest, "invalid_json", "sampleId, laboratoryId, reason, and observedAt are required")
		}
		obsTime, ok := ParseTime(req.ObservedAt)
		if !ok {
			return NewErr(http.StatusBadRequest, "invalid_time", "invalid observedAt timestamp")
		}
		rec, ierr := CheckIdempotency(s, "record_laboratory_exception", u.UserID, req.IdempotencyKey, rawBody)
		if ierr != nil {
			return ierr
		}
		if rec != nil {
			cached = rec
			return nil
		}

		sample, ok := s.Samples[req.SampleID]
		if !ok {
			return NewErr(http.StatusNotFound, "not_found", "sample not found")
		}
		if _, ok := s.Locations[req.LaboratoryID]; !ok {
			return NewErr(http.StatusNotFound, "not_found", "laboratory not found")
		}
		if u.AssignedLocationID != req.LaboratoryID {
			return NewErr(http.StatusForbidden, "wrong_laboratory_operator", "operator is not assigned to this laboratory")
		}
		if sample.TargetLaboratoryID != "" && sample.TargetLaboratoryID != req.LaboratoryID {
			return NewErr(http.StatusConflict, "wrong_laboratory", "sample is not routed to this laboratory")
		}
		if j, exists := s.Journeys[sample.ActiveJourneyID]; !exists || j.Status == "cancelled" {
			return NewErr(http.StatusConflict, "journey_inactive", "journey is not active")
		}
		if sample.CurrentHolderID != u.UserID {
			return NewErr(http.StatusConflict, "laboratory_not_ready", "laboratory operator does not yet hold custody of sample")
		}
		if sample.LastEventAt != "" {
			if lastT, ok := ParseTime(sample.LastEventAt); ok && obsTime.Before(lastT) {
				return NewErr(http.StatusConflict, "invalid_exception_time", "observedAt cannot be earlier than custody transfer")
			}
		}

		obsStr := models.FormatTime(obsTime)
		excID := uuid.NewString()
		sample.Status = "exception"
		sample.Exception = map[string]interface{}{
			"exceptionId":  excID,
			"sampleId":     sample.SampleID,
			"laboratoryId": req.LaboratoryID,
			"reason":       req.Reason,
			"status":       "exception",
			"observedAt":   obsStr,
		}
		s.Exceptions[excID] = &models.ExceptionRecord{
			ExceptionID:  excID,
			SampleID:     sample.SampleID,
			LaboratoryID: req.LaboratoryID,
			Reason:       req.Reason,
			Status:       "exception",
			ObservedAt:   obsStr,
		}
		ReleaseSampleCapacity(s, sample.SampleID)

		te := RecordAudit(s, u.UserID, role, "record_laboratory_exception", "sample", sample.SampleID, true, obsStr, map[string]interface{}{
			"exceptionId":  excID,
			"sampleId":     sample.SampleID,
			"laboratoryId": req.LaboratoryID,
			"reason":       req.Reason,
			"status":       "exception",
		})
		AppendSampleTimeline(sample, te)

		respData = map[string]interface{}{
			"exceptionId": excID,
			"sampleId":    sample.SampleID,
			"status":      "exception",
			"reason":      req.Reason,
		}
		EmitEvent(s, "sample.exception", "sample", sample.SampleID, respData)
		SaveIdempotency(s, "record_laboratory_exception", u.UserID, req.IdempotencyKey, rawBody, http.StatusCreated, respData)
		return nil
	})
	if err != nil {
		WriteError(w, err)
		return
	}
	if cached != nil {
		w.Header().Set("Content-Type", "application/json")
		w.WriteHeader(cached.StatusCode)
		_, _ = w.Write(cached.Response)
		return
	}
	WriteData(w, http.StatusCreated, respData)
}

func (srv *Server) handleRecordHandlingCheckpoint(w http.ResponseWriter, r *http.Request) {
	var req struct {
		SampleID             string   `json:"sampleId"`
		AssignmentID         string   `json:"assignmentId"`
		LocationID           string   `json:"locationId"`
		ContainerType        string   `json:"containerType"`
		ObservedTemperatureC *float64 `json:"observedTemperatureC"`
		RecordedAt           string   `json:"recordedAt"`
		IdempotencyKey       string   `json:"idempotencyKey"`
	}
	rawBody, apiErr := DecodeStrictJSON(r, &req)
	if apiErr != nil {
		WriteError(w, apiErr)
		return
	}

	var cached *models.IdempotencyRecord
	var respData map[string]interface{}
	err := srv.store.Write(r.Context(), func(s *db.State) error {
		u, sess, apiErr := AuthenticateSession(s, r)
		if apiErr != nil {
			return apiErr
		}
		role, apiErr := RequireActiveRole(s, u, sess, "record_handling_checkpoint", "sample", req.SampleID, true, "collection_professional", "delivery_partner", "node_handler", "laboratory_team")
		if apiErr != nil {
			return apiErr
		}
		if strings.TrimSpace(req.IdempotencyKey) == "" {
			return NewErr(http.StatusBadRequest, "idempotency_required", "idempotencyKey is required")
		}
		if req.SampleID == "" || req.AssignmentID == "" || strings.TrimSpace(req.ContainerType) == "" || req.ObservedTemperatureC == nil || req.RecordedAt == "" {
			return NewErr(http.StatusBadRequest, "invalid_json", "missing required fields")
		}
		recTime, ok := ParseTime(req.RecordedAt)
		if !ok {
			return NewErr(http.StatusBadRequest, "invalid_time", "invalid recordedAt timestamp")
		}
		rec, ierr := CheckIdempotency(s, "record_handling_checkpoint", u.UserID, req.IdempotencyKey, rawBody)
		if ierr != nil {
			return ierr
		}
		if rec != nil {
			cached = rec
			return nil
		}

		sample, ok := s.Samples[req.SampleID]
		if !ok {
			return NewErr(http.StatusNotFound, "not_found", "sample not found")
		}
		a, ok := s.Assignments[req.AssignmentID]
		if !ok {
			return NewErr(http.StatusNotFound, "not_found", "assignment not found")
		}
		if sample.Status == "received" || sample.Status == "cancelled" || sample.Status == "expired" {
			return NewErr(http.StatusConflict, "terminal_sample", "sample is already in a terminal state")
		}
		if j, exists := s.Journeys[sample.ActiveJourneyID]; !exists || j.Status != "active" {
			return NewErr(http.StatusConflict, "journey_inactive", "journey is inactive")
		}
		if a.Status == "cancelled" {
			return NewErr(http.StatusConflict, "assignment_inactive", "assignment is inactive")
		}
		if sample.CurrentHolderID != u.UserID || a.WorkerID != u.UserID {
			RecordAudit(s, u.UserID, role, "record_handling_checkpoint", "sample", sample.SampleID, false, req.RecordedAt, map[string]interface{}{
				"reason":          "not_current_holder",
				"currentHolderId": sample.CurrentHolderID,
			})
			return NewErr(http.StatusForbidden, "forbidden", "only the current custodian holding the sample may record a handling checkpoint")
		}
		if sample.SealedAt != "" {
			if st, ok := ParseTime(sample.SealedAt); ok && recTime.Before(st) {
				return NewErr(http.StatusConflict, "invalid_checkpoint_time", "recordedAt cannot be earlier than sample sealedAt")
			}
		}

		temp := *req.ObservedTemperatureC
		compliant := req.ContainerType == sample.ContainerType && temp >= sample.TemperatureMinC && temp <= sample.TemperatureMaxC
		recStr := models.FormatTime(recTime)
		cpID := uuid.NewString()

		s.Checkpoints[cpID] = &models.Checkpoint{
			CheckpointID:         cpID,
			SampleID:             sample.SampleID,
			AssignmentID:         a.AssignmentID,
			LocationID:           req.LocationID,
			ContainerType:        req.ContainerType,
			ObservedTemperatureC: temp,
			Compliant:            compliant,
			RecordedAt:           recStr,
		}

		if !compliant {
			excID := uuid.NewString()
			reason := "handling_noncompliant"
			if req.ContainerType != sample.ContainerType {
				reason = "container_mismatch"
			} else {
				reason = "temperature_excursion"
			}
			sample.Status = "exception"
			sample.Exception = map[string]interface{}{
				"exceptionId":          excID,
				"checkpointId":         cpID,
				"sampleId":             sample.SampleID,
				"reason":               reason,
				"containerType":        req.ContainerType,
				"observedTemperatureC": temp,
				"observedAt":           recStr,
			}
			s.Exceptions[excID] = &models.ExceptionRecord{
				ExceptionID: excID,
				SampleID:    sample.SampleID,
				Reason:      reason,
				Status:      "exception",
				ObservedAt:  recStr,
			}
		}

		te := RecordAudit(s, u.UserID, role, "record_handling_checkpoint", "sample", sample.SampleID, true, recStr, map[string]interface{}{
			"checkpointId":         cpID,
			"sampleId":             sample.SampleID,
			"assignmentId":         a.AssignmentID,
			"containerType":        req.ContainerType,
			"observedTemperatureC": temp,
			"compliant":            compliant,
			"sampleStatus":         sample.Status,
		})
		AppendSampleTimeline(sample, te)
		AppendAssignmentHistory(a, te)

		respData = map[string]interface{}{
			"checkpointId": cpID,
			"sampleId":     sample.SampleID,
			"compliant":    compliant,
			"sampleStatus": sample.Status,
		}
		EmitEvent(s, "sample.checkpoint", "sample", sample.SampleID, respData)
		SaveIdempotency(s, "record_handling_checkpoint", u.UserID, req.IdempotencyKey, rawBody, http.StatusCreated, respData)
		return nil
	})
	if err != nil {
		WriteError(w, err)
		return
	}
	if cached != nil {
		w.Header().Set("Content-Type", "application/json")
		w.WriteHeader(cached.StatusCode)
		_, _ = w.Write(cached.Response)
		return
	}
	WriteData(w, http.StatusCreated, respData)
}

func (srv *Server) handleRecordWorkerLocation(w http.ResponseWriter, r *http.Request) {
	var req struct {
		AssignmentID string             `json:"assignmentId"`
		Coordinate   *models.Coordinate `json:"coordinate"`
		Sequence     *int               `json:"sequence"`
		RecordedAt   string             `json:"recordedAt"`
	}
	if _, apiErr := DecodeStrictJSON(r, &req); apiErr != nil {
		WriteError(w, apiErr)
		return
	}

	var respData map[string]interface{}
	err := srv.store.Write(r.Context(), func(s *db.State) error {
		u, sess, apiErr := AuthenticateSession(s, r)
		if apiErr != nil {
			return apiErr
		}
		role, apiErr := RequireActiveRole(s, u, sess, "record_worker_location", "assignment", req.AssignmentID, true, "collection_professional", "delivery_partner", "node_handler", "laboratory_team")
		if apiErr != nil {
			return apiErr
		}
		if req.AssignmentID == "" || req.Coordinate == nil || req.Sequence == nil || req.RecordedAt == "" {
			return NewErr(http.StatusBadRequest, "invalid_json", "assignmentId, coordinate, sequence, and recordedAt are required")
		}
		if !ValidCoordinate(*req.Coordinate) {
			return NewErr(http.StatusBadRequest, "invalid_coordinate", "coordinate out of bounds")
		}
		if *req.Sequence < 1 {
			return NewErr(http.StatusBadRequest, "invalid_sequence", "sequence must be >= 1")
		}
		recTime, ok := ParseTime(req.RecordedAt)
		if !ok {
			return NewErr(http.StatusBadRequest, "invalid_time", "invalid recordedAt timestamp")
		}

		a, ok := s.Assignments[req.AssignmentID]
		if !ok {
			return NewErr(http.StatusNotFound, "not_found", "assignment not found")
		}
		if a.WorkerID != u.UserID {
			return NewErr(http.StatusForbidden, "forbidden", "assignment does not belong to caller")
		}

		if *req.Sequence <= a.LastLocationSequence {
			return NewErr(http.StatusConflict, "stale_location", "location sequence is older than or equal to latest recorded sequence")
		}
		if a.LastLocationAt != "" {
			if prevT, ok := ParseTime(a.LastLocationAt); ok && recTime.Before(prevT) {
				return NewErr(http.StatusConflict, "stale_location", "recordedAt is older than latest recorded location timestamp")
			}
		}

		recStr := models.FormatTime(recTime)
		coordCopy := *req.Coordinate
		a.LastLocationSequence = *req.Sequence
		a.LastLocationAt = recStr
		a.LatestCoordinate = &coordCopy

		u.LatestLocation = &coordCopy
		u.LocationRecordedAt = recStr
		u.LastLocationSequence = *req.Sequence

		// Update sample location for samples held by this worker or on this assignment
		if samp, exists := s.Samples[a.SampleID]; exists {
			if samp.CurrentHolderID == u.UserID || samp.CurrentHolderID == "" {
				c := coordCopy
				samp.LatestLocation = &c
				samp.LocationRecordedAt = recStr
				samp.HasExplicitWorkerLocation = true
			}
		}
		if j, exists := s.Journeys[a.JourneyID]; exists {
			for _, sid := range j.SampleIDs {
				if samp, ok := s.Samples[sid]; ok && (samp.CurrentHolderID == u.UserID || samp.CurrentHolderID == "") {
					c := coordCopy
					samp.LatestLocation = &c
					samp.LocationRecordedAt = recStr
					samp.HasExplicitWorkerLocation = true
				}
			}
		}

		te := RecordAudit(s, u.UserID, role, "record_worker_location", "assignment", a.AssignmentID, true, recStr, map[string]interface{}{
			"assignmentId": a.AssignmentID,
			"sampleId":     a.SampleID,
			"coordinate":   coordCopy,
			"sequence":     *req.Sequence,
			"recordedAt":   recStr,
		})
		AppendAssignmentHistory(a, te)
		if samp, exists := s.Samples[a.SampleID]; exists {
			// Do not advance LastEventAt ahead of LocationRecordedAt when recording a deliberately old location
			samp.Timeline = append(samp.Timeline, te)
		}

		respData = map[string]interface{}{
			"assignmentId": a.AssignmentID,
			"coordinate":   coordCopy,
			"sequence":     *req.Sequence,
			"recordedAt":   recStr,
		}
		EmitEvent(s, "worker.location", "user", u.UserID, respData)
		return nil
	})
	if err != nil {
		WriteError(w, err)
		return
	}
	_ = json.Marshal
	WriteData(w, http.StatusCreated, respData)
}
