func (srv *Server) handleCancelJourney(w http.ResponseWriter, r *http.Request) {
	var req struct {
		JourneyID           string `json:"journeyId"`
		ExpectedPlanVersion *int   `json:"expectedPlanVersion"`
		Reason              string `json:"reason"`
		IdempotencyKey      string `json:"idempotencyKey"`
	}
	rawBody, apiErr := DecodeStrictJSON(r, &req)
	if apiErr != nil {
		WriteError(w, apiErr)
		return
	}

	var cached *models.IdempotencyRecord
	var respData map[string]interface{}
	err := srv.store.Write(r.Context(), func(s *db.State) error {
		u, sess, apiErr := AuthenticateSession(s, r)
		if apiErr != nil {
			return apiErr
		}
		role, apiErr := RequireActiveRole(s, u, sess, "cancel_journey", "journey", req.JourneyID, true, "dispatcher", "administrator")
		if apiErr != nil {
			return apiErr
		}
		if strings.TrimSpace(req.IdempotencyKey) == "" {
			return NewErr(http.StatusBadRequest, "idempotency_required", "idempotencyKey is required")
		}
		if req.JourneyID == "" || req.ExpectedPlanVersion == nil {
			return NewErr(http.StatusBadRequest, "invalid_json", "journeyId and expectedPlanVersion are required")
		}
		if *req.ExpectedPlanVersion < 1 {
			return NewErr(http.StatusBadRequest, "invalid_plan_version", "expectedPlanVersion must be >= 1")
		}
		rec, ierr := CheckIdempotency(s, "cancel_journey", u.UserID, req.IdempotencyKey, rawBody)
		if ierr != nil {
			return ierr
		}
		if rec != nil {
			cached = rec
			return nil
		}

		j, ok := s.Journeys[req.JourneyID]
		if !ok {
			return NewErr(http.StatusNotFound, "not_found", "journey not found")
		}
		if j.Status != "active" {
			return NewErr(http.StatusConflict, "inactive_plan", "journey is no longer active")
		}
		if j.PlanVersion != *req.ExpectedPlanVersion {
			return NewErr(http.StatusConflict, "stale_plan", "expectedPlanVersion does not match current journey planVersion")
		}

		nowStr := models.FormatTime(time.Now())
		j.Status = "cancelled"
		j.PlanVersion++

		// Cancel only unfinished assignments; preserve completed work
		for _, aid := range j.AssignmentIDs {
			if a, exists := s.Assignments[aid]; exists && a.Status != "completed" {
				a.Status = "cancelled"
			}
		}
		ReleaseJourneyCapacity(s, j.JourneyID)

		for _, sid := range j.SampleIDs {
			if samp, exists := s.Samples[sid]; exists && samp.Status != "received" {
				samp.Status = "cancelled"
				if samp.PendingHandoffID != "" {
					if ph, ok := s.Handoffs[samp.PendingHandoffID]; ok && ph.Status == "pending" {
						ph.Status = "cancelled"
					}
					samp.PendingHandoffID = ""
				}
			}
		}

		te := RecordAudit(s, u.UserID, role, "cancel_journey", "journey", j.JourneyID, true, nowStr, map[string]interface{}{
			"journeyId":   j.JourneyID,
			"planVersion": j.PlanVersion,
			"reason":      req.Reason,
			"sampleIds":   j.SampleIDs,
		})
		AppendJourneyHistory(j, te)
		for _, sid := range j.SampleIDs {
			if samp, exists := s.Samples[sid]; exists {
				AppendSampleTimeline(samp, te)
			}
		}

		respData = map[string]interface{}{
			"journeyId": j.JourneyID,
			"status":    "cancelled",
			"sampleIds": j.SampleIDs,
		}
		EmitEvent(s, "journey.cancelled", "journey", j.JourneyID, respData)
		SaveIdempotency(s, "cancel_journey", u.UserID, req.IdempotencyKey, rawBody, http.StatusCreated, respData)
		return nil
	})
	if err != nil {
		WriteError(w, err)
		return
	}
	if cached != nil {
		w.Header().Set("Content-Type", "application/json")
		w.WriteHeader(cached.StatusCode)
		_, _ = w.Write(cached.Response)
		return
	}
	WriteData(w, http.StatusCreated, respData)
}

func validateBatchMerge(s *db.State, targetJ *models.Journey, sourceJourneys []*models.Journey) *APIError {
	// Check if target or source journeys have completed or in-progress transport work that prevents full batch merge
	for _, aid := range targetJ.LegAssignmentIDs {
		if a, ok := s.Assignments[aid]; ok {
			if a.Status == "completed" || a.Status == "delivered" {
				return NewErr(http.StatusConflict, "completed_work_immutable", "cannot merge into a journey with completed transport legs")
			}
			if a.Status == "picked_up" || a.Status == "in_transit" {
				return NewErr(http.StatusConflict, "work_in_progress", "cannot merge into a transport leg already in transit")
			}
		}
	}
	for _, sj := range sourceJourneys {
		for _, aid := range sj.LegAssignmentIDs {
			if a, ok := s.Assignments[aid]; ok {
				if a.Status == "completed" || a.Status == "delivered" {
					return NewErr(http.StatusConflict, "partial_journey_merge", "cannot merge a journey that has already completed transport legs")
				}
				if a.Status == "picked_up" || a.Status == "in_transit" {
					return NewErr(http.StatusConflict, "work_in_progress", "cannot merge a journey with transport leg in transit")
				}
			}
		}
		// Check start and destination compatibility
		if len(sj.OrderedStops) > 0 && len(targetJ.OrderedStops) > 0 {
			if sj.OrderedStops[0].LocationID != targetJ.OrderedStops[0].LocationID {
				return NewErr(http.StatusConflict, "invalid_merge", "journeys do not share the same pickup origin location")
			}
			if sj.TargetLaboratoryID != targetJ.TargetLaboratoryID {
				return NewErr(http.StatusConflict, "invalid_destination", "journeys do not share the same destination laboratory")
			}
		}
	}

	// Collect all samples
	var allSamples []*models.Sample
	seenSample := make(map[string]bool)
	for _, sid := range targetJ.SampleIDs {
		if samp, ok := s.Samples[sid]; ok && !seenSample[sid] {
			seenSample[sid] = true
			allSamples = append(allSamples, samp)
		}
	}
	for _, sj := range sourceJourneys {
		for _, sid := range sj.SampleIDs {
			if samp, ok := s.Samples[sid]; ok && !seenSample[sid] {
				seenSample[sid] = true
				allSamples = append(allSamples, samp)
			}
		}
	}
	if len(allSamples) < 2 {
		return NewErr(http.StatusConflict, "invalid_merge", "merge requires at least two samples")
	}

	requiresCooled := targetJ.Cooled
	estDeliv, hasEstDeliv := ParseTime(targetJ.EstimatedDeliveryAt)

	for i, s1 := range allSamples {
		st1 := s.SampleTypes[s1.SampleTypeID]
		if SampleTypeDisallowsBatching(st1) {
			return NewErr(http.StatusConflict, "pulse_no_batch", "Pulse or non-batchable sample cannot be combined into a consolidation batch")
		}
		if SampleTypeRequiresCooled(st1) {
			requiresCooled = true
		}
		if !LabAcceptsSampleType(s, targetJ.TargetLaboratoryID, s1.SampleTypeID) {
			return NewErr(http.StatusConflict, "invalid_destination", "target laboratory does not accept all sample types in batch")
		}
		if hasEstDeliv {
			if dl, ok := ParseTime(s1.DeliveryDeadline); ok && estDeliv.After(dl) {
				return NewErr(http.StatusConflict, "delivery_deadline_exceeded", "merged journey estimated delivery exceeds sample deadline")
			}
		}
		for j := i + 1; j < len(allSamples); j++ {
			s2 := allSamples[j]
			st2 := s.SampleTypes[s2.SampleTypeID]
			if AreSampleTypesIncompatible(s, st1, st2, s1, s2) {
				return NewErr(http.StatusConflict, "incompatible_batch", "samples have incompatible types or temperature requirements")
			}
		}
	}

	// Check if cooled route is required by any sample in the batch
	if requiresCooled {
		for _, aid := range targetJ.LegAssignmentIDs {
			if a, ok := s.Assignments[aid]; ok && a.ConnectionID != "" {
				if conn, exists := s.Connections[a.ConnectionID]; exists && !conn.Cooled {
					return NewErr(http.StatusConflict, "invalid_route_mode", "cooled sample in batch requires cooled transport connection")
				}
			}
		}
	}

	// Check worker eligibility and capacity on target journey's transport legs
	totalUnits := len(allSamples)
	for _, aid := range targetJ.LegAssignmentIDs {
		if a, ok := s.Assignments[aid]; ok && a.WorkerID != "" {
			if w, exists := s.Users[a.WorkerID]; exists {
				if !w.Active || !w.Available {
					return NewErr(http.StatusConflict, "worker_unavailable", "assigned worker on target journey is unavailable")
				}
				if w.CapacityUnits < totalUnits {
					return NewErr(http.StatusConflict, "capacity_exceeded", "batch size exceeds assigned worker capacity")
				}
			}
		}
	}

	// Check if target locations/connections have capacity once source reservations are consolidated
	sourceSet := make(map[string]bool)
	for _, sj := range sourceJourneys {
		sourceSet[sj.JourneyID] = true
	}
	for _, stop := range targetJ.OrderedStops {
		loc, ok := s.Locations[stop.LocationID]
		if !ok || !loc.Active {
			return NewErr(http.StatusConflict, "invalid_route", "stop location on target journey is inactive")
		}
		// Calculate how many units are already reserved on this location by targetJ + sourceJourneys
		alreadyReserved := 0
		for _, res := range s.Reservations {
			if !res.Released && res.ResourceType == "location" && res.ResourceID == loc.LocationID && res.Cooled == requiresCooled {
				if res.JourneyID == targetJ.JourneyID || sourceSet[res.JourneyID] {
					alreadyReserved += res.Units
				}
			}
		}
		neededExtra := totalUnits - alreadyReserved
		if neededExtra > 0 && !LocationHasCapacity(loc, neededExtra, requiresCooled) {
			if requiresCooled {
				return NewErr(http.StatusConflict, "cooled_capacity_exhausted", "insufficient cooled capacity at location")
			}
			return NewErr(http.StatusConflict, "capacity_exhausted", "insufficient capacity at location")
		}
	}
	for _, aid := range targetJ.LegAssignmentIDs {
		a := s.Assignments[aid]
		if a == nil || a.ConnectionID == "" {
			continue
		}
		conn, ok := s.Connections[a.ConnectionID]
		if !ok || !conn.Active {
			return NewErr(http.StatusConflict, "invalid_route", "connection on target journey is inactive")
		}
		alreadyReserved := 0
		for _, res := range s.Reservations {
			if !res.Released && res.ResourceType == "connection" && res.ResourceID == conn.ConnectionID && res.Cooled == requiresCooled {
				if res.JourneyID == targetJ.JourneyID || sourceSet[res.JourneyID] {
					alreadyReserved += res.Units
				}
			}
		}
		neededExtra := totalUnits - alreadyReserved
		if neededExtra > 0 && !ConnectionHasCapacity(conn, neededExtra, requiresCooled) {
			if requiresCooled {
				return NewErr(http.StatusConflict, "cooled_capacity_exhausted", "insufficient cooled capacity on connection")
			}
			return NewErr(http.StatusConflict, "capacity_exhausted", "insufficient capacity on connection")
		}
	}

	return nil
}

func executeBatchMerge(s *db.State, u *models.User, role string, targetJ *models.Journey, sourceJourneys []*models.Journey) {
	nowStr := models.FormatTime(time.Now())
	var locIDs []string
	for _, st := range targetJ.OrderedStops {
		locIDs = append(locIDs, st.LocationID)
	}
	var connIDs []string
	for _, aid := range targetJ.LegAssignmentIDs {
		if a, ok := s.Assignments[aid]; ok && a.ConnectionID != "" {
			connIDs = append(connIDs, a.ConnectionID)
		}
	}

	for _, sj := range sourceJourneys {
		ReleaseJourneyCapacity(s, sj.JourneyID)
		for _, aid := range sj.AssignmentIDs {
			if a, ok := s.Assignments[aid]; ok {
				if a.Kind == "collection" {
					// Move collection assignment to targetJourney so collector can still collect/hand off
					a.JourneyID = targetJ.JourneyID
					targetJ.AssignmentIDs = append(targetJ.AssignmentIDs, a.AssignmentID)
					targetJ.CollectionAssignmentIDs = append(targetJ.CollectionAssignmentIDs, a.AssignmentID)
				} else if a.Status != "completed" {
					a.Status = "cancelled"
				}
			}
		}
		for _, sid := range sj.SampleIDs {
			has := false
			for _, existing := range targetJ.SampleIDs {
				if existing == sid {
					has = true
					break
				}
			}
			if !has {
				targetJ.SampleIDs = append(targetJ.SampleIDs, sid)
				if samp, ok := s.Samples[sid]; ok {
					st := s.SampleTypes[samp.SampleTypeID]
					cooled := SampleTypeRequiresCooled(st) || targetJ.Cooled
					if cooled {
						targetJ.Cooled = true
					}
					ReserveCapacityForSampleOnRoute(s, targetJ.JourneyID, sid, locIDs, connIDs, cooled)
					samp.ActiveJourneyID = targetJ.JourneyID
					samp.TargetLaboratoryID = targetJ.TargetLaboratoryID
				}
			}
		}
		sj.Status = "replaced"
		sj.ReplacementJourneyID = targetJ.JourneyID
		sj.ReplanStatus = "replaced"
	}

	targetJ.RouteMode = "batched"
	targetJ.CapacityUsed = len(targetJ.SampleIDs)
	targetJ.PlanVersion++

	for _, aid := range targetJ.LegAssignmentIDs {
		if a, ok := s.Assignments[aid]; ok {
			a.SampleIDs = append([]string(nil), targetJ.SampleIDs...)
		}
	}
	for _, aid := range targetJ.NodeAssignmentIDs {
		if a, ok := s.Assignments[aid]; ok {
			a.SampleIDs = append([]string(nil), targetJ.SampleIDs...)
		}
	}
	for _, aid := range targetJ.LaboratoryAssignmentIDs {
		if a, ok := s.Assignments[aid]; ok {
			a.SampleIDs = append([]string(nil), targetJ.SampleIDs...)
		}
	}

	te := RecordAudit(s, u.UserID, role, "merge_journeys", "journey", targetJ.JourneyID, true, nowStr, map[string]interface{}{
		"targetJourneyId": targetJ.JourneyID,
		"planVersion":     targetJ.PlanVersion,
		"sampleIds":       targetJ.SampleIDs,
		"routeMode":       targetJ.RouteMode,
	})
	AppendJourneyHistory(targetJ, te)
	for _, sid := range targetJ.SampleIDs {
		if samp, ok := s.Samples[sid]; ok {
			AppendSampleTimeline(samp, te)
		}
	}
}

func (srv *Server) handleMergeJourneys(w http.ResponseWriter, r *http.Request) {
	var req struct {
		TargetJourneyID     string   `json:"targetJourneyId"`
		ExpectedPlanVersion *int     `json:"expectedPlanVersion"`
		SourceJourneyIDs    []string `json:"sourceJourneyIds"`
		IdempotencyKey      string   `json:"idempotencyKey"`
	}
	rawBody, apiErr := DecodeStrictJSON(r, &req)
	if apiErr != nil {
		WriteError(w, apiErr)
		return
	}

	var cached *models.IdempotencyRecord
	var respData map[string]interface{}
	err := srv.store.Write(r.Context(), func(s *db.State) error {
		u, sess, apiErr := AuthenticateSession(s, r)
		if apiErr != nil {
			return apiErr
		}
		role, apiErr := RequireActiveRole(s, u, sess, "merge_journeys", "journey", req.TargetJourneyID, true, "dispatcher", "administrator")
		if apiErr != nil {
			return apiErr
		}
		if strings.TrimSpace(req.IdempotencyKey) == "" {
			return NewErr(http.StatusBadRequest, "idempotency_required", "idempotencyKey is required")
		}
		if req.TargetJourneyID == "" || req.ExpectedPlanVersion == nil || req.SourceJourneyIDs == nil {
			return NewErr(http.StatusBadRequest, "invalid_json", "targetJourneyId, expectedPlanVersion, and sourceJourneyIds are required")
		}
		if *req.ExpectedPlanVersion < 1 {
			return NewErr(http.StatusBadRequest, "invalid_plan_version", "expectedPlanVersion must be >= 1")
		}
		rec, ierr := CheckIdempotency(s, "merge_journeys", u.UserID, req.IdempotencyKey, rawBody)
		if ierr != nil {
			return ierr
		}
		if rec != nil {
			cached = rec
			return nil
		}

		targetJ, ok := s.Journeys[req.TargetJourneyID]
		if !ok {
			return NewErr(http.StatusNotFound, "not_found", "target journey not found")
		}
		if targetJ.Status != "active" {
			return NewErr(http.StatusConflict, "inactive_plan", "target journey is not active")
		}
		if targetJ.PlanVersion != *req.ExpectedPlanVersion {
			return NewErr(http.StatusConflict, "stale_plan", "expectedPlanVersion does not match target journey planVersion")
		}
		if len(req.SourceJourneyIDs) == 0 {
			return NewErr(http.StatusConflict, "invalid_merge", "sourceJourneyIds cannot be empty")
		}

		var sourceJourneys []*models.Journey
		for _, sjID := range req.SourceJourneyIDs {
			if sjID == req.TargetJourneyID {
				return NewErr(http.StatusConflict, "invalid_merge", "cannot merge journey with itself")
			}
			sj, exists := s.Journeys[sjID]
			if !exists {
				return NewErr(http.StatusNotFound, "not_found", "source journey not found: "+sjID)
			}
			if sj.Status != "active" {
				return NewErr(http.StatusConflict, "inactive_plan", "source journey is not active")
			}
			sourceJourneys = append(sourceJourneys, sj)
		}

		if verr := validateBatchMerge(s, targetJ, sourceJourneys); verr != nil {
			RecordAudit(s, u.UserID, role, "merge_journeys", "journey", targetJ.JourneyID, false, models.FormatTime(time.Now()), map[string]interface{}{
				"targetJourneyId":  req.TargetJourneyID,
				"sourceJourneyIds": req.SourceJourneyIDs,
				"errorCode":        verr.Code,
			})
			return verr
		}

		executeBatchMerge(s, u, role, targetJ, sourceJourneys)
		respData = BuildJourneyPlanResponse(s, targetJ)
		EmitEvent(s, "journey.merged", "journey", targetJ.JourneyID, respData)
		SaveIdempotency(s, "merge_journeys", u.UserID, req.IdempotencyKey, rawBody, http.StatusCreated, respData)
		return nil
	})
	if err != nil {
		WriteError(w, err)
		return
	}
	if cached != nil {
		w.Header().Set("Content-Type", "application/json")
		w.WriteHeader(cached.StatusCode)
		_, _ = w.Write(cached.Response)
		return
	}
	WriteData(w, http.StatusCreated, respData)
}

func executeSplitJourney(s *db.State, u *models.User, role string, j *models.Journey, splitSampleIDs []string) (*models.Journey, *APIError) {
	if len(splitSampleIDs) == 0 || len(splitSampleIDs) >= len(j.SampleIDs) {
		return nil, NewErr(http.StatusConflict, "invalid_split", "sampleIds must be a non-empty strict subset of the journey's samples")
	}
	splitSet := make(map[string]bool)
	for _, sid := range splitSampleIDs {
		found := false
		for _, existing := range j.SampleIDs {
			if existing == sid {
				found = true
				break
			}
		}
		if !found {
			return nil, NewErr(http.StatusConflict, "invalid_split", "sampleId does not belong to this journey: "+sid)
		}
		splitSet[sid] = true
	}

	// Check if any leg is currently in_transit / picked_up
	for _, aid := range j.LegAssignmentIDs {
		if a, ok := s.Assignments[aid]; ok {
			if a.Status == "picked_up" || a.Status == "in_transit" {
				return nil, NewErr(http.StatusConflict, "split_in_progress", "cannot split a batch while a transport leg is actively in transit")
			}
		}
	}

	var remainingSamples []string
	for _, sid := range j.SampleIDs {
		if !splitSet[sid] {
			remainingSamples = append(remainingSamples, sid)
		}
	}

	j.SampleIDs = remainingSamples
	j.CapacityUsed = len(remainingSamples)
	if len(remainingSamples) == 1 {
		if len(j.LegAssignmentIDs) > 1 {
			j.RouteMode = "multi_stop"
		} else {
			j.RouteMode = "direct"
		}
	}
	j.PlanVersion++

	// Update remaining journey assignments
	var remCollIDs []string
	var splitCollIDs []string
	for _, cid := range j.CollectionAssignmentIDs {
		if ca, ok := s.Assignments[cid]; ok {
			if splitSet[ca.SampleID] {
				splitCollIDs = append(splitCollIDs, cid)
			} else {
				remCollIDs = append(remCollIDs, cid)
			}
		}
	}
	j.CollectionAssignmentIDs = remCollIDs
	for _, aid := range j.LegAssignmentIDs {
		if a, ok := s.Assignments[aid]; ok {
			a.SampleIDs = append([]string(nil), remainingSamples...)
			a.SampleID = remainingSamples[0]
		}
	}
	for _, aid := range j.NodeAssignmentIDs {
		if a, ok := s.Assignments[aid]; ok {
			a.SampleIDs = append([]string(nil), remainingSamples...)
			a.SampleID = remainingSamples[0]
		}
	}
	for _, aid := range j.LaboratoryAssignmentIDs {
		if a, ok := s.Assignments[aid]; ok {
			a.SampleIDs = append([]string(nil), remainingSamples...)
			a.SampleID = remainingSamples[0]
		}
	}

	// Create the split journey
	splitJID := uuid.NewString()
	splitRouteMode := "direct"
	if len(splitSampleIDs) > 1 {
		splitRouteMode = "batched"
	} else if len(j.LegAssignmentIDs) > 1 {
		splitRouteMode = "multi_stop"
	}

	splitStops := make([]models.JourneyStop, len(j.OrderedStops))
	for i, st := range j.OrderedStops {
		stCopy := st
		stCopy.StopID = uuid.NewString()
		splitStops[i] = stCopy
	}

	splitJ := &models.Journey{
		JourneyID:               splitJID,
		ParentJourneyID:         j.JourneyID,
		PlanVersion:             1,
		RouteMode:               splitRouteMode,
		Status:                  "active",
		EstimatedDeliveryAt:     j.EstimatedDeliveryAt,
		TotalCostUnits:          j.TotalCostUnits,
		CapacityUsed:            len(splitSampleIDs),
		CapacityAvailable:       j.CapacityAvailable,
		SampleIDs:               append([]string(nil), splitSampleIDs...),
		OrderedStops:            splitStops,
		AssignmentIDs:           []string{},
		LegAssignmentIDs:        []string{},
		CollectionAssignmentIDs: splitCollIDs,
		NodeAssignmentIDs:       []string{},
		LaboratoryAssignmentIDs: []string{},
		TargetLaboratoryID:      j.TargetLaboratoryID,
		Cooled:                  j.Cooled,
		History:                 []models.TimelineEntry{},
	}
	s.Journeys[splitJID] = splitJ
	j.SplitJourneyID = splitJID

	for _, cid := range splitCollIDs {
		if ca, ok := s.Assignments[cid]; ok {
			ca.JourneyID = splitJID
			splitJ.AssignmentIDs = append(splitJ.AssignmentIDs, cid)
		}
	}

	now := time.Now().UTC()
	primarySampleID := splitSampleIDs[0]

	// Clone transport, node, and lab assignments for splitJ
	for _, aid := range j.AssignmentIDs {
		orig, ok := s.Assignments[aid]
		if !ok || orig.Kind == "collection" {
			continue
		}
		if orig.Status == "completed" {
			// Completed work is preserved
			splitJ.AssignmentIDs = append(splitJ.AssignmentIDs, orig.AssignmentID)
			if orig.Kind == "transport" {
				splitJ.LegAssignmentIDs = append(splitJ.LegAssignmentIDs, orig.AssignmentID)
			} else if orig.Kind == "node" {
				splitJ.NodeAssignmentIDs = append(splitJ.NodeAssignmentIDs, orig.AssignmentID)
			} else if orig.Kind == "laboratory" {
				splitJ.LaboratoryAssignmentIDs = append(splitJ.LaboratoryAssignmentIDs, orig.AssignmentID)
			}
			continue
		}
		newA := &models.Assignment{
			AssignmentID:           uuid.NewString(),
			Kind:                   orig.Kind,
			JourneyID:              splitJID,
			SampleID:               primarySampleID,
			SampleIDs:              append([]string(nil), splitSampleIDs...),
			Sequence:               orig.Sequence,
			LegSequence:            orig.LegSequence,
			Status:                 "pending",
			FromLocationID:         orig.FromLocationID,
			ToLocationID:           orig.ToLocationID,
			ConnectionID:           orig.ConnectionID,
			NodeID:                 orig.NodeID,
			IncomingFromLocationID: orig.IncomingFromLocationID,
			OutgoingToLocationID:   orig.OutgoingToLocationID,
			LaboratoryID:           orig.LaboratoryID,
			ExpectedSampleTypeID:   orig.ExpectedSampleTypeID,
			DeclinedByWorkerIDs:    []string{},
			History:                []models.TimelineEntry{},
		}
		s.Assignments[newA.AssignmentID] = newA
		splitJ.AssignmentIDs = append(splitJ.AssignmentIDs, newA.AssignmentID)
		switch newA.Kind {
		case "transport":
			splitJ.LegAssignmentIDs = append(splitJ.LegAssignmentIDs, newA.AssignmentID)
		case "node":
			splitJ.NodeAssignmentIDs = append(splitJ.NodeAssignmentIDs, newA.AssignmentID)
		case "laboratory":
			splitJ.LaboratoryAssignmentIDs = append(splitJ.LaboratoryAssignmentIDs, newA.AssignmentID)
		}
		OfferAssignmentToBestWorker(s, newA, now, "")
	}

	// Transfer capacity reservations for splitSampleIDs to splitJID
	for _, res := range s.Reservations {
		if res.JourneyID == j.JourneyID && splitSet[res.SampleID] {
			res.JourneyID = splitJID
		}
	}

	nowStr := models.FormatTime(now)
	te := RecordAudit(s, u.UserID, role, "split_journey", "journey", j.JourneyID, true, nowStr, map[string]interface{}{
		"journeyId":        j.JourneyID,
		"splitJourneyId":   splitJ.JourneyID,
		"remainingSamples": j.SampleIDs,
		"splitSamples":     splitJ.SampleIDs,
	})
	AppendJourneyHistory(j, te)
	AppendJourneyHistory(splitJ, te)

	for _, sid := range splitSampleIDs {
		if samp, ok := s.Samples[sid]; ok {
			samp.ActiveJourneyID = splitJID
			AppendSampleTimeline(samp, te)
		}
	}
	for _, sid := range j.SampleIDs {
		if samp, ok := s.Samples[sid]; ok {
			AppendSampleTimeline(samp, te)
		}
	}

	return splitJ, nil
}

func (srv *Server) handleSplitJourney(w http.ResponseWriter, r *http.Request) {
	var req struct {
		JourneyID           string   `json:"journeyId"`
		ExpectedPlanVersion *int     `json:"expectedPlanVersion"`
		SampleIDs           []string `json:"sampleIds"`
		IdempotencyKey      string   `json:"idempotencyKey"`
	}
	rawBody, apiErr := DecodeStrictJSON(r, &req)
	if apiErr != nil {
		WriteError(w, apiErr)
		return
	}

	var cached *models.IdempotencyRecord
	var respData map[string]interface{}
	err := srv.store.Write(r.Context(), func(s *db.State) error {
		u, sess, apiErr := AuthenticateSession(s, r)
		if apiErr != nil {
			return apiErr
		}
		role, apiErr := RequireActiveRole(s, u, sess, "split_journey", "journey", req.JourneyID, true, "dispatcher", "administrator")
		if apiErr != nil {
			return apiErr
		}
		if strings.TrimSpace(req.IdempotencyKey) == "" {
			return NewErr(http.StatusBadRequest, "idempotency_required", "idempotencyKey is required")
		}
		if req.JourneyID == "" || req.ExpectedPlanVersion == nil || req.SampleIDs == nil {
			return NewErr(http.StatusBadRequest, "invalid_json", "journeyId, expectedPlanVersion, and sampleIds are required")
		}
		if *req.ExpectedPlanVersion < 1 {
			return NewErr(http.StatusBadRequest, "invalid_plan_version", "expectedPlanVersion must be >= 1")
		}
		rec, ierr := CheckIdempotency(s, "split_journey", u.UserID, req.IdempotencyKey, rawBody)
		if ierr != nil {
			return ierr
		}
		if rec != nil {
			cached = rec
			return nil
		}

		j, ok := s.Journeys[req.JourneyID]
		if !ok {
			return NewErr(http.StatusNotFound, "not_found", "journey not found")
		}
		if j.Status != "active" {
			return NewErr(http.StatusConflict, "inactive_plan", "journey is not active")
		}
		if j.PlanVersion != *req.ExpectedPlanVersion {
			return NewErr(http.StatusConflict, "stale_plan", "expectedPlanVersion does not match current journey planVersion")
		}

		splitJ, serr := executeSplitJourney(s, u, role, j, req.SampleIDs)
		if serr != nil {
			return serr
		}

		respData = map[string]interface{}{
			"journey":      BuildJourneyPlanResponse(s, j),
			"splitJourney": BuildJourneyPlanResponse(s, splitJ),
		}
		EmitEvent(s, "journey.split", "journey", j.JourneyID, respData)
		SaveIdempotency(s, "split_journey", u.UserID, req.IdempotencyKey, rawBody, http.StatusCreated, respData)
		return nil
	})
	if err != nil {
		WriteError(w, err)
		return
	}
	if cached != nil {
		w.Header().Set("Content-Type", "application/json")
		w.WriteHeader(cached.StatusCode)
		_, _ = w.Write(cached.Response)
		return
	}
	WriteData(w, http.StatusCreated, respData)
}
