func isJourneyAffectedByDisruption(s *db.State, j *models.Journey, resourceType, resourceID string) bool {
	if j == nil || j.Status != "active" {
		return false
	}
	switch resourceType {
	case "location", "node", "laboratory", "capacity":
		// Check unfinished stops and unfinished assignments
		for _, st := range j.OrderedStops {
			if st.LocationID == resourceID && st.CompletedAt == "" {
				return true
			}
		}
		for _, aid := range j.AssignmentIDs {
			a := s.Assignments[aid]
			if a == nil || a.Status == "completed" || a.Status == "cancelled" {
				continue
			}
			if a.FromLocationID == resourceID || a.ToLocationID == resourceID || a.NodeID == resourceID || a.LaboratoryID == resourceID || a.ConnectionID == resourceID {
				return true
			}
		}
	case "connection", "route":
		for _, aid := range j.LegAssignmentIDs {
			a := s.Assignments[aid]
			if a == nil || a.Status == "completed" || a.Status == "cancelled" {
				continue
			}
			if a.ConnectionID == resourceID {
				return true
			}
		}
	case "worker":
		for _, aid := range j.AssignmentIDs {
			a := s.Assignments[aid]
			if a == nil || a.Status == "completed" || a.Status == "cancelled" {
				continue
			}
			if a.WorkerID == resourceID || a.OfferedToWorkerID == resourceID {
				return true
			}
		}
	}
	return false
}

func replanSingleJourney(s *db.State, actorID, role string, j *models.Journey, refTime time.Time, reason string, preferAlternate bool) (string, *models.Journey) {
	if j == nil || j.Status != "active" || len(j.SampleIDs) == 0 {
		return "not_required", nil
	}
	primarySample := s.Samples[j.SampleIDs[0]]
	if primarySample == nil || primarySample.Status == "received" || primarySample.Status == "cancelled" {
		return "not_required", nil
	}

	// Determine completed prefix of transport legs and current location of sample
	var completedLegs []*models.Assignment
	var completedStops []models.JourneyStop
	currentLocID := ""
	if len(j.OrderedStops) > 0 {
		currentLocID = j.OrderedStops[0].LocationID
	}

	for _, lid := range j.LegAssignmentIDs {
		leg := s.Assignments[lid]
		if leg != nil && (leg.Status == "completed" || leg.Status == "delivered") {
			completedLegs = append(completedLegs, leg)
			currentLocID = leg.ToLocationID
		} else {
			break
		}
	}

	for _, st := range j.OrderedStops {
		if st.CompletedAt != "" || (len(completedLegs) > 0 && st.LocationID == currentLocID && st.StopType != "delivery") {
			stCopy := st
			if stCopy.CompletedAt == "" {
				stCopy.CompletedAt = models.FormatTime(refTime)
			}
			completedStops = append(completedStops, stCopy)
			if st.LocationID == currentLocID {
				break
			}
		}
	}

	// Determine earliest deadline and cooling requirement across all samples in journey
	requiresCooled := j.Cooled
	var earliestDeadline time.Time
	for _, sid := range j.SampleIDs {
		samp := s.Samples[sid]
		if samp == nil {
			continue
		}
		st := s.SampleTypes[samp.SampleTypeID]
		if SampleTypeRequiresCooled(st) {
			requiresCooled = true
		}
		if dl, ok := ParseTime(samp.DeliveryDeadline); ok {
			if earliestDeadline.IsZero() || dl.Before(earliestDeadline) {
				earliestDeadline = dl
			}
		}
	}

	// Determine replan start time
	replanStart := refTime
	if primarySample.LastEventAt != "" {
		if lt, ok := ParseTime(primarySample.LastEventAt); ok && lt.After(replanStart) {
			replanStart = lt
		}
	}
	if !primarySample.Sealed {
		if ec, ok := ParseTime(primarySample.EarliestCollectionAt); ok && ec.After(replanStart) {
			replanStart = ec
		}
	}

	// Release old journey's unfinished reservations before computing available capacity for replacement
	ReleaseJourneyCapacity(s, j.JourneyID)

	// Find active laboratories that accept all sample types in j.SampleIDs
	acceptingLabs := make(map[string]bool)
	for _, loc := range s.Locations {
		if !loc.Active || !loc.Functions.Laboratory {
			continue
		}
		acceptsAll := true
		for _, sid := range j.SampleIDs {
			if samp, ok := s.Samples[sid]; ok {
				if !LabAcceptsSampleType(s, loc.LocationID, samp.SampleTypeID) {
					acceptsAll = false
					break
				}
			}
		}
		if acceptsAll {
			acceptingLabs[loc.LocationID] = true
		}
	}

	units := len(j.SampleIDs)
	allRoutes := FindRoutes(s, []string{currentLocID}, acceptingLabs, requiresCooled, units, replanStart)

	var validRoutes []RoutePath
	for _, r := range allRoutes {
		if requiresCooled && !r.AllCooled {
			continue
		}
		if !r.HasCapacity {
			continue
		}
		if !earliestDeadline.IsZero() && r.ArrivalAt.After(earliestDeadline) {
			continue
		}
		validRoutes = append(validRoutes, r)
	}

	if len(validRoutes) == 0 {
		// Mark journey and samples as expired if no valid route can meet the deadline
		nowStr := models.FormatTime(refTime)
		j.Status = "expired"
		j.ReplanStatus = "expired"
		j.PlanVersion++
		for _, aid := range j.AssignmentIDs {
			if a, ok := s.Assignments[aid]; ok && a.Status != "completed" {
				a.Status = "cancelled"
			}
		}
		te := RecordAudit(s, actorID, role, "replan_expired", "journey", j.JourneyID, true, nowStr, map[string]interface{}{
			"journeyId":    j.JourneyID,
			"reason":       reason,
			"replanStatus": "expired",
		})
		AppendJourneyHistory(j, te)
		for _, sid := range j.SampleIDs {
			if samp, ok := s.Samples[sid]; ok {
				samp.Status = "expired"
				samp.ActiveReplacementPlanIDs = []string{}
				AppendSampleTimeline(samp, te)
			}
		}
		return "expired", nil
	}

	chosenRoute := validRoutes[0]
	if preferAlternate && len(validRoutes) > 1 {
		// Build current remaining connection list to see if validRoutes[0] is identical
		var oldConns []string
		for _, lid := range j.LegAssignmentIDs {
			if leg, ok := s.Assignments[lid]; ok && leg.Status != "completed" && leg.Status != "delivered" {
				oldConns = append(oldConns, leg.ConnectionID)
			}
		}
		if strings.Join(chosenRoute.ConnectionIDs, ",") == strings.Join(oldConns, ",") {
			chosenRoute = validRoutes[1]
		}
	}

	// Build replacement journey preserving completed stops and assignments
	newJID := uuid.NewString()
	targetLabID := chosenRoute.LocationIDs[len(chosenRoute.LocationIDs)-1]

	var newStops []models.JourneyStop
	seqStop := 1
	for _, cst := range completedStops {
		cstCopy := cst
		cstCopy.Sequence = seqStop
		seqStop++
		newStops = append(newStops, cstCopy)
	}

	elapsedMin := 0
	for i, locID := range chosenRoute.LocationIDs {
		if i == 0 && len(newStops) > 0 && newStops[len(newStops)-1].LocationID == locID {
			continue
		}
		loc := s.Locations[locID]
		if i > 0 {
			if conn := s.Connections[chosenRoute.ConnectionIDs[i-1]]; conn != nil {
				elapsedMin += conn.TravelMinutes
			}
		}
		dwell := 0
		var coord *models.Coordinate
		if loc != nil {
			dwell = loc.HandlingMinutes
			c := loc.Coordinate
			coord = &c
		}
		elapsedMin += dwell
		estStr := models.FormatTime(replanStart.Add(time.Duration(elapsedMin) * time.Minute))
		stopType := "handoff"
		if len(newStops) == 0 && i == 0 {
			stopType = "pickup"
		} else if i == len(chosenRoute.LocationIDs)-1 {
			stopType = "delivery"
		}
		dwellCopy := dwell
		newStops = append(newStops, models.JourneyStop{
			StopID:       uuid.NewString(),
			LocationID:   locID,
			Location_ID:  locID,
			StopType:     stopType,
			Stop_Type:    stopType,
			Sequence:     seqStop,
			EstimatedAt:  estStr,
			Estimated_At: estStr,
			DwellMinutes: &dwellCopy,
			Coordinate:   coord,
		})
		seqStop++
	}

	totalLegsCount := len(completedLegs) + len(chosenRoute.ConnectionIDs)
	routeMode := "direct"
	if len(j.SampleIDs) > 1 {
		routeMode = "batched"
	} else if totalLegsCount > 1 {
		routeMode = "multi_stop"
	}

	newJ := &models.Journey{
		JourneyID:               newJID,
		ParentJourneyID:         j.JourneyID,
		PlanVersion:             j.PlanVersion + 1,
		RouteMode:               routeMode,
		Status:                  "active",
		EstimatedDeliveryAt:     models.FormatTime(chosenRoute.ArrivalAt),
		TotalCostUnits:          chosenRoute.TotalCost,
		CapacityUsed:            len(j.SampleIDs),
		CapacityAvailable:       100,
		SampleIDs:               append([]string(nil), j.SampleIDs...),
		OrderedStops:            newStops,
		AssignmentIDs:           []string{},
		LegAssignmentIDs:        []string{},
		CollectionAssignmentIDs: []string{},
		NodeAssignmentIDs:       []string{},
		LaboratoryAssignmentIDs: []string{},
		TargetLaboratoryID:      targetLabID,
		Cooled:                  requiresCooled,
		ReplanStatus:            "replaced",
		History:                 append([]models.TimelineEntry(nil), j.History...),
	}
	s.Journeys[newJID] = newJ

	for _, sid := range newJ.SampleIDs {
		ReserveCapacityForSampleOnRoute(s, newJID, sid, chosenRoute.LocationIDs, chosenRoute.ConnectionIDs, requiresCooled)
	}
	if lab, ok := s.Locations[targetLabID]; ok {
		c := GetLocationCapacity(lab)
		if requiresCooled {
			newJ.CapacityAvailable = c.CooledAvailableUnits
		} else {
			newJ.CapacityAvailable = c.AvailableUnits
		}
	}

	seqAssign := 1
	missingRequiredWorker := false

	// 1. Preserve completed or active-holder collection assignments, or create new one if not sealed
	for _, cid := range j.CollectionAssignmentIDs {
		ca := s.Assignments[cid]
		if ca == nil {
			continue
		}
		if ca.Status == "completed" || (primarySample.CurrentHolderID != "" && ca.WorkerID == primarySample.CurrentHolderID) {
			ca.JourneyID = newJID
			ca.Sequence = seqAssign
			seqAssign++
			newJ.AssignmentIDs = append(newJ.AssignmentIDs, ca.AssignmentID)
			newJ.CollectionAssignmentIDs = append(newJ.CollectionAssignmentIDs, ca.AssignmentID)
		} else if !primarySample.Sealed {
			// Check if the previously assigned collector is still eligible and available
			w := s.Users[ca.WorkerID]
			if w != nil && ca.Status == "accepted" {
				if okElig, _ := IsWorkerEligibleForAssignment(s, w, ca, replanStart, true); okElig {
					ca.JourneyID = newJID
					ca.Sequence = seqAssign
					seqAssign++
					newJ.AssignmentIDs = append(newJ.AssignmentIDs, ca.AssignmentID)
					newJ.CollectionAssignmentIDs = append(newJ.CollectionAssignmentIDs, ca.AssignmentID)
					continue
				}
			}
			ca.Status = "cancelled"
			newColl := &models.Assignment{
				AssignmentID:         uuid.NewString(),
				Kind:                 "collection",
				JourneyID:            newJID,
				SampleID:             primarySample.SampleID,
				SampleIDs:            append([]string(nil), newJ.SampleIDs...),
				Sequence:             seqAssign,
				Status:               "pending",
				FromLocationID:       currentLocID,
				ToLocationID:         currentLocID,
				ExpectedSampleTypeID: primarySample.SampleTypeID,
				DeclinedByWorkerIDs:  []string{},
				History:              []models.TimelineEntry{},
			}
			seqAssign++
			s.Assignments[newColl.AssignmentID] = newColl
			newJ.AssignmentIDs = append(newJ.AssignmentIDs, newColl.AssignmentID)
			newJ.CollectionAssignmentIDs = append(newJ.CollectionAssignmentIDs, newColl.AssignmentID)
			if OfferAssignmentToBestWorker(s, newColl, replanStart, "") == nil {
				missingRequiredWorker = true
				FlagNoQualifiedWorkerException(s, primarySample, newColl, models.FormatTime(replanStart))
			}
		} else {
			ca.Status = "cancelled"
		}
	}

	// 2. Preserve completed transport legs (and any node assignment currently holding custody at currentLocID)
	legSeq := 1
	for _, cleg := range completedLegs {
		cleg.JourneyID = newJID
		cleg.Sequence = seqAssign
		cleg.LegSequence = legSeq
		seqAssign++
		legSeq++
		newJ.AssignmentIDs = append(newJ.AssignmentIDs, cleg.AssignmentID)
		newJ.LegAssignmentIDs = append(newJ.LegAssignmentIDs, cleg.AssignmentID)
	}

	for _, nid := range j.NodeAssignmentIDs {
		na := s.Assignments[nid]
		if na == nil {
			continue
		}
		if na.Status == "completed" || (primarySample.CurrentHolderID != "" && na.WorkerID == primarySample.CurrentHolderID) {
			na.JourneyID = newJID
			na.Sequence = seqAssign
			if len(chosenRoute.LocationIDs) > 1 {
				na.OutgoingToLocationID = chosenRoute.LocationIDs[1]
			}
			seqAssign++
			newJ.AssignmentIDs = append(newJ.AssignmentIDs, na.AssignmentID)
			newJ.NodeAssignmentIDs = append(newJ.NodeAssignmentIDs, na.AssignmentID)
		} else {
			na.Status = "cancelled"
		}
	}

	// Cancel remaining unfinished transport and lab assignments on old journey
	for _, lid := range j.LegAssignmentIDs {
		if leg, ok := s.Assignments[lid]; ok && leg.JourneyID == j.JourneyID && leg.Status != "completed" {
			leg.Status = "cancelled"
		}
	}
	for _, lid := range j.LaboratoryAssignmentIDs {
		if la, ok := s.Assignments[lid]; ok && la.Status != "completed" {
			la.Status = "cancelled"
		}
	}

	// 3. Create new transport legs and intermediate node assignments for chosenRoute
	for i := 0; i < len(chosenRoute.ConnectionIDs); i++ {
		fromLoc := chosenRoute.LocationIDs[i]
		toLoc := chosenRoute.LocationIDs[i+1]
		connID := chosenRoute.ConnectionIDs[i]

		legAssign := &models.Assignment{
			AssignmentID:        uuid.NewString(),
			Kind:                "transport",
			JourneyID:           newJID,
			SampleID:            primarySample.SampleID,
			SampleIDs:           append([]string(nil), newJ.SampleIDs...),
			Sequence:            seqAssign,
			LegSequence:         legSeq,
			Status:              "pending",
			FromLocationID:      fromLoc,
			ToLocationID:        toLoc,
			ConnectionID:        connID,
			DeclinedByWorkerIDs: []string{},
			History:             []models.TimelineEntry{},
		}
		seqAssign++
		legSeq++
		s.Assignments[legAssign.AssignmentID] = legAssign
		newJ.AssignmentIDs = append(newJ.AssignmentIDs, legAssign.AssignmentID)
		newJ.LegAssignmentIDs = append(newJ.LegAssignmentIDs, legAssign.AssignmentID)
		if OfferAssignmentToBestWorker(s, legAssign, replanStart, "") == nil {
			missingRequiredWorker = true
			FlagNoQualifiedWorkerException(s, primarySample, legAssign, models.FormatTime(replanStart))
		}

		if i+1 < len(chosenRoute.LocationIDs)-1 {
			nextOutLoc := chosenRoute.LocationIDs[i+2]
			nodeAssign := &models.Assignment{
				AssignmentID:           uuid.NewString(),
				Kind:                   "node",
				JourneyID:              newJID,
				SampleID:               primarySample.SampleID,
				SampleIDs:              append([]string(nil), newJ.SampleIDs...),
				Sequence:               seqAssign,
				Status:                 "pending",
				NodeID:                 toLoc,
				FromLocationID:         toLoc,
				ToLocationID:           toLoc,
				IncomingFromLocationID: fromLoc,
				OutgoingToLocationID:   nextOutLoc,
				DeclinedByWorkerIDs:    []string{},
				History:                []models.TimelineEntry{},
			}
			seqAssign++
			s.Assignments[nodeAssign.AssignmentID] = nodeAssign
			newJ.AssignmentIDs = append(newJ.AssignmentIDs, nodeAssign.AssignmentID)
			newJ.NodeAssignmentIDs = append(newJ.NodeAssignmentIDs, nodeAssign.AssignmentID)
			OfferAssignmentToBestWorker(s, nodeAssign, replanStart, "")
		}
	}

	// 4. Create new laboratory assignment at targetLabID
	labAssign := &models.Assignment{
		AssignmentID:         uuid.NewString(),
		Kind:                 "laboratory",
		JourneyID:            newJID,
		SampleID:             primarySample.SampleID,
		SampleIDs:            append([]string(nil), newJ.SampleIDs...),
		Sequence:             seqAssign,
		Status:               "pending",
		LaboratoryID:         targetLabID,
		FromLocationID:       targetLabID,
		ToLocationID:         targetLabID,
		ExpectedSampleTypeID: primarySample.SampleTypeID,
		DeclinedByWorkerIDs:  []string{},
		History:              []models.TimelineEntry{},
	}
	s.Assignments[labAssign.AssignmentID] = labAssign
	newJ.AssignmentIDs = append(newJ.AssignmentIDs, labAssign.AssignmentID)
	newJ.LaboratoryAssignmentIDs = append(newJ.LaboratoryAssignmentIDs, labAssign.AssignmentID)
	OfferAssignmentToBestWorker(s, labAssign, replanStart, "")

	j.Status = "replaced"
	j.ReplacementJourneyID = newJID
	j.ReplanStatus = "replaced"

	statusResult := "replaced"
	if missingRequiredWorker {
		statusResult = "exception"
		newJ.ReplanStatus = "exception"
	}

	nowStr := models.FormatTime(refTime)
	te := RecordAudit(s, actorID, role, "replan_journey", "journey", newJID, true, nowStr, map[string]interface{}{
		"previousJourneyId":  j.JourneyID,
		"replacementPlanId":  newJID,
		"planVersion":        newJ.PlanVersion,
		"replanStatus":       statusResult,
		"targetLaboratoryId": targetLabID,
		"reason":             reason,
	})
	AppendJourneyHistory(j, te)
	AppendJourneyHistory(newJ, te)

	for _, sid := range newJ.SampleIDs {
		if samp, ok := s.Samples[sid]; ok {
			samp.ActiveJourneyID = newJID
			samp.TargetLaboratoryID = targetLabID
			// Allow only ONE active replacement plan at a time
			samp.ActiveReplacementPlanIDs = []string{newJID}
			AppendSampleTimeline(samp, te)
		}
	}

	return statusResult, newJ
}

func (srv *Server) handleRerouteJourney(w http.ResponseWriter, r *http.Request) {
	var req struct {
		JourneyID           string `json:"journeyId"`
		ExpectedPlanVersion *int   `json:"expectedPlanVersion"`
		Reason              string `json:"reason"`
		IdempotencyKey      string `json:"idempotencyKey"`
	}
	rawBody, apiErr := DecodeStrictJSON(r, &req)
	if apiErr != nil {
		WriteError(w, apiErr)
		return
	}

	var cached *models.IdempotencyRecord
	var respData map[string]interface{}
	err := srv.store.Write(r.Context(), func(s *db.State) error {
		u, sess, apiErr := AuthenticateSession(s, r)
		if apiErr != nil {
			return apiErr
		}
		role, apiErr := RequireActiveRole(s, u, sess, "reroute_journey", "journey", req.JourneyID, true, "dispatcher", "administrator")
		if apiErr != nil {
			return apiErr
		}
		if strings.TrimSpace(req.IdempotencyKey) == "" {
			return NewErr(http.StatusBadRequest, "idempotency_required", "idempotencyKey is required")
		}
		if req.JourneyID == "" || req.ExpectedPlanVersion == nil {
			return NewErr(http.StatusBadRequest, "invalid_json", "journeyId and expectedPlanVersion are required")
		}
		if *req.ExpectedPlanVersion < 1 {
			return NewErr(http.StatusBadRequest, "invalid_plan_version", "expectedPlanVersion must be >= 1")
		}
		rec, ierr := CheckIdempotency(s, "reroute_journey", u.UserID, req.IdempotencyKey, rawBody)
		if ierr != nil {
			return ierr
		}
		if rec != nil {
			cached = rec
			return nil
		}

		j, ok := s.Journeys[req.JourneyID]
		if !ok {
			return NewErr(http.StatusNotFound, "not_found", "journey not found")
		}
		if j.Status != "active" {
			return NewErr(http.StatusConflict, "inactive_plan", "journey is not active")
		}
		if j.PlanVersion != *req.ExpectedPlanVersion {
			return NewErr(http.StatusConflict, "stale_plan", "expectedPlanVersion does not match current journey planVersion")
		}

		now := time.Now().UTC()
		statusResult, newJ := replanSingleJourney(s, u.UserID, role, j, now, req.Reason, true)

		respData = map[string]interface{}{
			"journeyId":    j.JourneyID,
			"replanStatus": statusResult,
		}
		if newJ != nil {
			respData["replacementPlanId"] = newJ.JourneyID
			respData["replacementJourney"] = BuildJourneyPlanResponse(s, newJ)
		}
		EmitEvent(s, "journey.rerouted", "journey", j.JourneyID, respData)
		SaveIdempotency(s, "reroute_journey", u.UserID, req.IdempotencyKey, rawBody, http.StatusCreated, respData)
		return nil
	})
	if err != nil {
		WriteError(w, err)
		return
	}
	if cached != nil {
		w.Header().Set("Content-Type", "application/json")
		w.WriteHeader(cached.StatusCode)
		_, _ = w.Write(cached.Response)
		return
	}
	WriteData(w, http.StatusCreated, respData)
}

var validDisruptionResourceTypes = map[string]bool{
	"location":   true,
	"node":       true,
	"laboratory": true,
	"connection": true,
	"route":      true,
	"worker":     true,
	"capacity":   true,
}

func (srv *Server) handleReportDisruption(w http.ResponseWriter, r *http.Request) {
	var req struct {
		ResourceType   string `json:"resourceType"`
		ResourceID     string `json:"resourceId"`
		Reason         string `json:"reason"`
		OccurredAt     string `json:"occurredAt"`
		IdempotencyKey string `json:"idempotencyKey"`
	}
	rawBody, apiErr := DecodeStrictJSON(r, &req)
	if apiErr != nil {
		WriteError(w, apiErr)
		return
	}

	var cached *models.IdempotencyRecord
	var respData map[string]interface{}
	err := srv.store.Write(r.Context(), func(s *db.State) error {
		u, sess, apiErr := AuthenticateSession(s, r)
		if apiErr != nil {
			return apiErr
		}
		role, apiErr := RequireActiveRole(s, u, sess, "report_disruption", req.ResourceType, req.ResourceID, true, "dispatcher", "administrator")
		if apiErr != nil {
			return apiErr
		}
		if strings.TrimSpace(req.IdempotencyKey) == "" {
			return NewErr(http.StatusBadRequest, "idempotency_required", "idempotencyKey is required")
		}
		if req.ResourceID == "" || req.OccurredAt == "" {
			return NewErr(http.StatusBadRequest, "invalid_json", "resourceType, resourceId, and occurredAt are required")
		}
		if !validDisruptionResourceTypes[req.ResourceType] {
			return NewErr(http.StatusBadRequest, "invalid_resource_type", "invalid resourceType")
		}
		occTime, ok := ParseTime(req.OccurredAt)
		if !ok {
			return NewErr(http.StatusBadRequest, "invalid_time", "invalid occurredAt timestamp")
		}
		rec, ierr := CheckIdempotency(s, "report_disruption", u.UserID, req.IdempotencyKey, rawBody)
		if ierr != nil {
			return ierr
		}
		if rec != nil {
			cached = rec
			return nil
		}

		// Mark the disrupted resource unavailable
		switch req.ResourceType {
		case "location", "node":
			loc, exists := s.Locations[req.ResourceID]
			if !exists {
				return NewErr(http.StatusNotFound, "not_found", "location not found")
			}
			loc.Active = false
			RecomputeServiceabilitySnapshot(s)
		case "laboratory":
			loc, exists := s.Locations[req.ResourceID]
			if !exists {
				return NewErr(http.StatusNotFound, "not_found", "laboratory not found")
			}
			loc.Functions.Laboratory = false
			if !loc.Functions.CollectionPoint && !loc.Functions.TransferPoint && !loc.Functions.Hub {
				loc.Active = false
			}
			RecomputeServiceabilitySnapshot(s)
		case "connection", "route":
			conn, exists := s.Connections[req.ResourceID]
			if !exists {
				return NewErr(http.StatusNotFound, "not_found", "connection not found")
			}
			conn.Active = false
			RecomputeServiceabilitySnapshot(s)
		case "worker":
			wUser, exists := s.Users[req.ResourceID]
			if !exists {
				return NewErr(http.StatusNotFound, "not_found", "worker not found")
			}
			wUser.Available = false
		case "capacity":
			if loc, exists := s.Locations[req.ResourceID]; exists {
				loc.CapacityConfigured = true
				loc.CapacityUnits = 0
				loc.CooledCapacityUnits = 0
				RecomputeServiceabilitySnapshot(s)
			} else if conn, exists := s.Connections[req.ResourceID]; exists {
				conn.CapacityConfigured = true
				conn.CapacityUnits = 0
				conn.CooledCapacityUnits = 0
				RecomputeServiceabilitySnapshot(s)
			} else {
				return NewErr(http.StatusNotFound, "not_found", "capacity resource not found")
			}
		}

		// Find all active journeys affected by this disruption
		var affectedJourneys []*models.Journey
		for _, j := range s.Journeys {
			if isJourneyAffectedByDisruption(s, j, req.ResourceType, req.ResourceID) {
				affectedJourneys = append(affectedJourneys, j)
			}
		}

		affectedSamples := []string{}
		replacementPlans := []string{}
		overallStatus := "not_required"

		for _, j := range affectedJourneys {
			for _, sid := range j.SampleIDs {
				affectedSamples = append(affectedSamples, sid)
			}
			stRes, newJ := replanSingleJourney(s, u.UserID, role, j, occTime, req.Reason, false)
			if newJ != nil {
				replacementPlans = append(replacementPlans, newJ.JourneyID)
			}
			if stRes == "expired" {
				overallStatus = "expired"
			} else if stRes == "exception" && overallStatus != "expired" {
				overallStatus = "exception"
			} else if stRes == "replaced" && overallStatus == "not_required" {
				overallStatus = "replaced"
			}
		}

		disruptionID := uuid.NewString()
		occStr := models.FormatTime(occTime)
		s.Disruptions[disruptionID] = &models.DisruptionRecord{
			DisruptionID:       disruptionID,
			ResourceType:       req.ResourceType,
			ResourceID:         req.ResourceID,
			Reason:             req.Reason,
			OccurredAt:         occStr,
			AffectedSampleIDs:  affectedSamples,
			ReplacementPlanIDs: replacementPlans,
			ReplanStatus:       overallStatus,
		}

		RecordAudit(s, u.UserID, role, "report_disruption", req.ResourceType, req.ResourceID, true, occStr, map[string]interface{}{
			"disruptionId":       disruptionID,
			"resourceType":       req.ResourceType,
			"resourceId":         req.ResourceID,
			"affectedSampleIds":  affectedSamples,
			"replacementPlanIds": replacementPlans,
			"replanStatus":       overallStatus,
			"reason":             req.Reason,
		})

		respData = map[string]interface{}{
			"disruptionId":       disruptionID,
			"affectedSampleIds":  affectedSamples,
			"replacementPlanIds": replacementPlans,
			"replanStatus":       overallStatus,
		}
		EmitEvent(s, "disruption.reported", "disruption", disruptionID, respData)
		SaveIdempotency(s, "report_disruption", u.UserID, req.IdempotencyKey, rawBody, http.StatusCreated, respData)
		return nil
	})
	if err != nil {
		WriteError(w, err)
		return
	}
	if cached != nil {
		w.Header().Set("Content-Type", "application/json")
		w.WriteHeader(cached.StatusCode)
		_, _ = w.Write(cached.Response)
		return
	}
	WriteData(w, http.StatusCreated, respData)
}

var validChangeTypes = map[string]bool{
	"add_stop":        true,
	"remove_stop":     true,
	"reorder_stops":   true,
	"replace_worker":  true,
	"reassign_worker": true,
	"merge_samples":   true,
	"split_samples":   true,
	"split_batch":     true,
	"cancel_work":     true,
	"reroute":         true,
	"replace_route":   true,
}

func getStringField(m map[string]interface{}, keys ...string) string {
	for _, k := range keys {
		if v, ok := m[k]; ok {
			if s, ok := v.(string); ok && strings.TrimSpace(s) != "" {
				return strings.TrimSpace(s)
			}
		}
	}
	return ""
}

func getIntField(m map[string]interface{}, keys ...string) (int, bool) {
	for _, k := range keys {
		if v, ok := m[k]; ok {
			switch n := v.(type) {
			case float64:
				return int(n), true
			case int:
				return n, true
			}
		}
	}
	return 0, false
}

func getStringSliceField(m map[string]interface{}, keys ...string) []string {
	for _, k := range keys {
		if v, ok := m[k]; ok {
			if arr, ok := v.([]interface{}); ok {
				res := make([]string, 0, len(arr))
				for _, item := range arr {
					if s, ok := item.(string); ok {
						res = append(res, s)
					} else if obj, ok := item.(map[string]interface{}); ok {
						if id := getStringField(obj, "stopId", "locationId", "id"); id != "" {
							res = append(res, id)
						}
					}
				}
				return res
			}
		}
	}
	return nil
}

func findActiveConnectionBetween(s *db.State, fromLocID, toLocID string) *models.Connection {
	for _, c := range s.Connections {
		if c.Active && c.FromLocationID == fromLocID && c.ToLocationID == toLocID {
			return c
		}
	}
	return nil
}

func validateAndRebuildStopsOnJourney(s *db.State, j *models.Journey, candidateLocIDs []string, customDwell map[string]int) *APIError {
	if len(candidateLocIDs) < 2 {
		return NewErr(http.StatusConflict, "invalid_stop_order", "journey must have at least pickup and delivery locations")
	}

	// Verify completed stops prefix is unchanged
	for idx, st := range j.OrderedStops {
		if st.CompletedAt != "" {
			if idx >= len(candidateLocIDs) || candidateLocIDs[idx] != st.LocationID {
				return NewErr(http.StatusConflict, "completed_work_immutable", "cannot modify or reorder completed stops")
			}
		}
	}
	// Also check if any completed transport leg exists and would be altered
	for idx, lid := range j.LegAssignmentIDs {
		leg := s.Assignments[lid]
		if leg != nil && (leg.Status == "completed" || leg.Status == "delivered") {
			if idx+1 >= len(candidateLocIDs) || candidateLocIDs[idx] != leg.FromLocationID || candidateLocIDs[idx+1] != leg.ToLocationID {
				return NewErr(http.StatusConflict, "completed_work_immutable", "cannot modify completed transport legs")
			}
		}
		if leg != nil && (leg.Status == "picked_up" || leg.Status == "in_transit") {
			if idx+1 >= len(candidateLocIDs) || candidateLocIDs[idx] != leg.FromLocationID || candidateLocIDs[idx+1] != leg.ToLocationID {
				return NewErr(http.StatusConflict, "work_in_progress", "cannot modify transport leg currently in transit")
			}
		}
	}

	// Check for duplicate locations (loops)
	seen := make(map[string]bool)
	for _, lid := range candidateLocIDs {
		if seen[lid] {
			return NewErr(http.StatusConflict, "ambiguous_stop_order", "duplicate stop location in route")
		}
		seen[lid] = true
		loc, ok := s.Locations[lid]
		if !ok || !loc.Active {
			return NewErr(http.StatusConflict, "invalid_stop", "stop location not found or inactive")
		}
	}

	// Final stop must be an active accepting laboratory
	finalLocID := candidateLocIDs[len(candidateLocIDs)-1]
	finalLoc := s.Locations[finalLocID]
	if finalLoc == nil || !finalLoc.Active || !finalLoc.Functions.Laboratory {
		return NewErr(http.StatusConflict, "invalid_destination", "final stop must be an active laboratory")
	}
	for _, sid := range j.SampleIDs {
		if samp, ok := s.Samples[sid]; ok {
			if !LabAcceptsSampleType(s, finalLocID, samp.SampleTypeID) {
				return NewErr(http.StatusConflict, "invalid_destination", "destination laboratory does not accept sample type")
			}
		}
	}

	// First stop must match origin pickup location
	if len(j.OrderedStops) > 0 && candidateLocIDs[0] != j.OrderedStops[0].LocationID {
		return NewErr(http.StatusConflict, "invalid_stop_order", "pickup origin stop must remain first")
	}

	requiresCooled := j.Cooled
	var earliestDeadline time.Time
	var startTime time.Time
	for _, sid := range j.SampleIDs {
		if samp, ok := s.Samples[sid]; ok {
			if st := s.SampleTypes[samp.SampleTypeID]; SampleTypeRequiresCooled(st) {
				requiresCooled = true
			}
			if dl, ok := ParseTime(samp.DeliveryDeadline); ok && (earliestDeadline.IsZero() || dl.Before(earliestDeadline)) {
				earliestDeadline = dl
			}
			if reqT, ok := ParseTime(samp.RequestedAt); ok && startTime.IsZero() {
				startTime = reqT
				if ec, ok2 := ParseTime(samp.EarliestCollectionAt); ok2 && ec.After(startTime) {
					startTime = ec
				}
			}
		}
	}
	if startTime.IsZero() {
		startTime = time.Now().UTC()
	}

	units := len(j.SampleIDs)
	var conns []*models.Connection
	totalMin := 0
	totalCost := 0.0

	for i := 0; i < len(candidateLocIDs); i++ {
		loc := s.Locations[candidateLocIDs[i]]
		dwell := loc.HandlingMinutes
		if customDwell != nil {
			if d, ok := customDwell[loc.LocationID]; ok {
				dwell = d
			}
		}
		totalMin += dwell

		// Check location capacity if not already reserved by this journey
		alreadyLoc := 0
		for _, res := range s.Reservations {
			if !res.Released && res.JourneyID == j.JourneyID && res.ResourceType == "location" && res.ResourceID == loc.LocationID && res.Cooled == requiresCooled {
				alreadyLoc += res.Units
			}
		}
		if units-alreadyLoc > 0 && !LocationHasCapacity(loc, units-alreadyLoc, requiresCooled) {
			if requiresCooled {
				return NewErr(http.StatusConflict, "cooled_capacity_exhausted", "insufficient cooled capacity at stop location")
			}
			return NewErr(http.StatusConflict, "capacity_exhausted", "insufficient capacity at stop location")
		}

		if i < len(candidateLocIDs)-1 {
			conn := findActiveConnectionBetween(s, candidateLocIDs[i], candidateLocIDs[i+1])
			if conn == nil {
				return NewErr(http.StatusConflict, "invalid_route", "no active connection between consecutive stops")
			}
			if requiresCooled && !conn.Cooled {
				return NewErr(http.StatusConflict, "invalid_route_mode", "cooled sample requires cooled connection")
			}
			alreadyConn := 0
			for _, res := range s.Reservations {
				if !res.Released && res.JourneyID == j.JourneyID && res.ResourceType == "connection" && res.ResourceID == conn.ConnectionID && res.Cooled == requiresCooled {
					alreadyConn += res.Units
				}
			}
			if units-alreadyConn > 0 && !ConnectionHasCapacity(conn, units-alreadyConn, requiresCooled) {
				if requiresCooled {
					return NewErr(http.StatusConflict, "cooled_capacity_exhausted", "insufficient cooled capacity on connection")
				}
				return NewErr(http.StatusConflict, "capacity_exhausted", "insufficient capacity on connection")
			}
			conns = append(conns, conn)
			totalMin += conn.TravelMinutes
			totalCost += conn.CostUnits
		}
	}

	arrivalAt := startTime.Add(time.Duration(totalMin) * time.Minute)
	if !earliestDeadline.IsZero() && arrivalAt.After(earliestDeadline) {
		return NewErr(http.StatusConflict, "delivery_deadline_exceeded", "edited route exceeds delivery deadline")
	}

	// Rebuild stops and unfinished legs
	ReleaseJourneyCapacity(s, j.JourneyID)
	var connIDs []string
	for _, c := range conns {
		connIDs = append(connIDs, c.ConnectionID)
	}
	for _, sid := range j.SampleIDs {
		ReserveCapacityForSampleOnRoute(s, j.JourneyID, sid, candidateLocIDs, connIDs, requiresCooled)
	}

	newStops := make([]models.JourneyStop, 0, len(candidateLocIDs))
	elapsed := 0
	for i, lid := range candidateLocIDs {
		loc := s.Locations[lid]
		if i > 0 {
			elapsed += conns[i-1].TravelMinutes
		}
		dwell := loc.HandlingMinutes
		if customDwell != nil {
			if d, ok := customDwell[lid]; ok {
				dwell = d
			}
		}
		elapsed += dwell
		estStr := models.FormatTime(startTime.Add(time.Duration(elapsed) * time.Minute))
		stType := "handoff"
		if i == 0 {
			stType = "pickup"
		} else if i == len(candidateLocIDs)-1 {
			stType = "delivery"
		}
		var completedAt string
		for _, oldSt := range j.OrderedStops {
			if oldSt.LocationID == lid && oldSt.CompletedAt != "" {
				completedAt = oldSt.CompletedAt
				break
			}
		}
		c := loc.Coordinate
		dwellCopy := dwell
		newStops = append(newStops, models.JourneyStop{
			StopID:       uuid.NewString(),
			LocationID:   lid,
			Location_ID:  lid,
			StopType:     stType,
			Stop_Type:    stType,
			Sequence:     i + 1,
			EstimatedAt:  estStr,
			Estimated_At: estStr,
			DwellMinutes: &dwellCopy,
			Coordinate:   &c,
			CompletedAt:  completedAt,
		})
	}
	j.OrderedStops = newStops
	j.EstimatedDeliveryAt = models.FormatTime(arrivalAt)
	j.TotalCostUnits = totalCost
	j.TargetLaboratoryID = finalLocID
	if len(j.SampleIDs) > 1 {
		j.RouteMode = "batched"
	} else if len(conns) > 1 {
		j.RouteMode = "multi_stop"
	} else {
		j.RouteMode = "direct"
	}

	// Rebuild unfinished transport and node assignments
	var newAssignIDs []string
	var newLegIDs []string
	var newNodeIDs []string
	seq := 1
	for _, cid := range j.CollectionAssignmentIDs {
		if ca, ok := s.Assignments[cid]; ok {
			ca.Sequence = seq
			seq++
			newAssignIDs = append(newAssignIDs, cid)
		}
	}

	primarySID := j.SampleIDs[0]
	for i, conn := range conns {
		fromLoc := candidateLocIDs[i]
		toLoc := candidateLocIDs[i+1]
		// Reuse completed leg if matching
		var existingLeg *models.Assignment
		if i < len(j.LegAssignmentIDs) {
			candLeg := s.Assignments[j.LegAssignmentIDs[i]]
			if candLeg != nil && candLeg.FromLocationID == fromLoc && candLeg.ToLocationID == toLoc && candLeg.Status != "cancelled" {
				existingLeg = candLeg
			}
		}
		if existingLeg != nil {
			existingLeg.Sequence = seq
			existingLeg.LegSequence = i + 1
			seq++
			newAssignIDs = append(newAssignIDs, existingLeg.AssignmentID)
			newLegIDs = append(newLegIDs, existingLeg.AssignmentID)
		} else {
			legA := &models.Assignment{
				AssignmentID:        uuid.NewString(),
				Kind:                "transport",
				JourneyID:           j.JourneyID,
				SampleID:            primarySID,
				SampleIDs:           append([]string(nil), j.SampleIDs...),
				Sequence:            seq,
				LegSequence:         i + 1,
				Status:              "pending",
				FromLocationID:      fromLoc,
				ToLocationID:        toLoc,
				ConnectionID:        conn.ConnectionID,
				DeclinedByWorkerIDs: []string{},
				History:             []models.TimelineEntry{},
			}
			seq++
			s.Assignments[legA.AssignmentID] = legA
			newAssignIDs = append(newAssignIDs, legA.AssignmentID)
			newLegIDs = append(newLegIDs, legA.AssignmentID)
			OfferAssignmentToBestWorker(s, legA, startTime, "")
		}

		if i+1 < len(candidateLocIDs)-1 {
			nextOutLoc := candidateLocIDs[i+2]
			nodeA := &models.Assignment{
				AssignmentID:           uuid.NewString(),
				Kind:                   "node",
				JourneyID:              j.JourneyID,
				SampleID:               primarySID,
				SampleIDs:              append([]string(nil), j.SampleIDs...),
				Sequence:               seq,
				Status:                 "pending",
				NodeID:                 toLoc,
				FromLocationID:         toLoc,
				ToLocationID:           toLoc,
				IncomingFromLocationID: fromLoc,
				OutgoingToLocationID:   nextOutLoc,
				DeclinedByWorkerIDs:    []string{},
				History:                []models.TimelineEntry{},
			}
			seq++
			s.Assignments[nodeA.AssignmentID] = nodeA
			newAssignIDs = append(newAssignIDs, nodeA.AssignmentID)
			newNodeIDs = append(newNodeIDs, nodeA.AssignmentID)
			OfferAssignmentToBestWorker(s, nodeA, startTime, "")
		}
	}

	// Cancel replaced transport/node assignments
	keepSet := make(map[string]bool)
	for _, id := range newAssignIDs {
		keepSet[id] = true
	}
	for _, lid := range j.LegAssignmentIDs {
		if !keepSet[lid] {
			if oldA, ok := s.Assignments[lid]; ok && oldA.Status != "completed" {
				oldA.Status = "cancelled"
			}
		}
	}
	for _, nid := range j.NodeAssignmentIDs {
		if !keepSet[nid] {
			if oldA, ok := s.Assignments[nid]; ok && oldA.Status != "completed" {
				oldA.Status = "cancelled"
			}
		}
	}
	for _, lid := range j.LaboratoryAssignmentIDs {
		if la, ok := s.Assignments[lid]; ok {
			la.Sequence = seq
			la.LaboratoryID = finalLocID
			la.FromLocationID = finalLocID
			la.ToLocationID = finalLocID
			seq++
			newAssignIDs = append(newAssignIDs, lid)
		}
	}

	j.AssignmentIDs = newAssignIDs
	j.LegAssignmentIDs = newLegIDs
	j.NodeAssignmentIDs = newNodeIDs
	j.PlanVersion++

	return nil
}

func (srv *Server) handleEditActivePlan(w http.ResponseWriter, r *http.Request) {
	var req struct {
		JourneyID           string                 `json:"journeyId"`
		ExpectedPlanVersion *int                   `json:"expectedPlanVersion"`
		ChangeType          string                 `json:"changeType"`
		Changes             map[string]interface{} `json:"changes"`
		IdempotencyKey      string                 `json:"idempotencyKey"`
	}
	rawBody, apiErr := DecodeStrictJSON(r, &req)
	if apiErr != nil {
		WriteError(w, apiErr)
		return
	}

	var cached *models.IdempotencyRecord
	var respData map[string]interface{}
	err := srv.store.Write(r.Context(), func(s *db.State) error {
		u, sess, apiErr := AuthenticateSession(s, r)
		if apiErr != nil {
			return apiErr
		}
		role, apiErr := RequireActiveRole(s, u, sess, "edit_active_plan", "journey", req.JourneyID, true, "dispatcher", "administrator")
		if apiErr != nil {
			return apiErr
		}
		if strings.TrimSpace(req.IdempotencyKey) == "" {
			return NewErr(http.StatusBadRequest, "idempotency_required", "idempotencyKey is required")
		}
		if req.JourneyID == "" || req.ExpectedPlanVersion == nil || req.Changes == nil {
			return NewErr(http.StatusBadRequest, "invalid_json", "journeyId, expectedPlanVersion, changeType, and changes are required")
		}
		if *req.ExpectedPlanVersion < 1 {
			return NewErr(http.StatusBadRequest, "invalid_plan_version", "expectedPlanVersion must be >= 1")
		}
		if !validChangeTypes[req.ChangeType] {
			return NewErr(http.StatusBadRequest, "invalid_change_type", "invalid changeType")
		}
		rec, ierr := CheckIdempotency(s, "edit_active_plan", u.UserID, req.IdempotencyKey, rawBody)
		if ierr != nil {
			return ierr
		}
		if rec != nil {
			cached = rec
			return nil
		}

		j, ok := s.Journeys[req.JourneyID]
		if !ok {
			return NewErr(http.StatusNotFound, "not_found", "journey not found")
		}
		if j.Status != "active" {
			return NewErr(http.StatusConflict, "inactive_plan", "journey is not active")
		}
		if j.PlanVersion != *req.ExpectedPlanVersion {
			return NewErr(http.StatusConflict, "stale_plan", "expectedPlanVersion does not match current journey planVersion")
		}

		now := time.Now().UTC()
		nowStr := models.FormatTime(now)

		switch req.ChangeType {
		case "replace_worker", "reassign_worker":
			assignID := getStringField(req.Changes, "assignmentId", "legId", "targetAssignmentId")
			workerID := getStringField(req.Changes, "workerId", "newWorkerId", "targetWorkerId", "replacementWorkerId")
			if assignID == "" && len(j.LegAssignmentIDs) > 0 {
				assignID = j.LegAssignmentIDs[0]
			}
			if workerID == "" {
				return NewErr(http.StatusBadRequest, "invalid_worker", "workerId is required")
			}
			worker, exists := s.Users[workerID]
			if !exists {
				return NewErr(http.StatusBadRequest, "invalid_worker", "worker not found")
			}
			a, exists := s.Assignments[assignID]
			if !exists || a.JourneyID != j.JourneyID {
				return NewErr(http.StatusConflict, "invalid_assignment", "assignment not found on this journey")
			}
			if a.Status == "completed" || a.Status == "delivered" {
				return NewErr(http.StatusConflict, "completed_work_immutable", "cannot reassign a completed assignment")
			}
			if a.Status == "picked_up" || a.Status == "in_transit" {
				return NewErr(http.StatusConflict, "work_in_progress", "cannot reassign an assignment actively in transit")
			}
			if !worker.Active || !worker.Available {
				return NewErr(http.StatusConflict, "worker_unavailable", "replacement worker is unavailable")
			}
			if eligible, reason := IsWorkerEligibleForAssignment(s, worker, a, now, true); !eligible {
				s.IneligibleAttempts++
				if reason == "capacity_exceeded" {
					return NewErr(http.StatusConflict, "capacity_exceeded", "worker capacity exceeded")
				}
				return NewErr(http.StatusConflict, "ineligible_worker", "replacement worker is not eligible for this assignment")
			}
			a.WorkerID = worker.UserID
			a.OfferedToWorkerID = worker.UserID
			if a.Status == "pending" {
				a.OfferedAt = nowStr
				a.OfferExpiresAt = models.FormatTime(now.Add(15 * time.Minute))
			}
			worker.RecentAssignmentCount++
			worker.LastAssignedSeq = s.NextAssignmentSeq
			s.NextAssignmentSeq++
			j.PlanVersion++

		case "add_stop":
			locID := getStringField(req.Changes, "locationId", "nodeId", "stopLocationId")
			if locID == "" {
				if stopObj, ok := req.Changes["stop"].(map[string]interface{}); ok {
					locID = getStringField(stopObj, "locationId", "nodeId")
				}
			}
			if locID == "" {
				return NewErr(http.StatusConflict, "invalid_stop", "locationId is required to add stop")
			}
			dwell, hasDwell := getIntField(req.Changes, "dwellMinutes", "handlingMinutes")
			if !hasDwell {
				if stopObj, ok := req.Changes["stop"].(map[string]interface{}); ok {
					dwell, hasDwell = getIntField(stopObj, "dwellMinutes", "handlingMinutes")
				}
			}
			if hasDwell && dwell < 0 {
				return NewErr(http.StatusBadRequest, "invalid_dwell", "dwellMinutes cannot be negative")
			}

			seqPos, hasSeq := getIntField(req.Changes, "sequence", "position", "index")
			if !hasSeq {
				seqPos = len(j.OrderedStops) // insert before final delivery stop
			}
			if seqPos <= 1 || seqPos > len(j.OrderedStops) {
				// Check if inserting at index 1 violates completed stop
				if seqPos == 1 && len(j.OrderedStops) > 0 && j.OrderedStops[0].CompletedAt != "" {
					return NewErr(http.StatusConflict, "completed_work_immutable", "cannot insert stop before completed pickup stop")
				}
				if seqPos <= 1 {
					return NewErr(http.StatusConflict, "invalid_stop_order", "cannot insert stop before pickup stop")
				}
				seqPos = len(j.OrderedStops)
			}

			var candidateLocs []string
			for idx, st := range j.OrderedStops {
				if idx == seqPos-1 {
					candidateLocs = append(candidateLocs, locID)
				}
				candidateLocs = append(candidateLocs, st.LocationID)
			}
			customDwell := map[string]int{}
			if hasDwell {
				customDwell[locID] = dwell
			}
			if verr := validateAndRebuildStopsOnJourney(s, j, candidateLocs, customDwell); verr != nil {
				return verr
			}

		case "remove_stop":
			stopID := getStringField(req.Changes, "stopId")
			locID := getStringField(req.Changes, "locationId", "nodeId")
			seqPos, hasSeq := getIntField(req.Changes, "sequence", "index")

			removeIdx := -1
			for idx, st := range j.OrderedStops {
				if (stopID != "" && st.StopID == stopID) || (locID != "" && st.LocationID == locID) || (hasSeq && st.Sequence == seqPos) {
					removeIdx = idx
					break
				}
			}
			if removeIdx < 0 {
				return NewErr(http.StatusConflict, "invalid_stop", "stop to remove not found on journey")
			}
			if j.OrderedStops[removeIdx].CompletedAt != "" {
				return NewErr(http.StatusConflict, "completed_work_immutable", "cannot remove a completed stop")
			}
			if removeIdx == 0 || removeIdx == len(j.OrderedStops)-1 {
				return NewErr(http.StatusConflict, "invalid_stop", "cannot remove pickup or final laboratory delivery stop")
			}
			var candidateLocs []string
			for idx, st := range j.OrderedStops {
				if idx != removeIdx {
					candidateLocs = append(candidateLocs, st.LocationID)
				}
			}
			if verr := validateAndRebuildStopsOnJourney(s, j, candidateLocs, nil); verr != nil {
				return verr
			}

		case "reorder_stops":
			orderIDs := getStringSliceField(req.Changes, "stopIds", "orderedStopIds", "locationIds", "orderedLocationIds", "stops")
			if len(orderIDs) == 0 {
				return NewErr(http.StatusConflict, "invalid_stop_order", "ordered stops list is required")
			}
			if len(orderIDs) != len(j.OrderedStops) {
				return NewErr(http.StatusConflict, "invalid_stop_order", "reordered stops count must match current journey stops count")
			}
			// Map each ID (could be stopId or locationId) to locationId
			var candidateLocs []string
			for _, id := range orderIDs {
				mappedLoc := ""
				for _, st := range j.OrderedStops {
					if st.StopID == id || st.LocationID == id {
						mappedLoc = st.LocationID
						break
					}
				}
				if mappedLoc == "" {
					if _, exists := s.Locations[id]; exists {
						mappedLoc = id
					} else {
						return NewErr(http.StatusConflict, "invalid_stop", "unknown stop in reorder_stops: "+id)
					}
				}
				candidateLocs = append(candidateLocs, mappedLoc)
			}
			if verr := validateAndRebuildStopsOnJourney(s, j, candidateLocs, nil); verr != nil {
				return verr
			}

		case "reroute", "replace_route":
			locIDs := getStringSliceField(req.Changes, "locationIds", "routeLocationIds", "stops", "route")
			if len(locIDs) > 0 {
				if verr := validateAndRebuildStopsOnJourney(s, j, locIDs, nil); verr != nil {
					return verr
				}
			} else {
				statusRes, newJ := replanSingleJourney(s, u.UserID, role, j, now, "edit_active_plan:reroute", true)
				if statusRes == "expired" || newJ == nil {
					return NewErr(http.StatusConflict, "no_valid_route", "no valid replacement route found")
				}
				j = newJ
			}

		case "merge_samples":
			srcJourneyIDs := getStringSliceField(req.Changes, "sourceJourneyIds", "journeyIds")
			sampleIDs := getStringSliceField(req.Changes, "sampleIds")
			if sID := getStringField(req.Changes, "sampleId"); sID != "" {
				sampleIDs = append(sampleIDs, sID)
			}
			if sjID := getStringField(req.Changes, "sourceJourneyId"); sjID != "" {
				srcJourneyIDs = append(srcJourneyIDs, sjID)
			}
			for _, sid := range sampleIDs {
				if samp, exists := s.Samples[sid]; exists && samp.ActiveJourneyID != "" && samp.ActiveJourneyID != j.JourneyID {
					srcJourneyIDs = append(srcJourneyIDs, samp.ActiveJourneyID)
				}
			}
			if len(srcJourneyIDs) == 0 {
				return NewErr(http.StatusConflict, "invalid_batch", "no source journeys or samples specified for merge")
			}
			var srcJourneys []*models.Journey
			seenJ := make(map[string]bool)
			for _, sjID := range srcJourneyIDs {
				if sjID == j.JourneyID || seenJ[sjID] {
					continue
				}
				seenJ[sjID] = true
				sj, exists := s.Journeys[sjID]
				if !exists {
					return NewErr(http.StatusNotFound, "not_found", "source journey not found")
				}
				if sj.Status != "active" {
					return NewErr(http.StatusConflict, "inactive_plan", "source journey is not active")
				}
				srcJourneys = append(srcJourneys, sj)
			}
			if verr := validateBatchMerge(s, j, srcJourneys); verr != nil {
				return verr
			}
			executeBatchMerge(s, u, role, j, srcJourneys)

		case "split_samples", "split_batch":
			splitSIDs := getStringSliceField(req.Changes, "sampleIds")
			if sID := getStringField(req.Changes, "sampleId"); sID != "" {
				splitSIDs = append(splitSIDs, sID)
			}
			if _, serr := executeSplitJourney(s, u, role, j, splitSIDs); serr != nil {
				return serr
			}

		case "cancel_work":
			assignID := getStringField(req.Changes, "assignmentId", "legId")
			if assignID != "" {
				a, exists := s.Assignments[assignID]
				if !exists || a.JourneyID != j.JourneyID {
					return NewErr(http.StatusConflict, "invalid_assignment", "assignment not found on journey")
				}
				if a.Status == "completed" || a.Status == "delivered" {
					return NewErr(http.StatusConflict, "completed_work_immutable", "cannot cancel completed assignment")
				}
				a.Status = "cancelled"
				j.PlanVersion++
			} else {
				for _, lid := range j.LegAssignmentIDs {
					if leg, ok := s.Assignments[lid]; ok && (leg.Status == "completed" || leg.Status == "delivered") {
						return NewErr(http.StatusConflict, "completed_work_immutable", "cannot cancel completed work")
					}
				}
				j.Status = "cancelled"
				j.PlanVersion++
				for _, aid := range j.AssignmentIDs {
					if a, ok := s.Assignments[aid]; ok && a.Status != "completed" {
						a.Status = "cancelled"
					}
				}
				ReleaseJourneyCapacity(s, j.JourneyID)
				for _, sid := range j.SampleIDs {
					if samp, ok := s.Samples[sid]; ok && samp.Status != "received" {
						samp.Status = "cancelled"
					}
				}
			}
		}

		te := RecordAudit(s, u.UserID, role, "edit_active_plan", "journey", j.JourneyID, true, nowStr, map[string]interface{}{
			"journeyId":   j.JourneyID,
			"changeType":  req.ChangeType,
			"planVersion": j.PlanVersion,
			"changes":     req.Changes,
		})
		AppendJourneyHistory(j, te)
		for _, sid := range j.SampleIDs {
			if samp, ok := s.Samples[sid]; ok {
				AppendSampleTimeline(samp, te)
			}
		}

		respData = BuildJourneyPlanResponse(s, j)
		EmitEvent(s, "journey.edited", "journey", j.JourneyID, map[string]interface{}{
			"journeyId":   j.JourneyID,
			"changeType":  req.ChangeType,
			"planVersion": j.PlanVersion,
		})
		SaveIdempotency(s, "edit_active_plan", u.UserID, req.IdempotencyKey, rawBody, http.StatusCreated, respData)
		return nil
	})
	if err != nil {
		WriteError(w, err)
		return
	}
	if cached != nil {
		w.Header().Set("Content-Type", "application/json")
		w.WriteHeader(cached.StatusCode)
		_, _ = w.Write(cached.Response)
		return
	}
	_ = fmt.Sprintf
	WriteData(w, http.StatusCreated, respData)
}
