func canUserAccessSample(s *db.State, u *models.User, role string, sample *models.Sample) bool {
	if role == "administrator" || role == "dispatcher" {
		return true
	}
	if role == "requester" {
		return sample.RequesterID == u.UserID
	}
	if sample.CurrentHolderID == u.UserID {
		return true
	}
	for _, a := range s.Assignments {
		if a.WorkerID == u.UserID || a.OfferedToWorkerID == u.UserID {
			if a.SampleID == sample.SampleID {
				return true
			}
			for _, sid := range a.SampleIDs {
				if sid == sample.SampleID {
					return true
				}
			}
		}
	}
	return false
}

func buildSampleWorkItem(s *db.State, samp *models.Sample, now time.Time) map[string]interface{} {
	hist := samp.Timeline
	if hist == nil {
		hist = []models.TimelineEntry{}
	}
	item := map[string]interface{}{
		"kind":            "sample",
		"sampleId":        samp.SampleID,
		"sample_id":       samp.SampleID,
		"requestId":       samp.RequestID,
		"status":          samp.Status,
		"serviceability":  samp.Serviceability,
		"requestedAt":     samp.RequestedAt,
		"deliveryDeadline": samp.DeliveryDeadline,
		"earliestCollectionAt": samp.EarliestCollectionAt,
		"latestCollectionAt":   samp.LatestCollectionAt,
		"requesterId":     samp.RequesterID,
		"history":         hist,
		"locationStale":   IsSampleLocationStale(samp, now),
	}
	if samp.ActiveJourneyID != "" {
		item["journeyId"] = samp.ActiveJourneyID
		item["activeJourneyId"] = samp.ActiveJourneyID
	}
	if samp.TargetLaboratoryID != "" {
		item["laboratoryId"] = samp.TargetLaboratoryID
	}
	if samp.CurrentHolderID != "" {
		item["currentHolderId"] = samp.CurrentHolderID
	}
	if samp.LocationRecordedAt != "" {
		item["locationRecordedAt"] = samp.LocationRecordedAt
	}
	return item
}

func buildJourneyWorkItem(s *db.State, j *models.Journey) map[string]interface{} {
	hist := j.History
	if hist == nil {
		hist = []models.TimelineEntry{}
	}
	sids := j.SampleIDs
	if sids == nil {
		sids = []string{}
	}
	return map[string]interface{}{
		"kind":                "journey",
		"journeyId":           j.JourneyID,
		"journey_id":          j.JourneyID,
		"status":              j.Status,
		"routeMode":           j.RouteMode,
		"planVersion":         j.PlanVersion,
		"sampleIds":           sids,
		"estimatedDeliveryAt": j.EstimatedDeliveryAt,
		"assignmentCount":     len(j.AssignmentIDs),
		"history":             hist,
	}
}

func buildAssignmentWorkItem(s *db.State, a *models.Assignment) map[string]interface{} {
	hist := a.History
	if hist == nil {
		hist = []models.TimelineEntry{}
	}
	item := map[string]interface{}{
		"kind":          a.Kind,
		"assignmentId":  a.AssignmentID,
		"assignment_id": a.AssignmentID,
		"sampleId":      a.SampleID,
		"sample_id":     a.SampleID,
		"status":        a.Status,
		"journeyId":     a.JourneyID,
		"sequence":      a.Sequence,
		"history":       hist,
	}
	if a.FromLocationID != "" {
		item["fromLocationId"] = a.FromLocationID
	}
	if a.ToLocationID != "" {
		item["toLocationId"] = a.ToLocationID
	}
	if a.OfferExpiresAt != "" {
		item["offerExpiresAt"] = a.OfferExpiresAt
	}
	if a.NodeID != "" {
		item["nodeId"] = a.NodeID
		if loc, ok := s.Locations[a.NodeID]; ok {
			item["destinationCapacity"] = GetLocationCapacity(loc)
		}
	}
	if a.IncomingFromLocationID != "" {
		item["incomingFromLocationId"] = a.IncomingFromLocationIdOrDefault()
	}
	if a.OutgoingToLocationID != "" {
		item["outgoingToLocationId"] = a.OutgoingToLocationID
	}
	if a.LaboratoryID != "" {
		item["laboratoryId"] = a.LaboratoryID
		if loc, ok := s.Locations[a.LaboratoryID]; ok {
			item["destinationCapacity"] = GetLocationCapacity(loc)
		}
	}
	if a.ExpectedSampleTypeID != "" {
		item["expectedSampleTypeId"] = a.ExpectedSampleTypeID
	}
	if _, hasCap := item["destinationCapacity"]; !hasCap && a.ToLocationID != "" {
		if loc, ok := s.Locations[a.ToLocationID]; ok {
			item["destinationCapacity"] = GetLocationCapacity(loc)
		}
	}
	return item
}

func (srv *Server) handleListRoleWork(w http.ResponseWriter, r *http.Request) {
	var req struct {
		Role   string `json:"role"`
		Status string `json:"status"`
	}
	if _, apiErr := DecodeStrictJSON(r, &req); apiErr != nil {
		WriteError(w, apiErr)
		return
	}

	var respData map[string]interface{}
	var handlerErr error
	srv.store.Read(func(s *db.State) {
		u, sess, apiErr := AuthenticateSession(s, r)
		if apiErr != nil {
			handlerErr = apiErr
			return
		}
		if req.Role != "" && !ValidRoles[req.Role] {
			handlerErr = NewErr(http.StatusBadRequest, "invalid_role", "invalid role")
			return
		}
		activeRole := sess.ActiveRole
		if activeRole == "" {
			if len(u.Roles) == 1 {
				activeRole = u.Roles[0]
			} else {
				handlerErr = NewErr(http.StatusConflict, "role_not_selected", "must select an active role")
				return
			}
		}
		if !UserHasRole(u, activeRole) {
			handlerErr = NewErr(http.StatusForbidden, "forbidden", "active role not held")
			return
		}
		if req.Role != "" && req.Role != activeRole {
			handlerErr = NewErr(http.StatusForbidden, "forbidden", "cannot list work for a role other than the currently selected active role")
			return
		}

		now := time.Now().UTC()
		pending := make([]interface{}, 0)
		inProgress := make([]interface{}, 0)
		completed := make([]interface{}, 0)

		switch activeRole {
		case "requester":
			var samples []*models.Sample
			for _, samp := range s.Samples {
				if samp.RequesterID == u.UserID {
					samples = append(samples, samp)
				}
			}
			sort.Slice(samples, func(i, j int) bool {
				return samples[i].SampleID < samples[j].SampleID
			})
			for _, samp := range samples {
				item := buildSampleWorkItem(s, samp, now)
				switch samp.Status {
				case "received", "cancelled", "expired":
					completed = append(completed, item)
				case "sealed", "in_transit", "at_node", "at_laboratory":
					inProgress = append(inProgress, item)
				default:
					pending = append(pending, item)
				}
			}

		case "dispatcher", "administrator":
			var journeys []*models.Journey
			for _, j := range s.Journeys {
				journeys = append(journeys, j)
			}
			sort.Slice(journeys, func(i, j int) bool {
				return journeys[i].JourneyID < journeys[j].JourneyID
			})
			for _, j := range journeys {
				item := buildJourneyWorkItem(s, j)
				if j.Status == "completed" || j.Status == "cancelled" || j.Status == "replaced" || j.Status == "expired" {
					completed = append(completed, item)
				} else {
					hasStarted := false
					for _, aid := range j.AssignmentIDs {
						if a, ok := s.Assignments[aid]; ok && a.Status != "pending" {
							hasStarted = true
							break
						}
					}
					if hasStarted {
						inProgress = append(inProgress, item)
					} else {
						pending = append(pending, item)
					}
				}
			}

		case "collection_professional", "delivery_partner", "node_handler", "laboratory_team":
			targetKind := ""
			switch activeRole {
			case "collection_professional":
				targetKind = "collection"
			case "delivery_partner":
				targetKind = "transport"
			case "node_handler":
				targetKind = "node"
			case "laboratory_team":
				targetKind = "laboratory"
			}
			var assigns []*models.Assignment
			for _, a := range s.Assignments {
				if a.Kind != targetKind {
					continue
				}
				if a.WorkerID == u.UserID || a.OfferedToWorkerID == u.UserID {
					assigns = append(assigns, a)
				}
			}
			sort.Slice(assigns, func(i, j int) bool {
				if assigns[i].Sequence != assigns[j].Sequence {
					return assigns[i].Sequence < assigns[j].Sequence
				}
				return assigns[i].AssignmentID < assigns[j].AssignmentID
			})
			for _, a := range assigns {
				item := buildAssignmentWorkItem(s, a)
				switch a.Status {
				case "pending":
					pending = append(pending, item)
				case "completed", "cancelled", "declined":
					completed = append(completed, item)
				default:
					inProgress = append(inProgress, item)
				}
			}
		}

		respData = map[string]interface{}{
			"pending":    pending,
			"inProgress": inProgress,
			"completed":  completed,
		}
	})
	if handlerErr != nil {
		WriteError(w, handlerErr)
		return
	}
	WriteData(w, http.StatusOK, respData)
}

func (srv *Server) handleReadJourneyPlan(w http.ResponseWriter, r *http.Request) {
	var req struct {
		JourneyID string `json:"journeyId"`
	}
	if _, apiErr := DecodeStrictJSON(r, &req); apiErr != nil {
		WriteError(w, apiErr)
		return
	}

	var respData map[string]interface{}
	err := srv.store.Write(r.Context(), func(s *db.State) error {
		u, sess, apiErr := AuthenticateSession(s, r)
		if apiErr != nil {
			return apiErr
		}
		role, apiErr := RequireActiveRole(s, u, sess, "read_journey_plan", "journey", req.JourneyID, true)
		if apiErr != nil {
			return apiErr
		}
		if req.JourneyID == "" {
			return NewErr(http.StatusBadRequest, "invalid_json", "journeyId is required")
		}
		j, ok := s.Journeys[req.JourneyID]
		if !ok {
			return NewErr(http.StatusNotFound, "not_found", "journey not found")
		}

		nowStr := models.FormatTime(time.Now())
		switch role {
		case "administrator", "dispatcher":
			respData = BuildJourneyPlanResponse(s, j)
		case "requester":
			owns := false
			for _, sid := range j.SampleIDs {
				if samp, exists := s.Samples[sid]; exists && samp.RequesterID == u.UserID {
					owns = true
					break
				}
			}
			if !owns {
				RecordAudit(s, u.UserID, role, "read_journey_plan", "journey", j.JourneyID, false, nowStr, map[string]interface{}{
					"reason": "not_requester_owner",
				})
				return NewErr(http.StatusForbidden, "forbidden", "requester does not own any sample in this journey")
			}
			respData = BuildRequesterJourneyPlanResponse(s, j, u.UserID)
		default:
			// Worker role: verify worker has an assignment on this journey
			hasAssignment := false
			for _, aid := range j.AssignmentIDs {
				if a, exists := s.Assignments[aid]; exists && (a.WorkerID == u.UserID || a.OfferedToWorkerID == u.UserID) {
					hasAssignment = true
					break
				}
			}
			if !hasAssignment {
				RecordAudit(s, u.UserID, role, "read_journey_plan", "journey", j.JourneyID, false, nowStr, map[string]interface{}{
					"reason": "not_assigned_to_journey",
				})
				return NewErr(http.StatusForbidden, "forbidden", "worker is not assigned to this journey")
			}
			respData = BuildWorkerJourneyPlanResponse(s, j, u.UserID)
		}
		return nil
	})
	if err != nil {
		WriteError(w, err)
		return
	}
	WriteData(w, http.StatusOK, respData)
}

func buildOperationsState(s *db.State, filterSampleTypeID string) map[string]interface{} {
	now := time.Now().UTC()

	// 1. Samples
	var sampleList []*models.Sample
	for _, samp := range s.Samples {
		if filterSampleTypeID != "" && samp.SampleTypeID != filterSampleTypeID {
			continue
		}
		sampleList = append(sampleList, samp)
	}
	sort.Slice(sampleList, func(i, j int) bool {
		return sampleList[i].SampleID < sampleList[j].SampleID
	})
	samplesOut := make([]map[string]interface{}, 0, len(sampleList))
	for _, samp := range sampleList {
		so := map[string]interface{}{
			"sampleId":         samp.SampleID,
			"sample_id":        samp.SampleID,
			"status":           samp.Status,
			"requestId":        samp.RequestID,
			"origin":           samp.Origin,
			"deliveryDeadline": samp.DeliveryDeadline,
			"locationStale":    IsSampleLocationStale(samp, now),
		}
		if samp.CurrentHolderID != "" {
			so["currentHolderId"] = samp.CurrentHolderID
		}
		if samp.ActiveJourneyID != "" {
			so["activeJourneyId"] = samp.ActiveJourneyID
		}
		if samp.LatestLocation != nil {
			so["latestLocation"] = samp.LatestLocation
		}
		if samp.LocationRecordedAt != "" {
			so["locationRecordedAt"] = samp.LocationRecordedAt
		}
		samplesOut = append(samplesOut, so)
	}

	// 2. Workers
	var workerUsers []*models.User
	for _, u := range s.Users {
		isWorker := false
		for _, r := range u.Roles {
			if r == "collection_professional" || r == "delivery_partner" || r == "node_handler" || r == "laboratory_team" {
				isWorker = true
				break
			}
		}
		if isWorker {
			workerUsers = append(workerUsers, u)
		}
	}
	sort.Slice(workerUsers, func(i, j int) bool {
		return workerUsers[i].UserID < workerUsers[j].UserID
	})

	workersOut := make([]map[string]interface{}, 0, len(workerUsers))
	roleCounts := make(map[string][]int)
	for _, wu := range workerUsers {
		assignCount := wu.RecentAssignmentCount
		statusStr := "unavailable"
		if wu.Available && wu.Active {
			statusStr = "available"
			for _, r := range wu.Roles {
				roleCounts[r] = append(roleCounts[r], assignCount)
			}
		}
		wo := map[string]interface{}{
			"workerId":        wu.UserID,
			"worker_id":       wu.UserID,
			"fullName":        wu.FullName,
			"roles":           wu.Roles,
			"available":       wu.Available && wu.Active,
			"status":          statusStr,
			"capacityUnits":   wu.CapacityUnits,
			"assignmentCount": assignCount,
			"locationStale":   IsWorkerLocationStale(wu, now),
		}
		if wu.LatestLocation != nil {
			wo["latestLocation"] = wu.LatestLocation
			wo["latest_location"] = wu.LatestLocation
		}
		if wu.LocationRecordedAt != "" {
			wo["locationRecordedAt"] = wu.LocationRecordedAt
		}
		workersOut = append(workersOut, wo)
	}

	maxSpread := 0
	for _, counts := range roleCounts {
		if len(counts) > 1 {
			minC, maxC := counts[0], counts[0]
			for _, c := range counts[1:] {
				if c < minC {
					minC = c
				}
				if c > maxC {
					maxC = c
				}
			}
			if maxC-minC > maxSpread {
				maxSpread = maxC - minC
			}
		}
	}

	// 3. Locations
	var locList []*models.Location
	for _, loc := range s.Locations {
		locList = append(locList, loc)
	}
	sort.Slice(locList, func(i, j int) bool {
		return locList[i].LocationID < locList[j].LocationID
	})
	locsOut := make([]map[string]interface{}, 0, len(locList))
	for _, loc := range locList {
		acceptedIDs := make([]string, 0)
		for _, acc := range s.LabAcceptances {
			if acc.LaboratoryID == loc.LocationID && acc.Accepts {
				acceptedIDs = append(acceptedIDs, acc.SampleTypeID)
			}
		}
		sort.Strings(acceptedIDs)
		locsOut = append(locsOut, map[string]interface{}{
			"id":                    loc.LocationID,
			"locationId":            loc.LocationID,
			"name":                  loc.Name,
			"coordinate":            loc.Coordinate,
			"active":                loc.Active,
			"coverageKm":            loc.CoverageKm,
			"handlingMinutes":       loc.HandlingMinutes,
			"functions":             loc.Functions,
			"capacity":              GetLocationCapacity(loc),
			"acceptedSampleTypeIds": acceptedIDs,
		})
	}

	// 4. Connections
	var connList []*models.Connection
	for _, conn := range s.Connections {
		connList = append(connList, conn)
	}
	sort.Slice(connList, func(i, j int) bool {
		return connList[i].ConnectionID < connList[j].ConnectionID
	})
	connsOut := make([]map[string]interface{}, 0, len(connList))
	for _, conn := range connList {
		connsOut = append(connsOut, map[string]interface{}{
			"id":             conn.ConnectionID,
			"connectionId":   conn.ConnectionID,
			"fromLocationId": conn.FromLocationID,
			"toLocationId":   conn.ToLocationID,
			"travelMinutes":  conn.TravelMinutes,
			"costUnits":      conn.CostUnits,
			"cooled":         conn.Cooled,
			"active":         conn.Active,
			"capacity":       GetConnectionCapacity(conn),
		})
	}

	// 5. Routes (active journeys)
	var jList []*models.Journey
	for _, j := range s.Journeys {
		jList = append(jList, j)
	}
	sort.Slice(jList, func(i, j int) bool {
		return jList[i].JourneyID < jList[j].JourneyID
	})
	routesOut := make([]map[string]interface{}, 0, len(jList))
	for _, j := range jList {
		routesOut = append(routesOut, BuildJourneyPlanResponse(s, j))
	}

	// 6. Handoffs
	var hList []*models.Handoff
	for _, h := range s.Handoffs {
		hList = append(hList, h)
	}
	sort.Slice(hList, func(i, j int) bool {
		return hList[i].HandoffID < hList[j].HandoffID
	})
	handoffsOut := make([]interface{}, 0, len(hList))
	for _, h := range hList {
		handoffsOut = append(handoffsOut, h)
	}

	// 7. Delays & 8. Exceptions
	delaysOut := make([]interface{}, 0)
	exceptionsOut := make([]interface{}, 0)
	for _, samp := range sampleList {
		if samp.Status == "expired" {
			delaysOut = append(delaysOut, map[string]interface{}{
				"sampleId":         samp.SampleID,
				"status":           samp.Status,
				"deliveryDeadline": samp.DeliveryDeadline,
			})
		}
		if samp.Status == "exception" || samp.Exception != nil {
			if samp.Exception != nil {
				exceptionsOut = append(exceptionsOut, samp.Exception)
			} else {
				exceptionsOut = append(exceptionsOut, map[string]interface{}{
					"sampleId": samp.SampleID,
					"status":   samp.Status,
					"reason":   "exception",
				})
			}
		}
	}

	return map[string]interface{}{
		"samples":                   samplesOut,
		"workers":                   workersOut,
		"locations":                 locsOut,
		"connections":               connsOut,
		"routes":                    routesOut,
		"handoffs":                  handoffsOut,
		"delays":                    delaysOut,
		"exceptions":                exceptionsOut,
		"assignmentCountSpread":     maxSpread,
		"ineligibleAssignmentCount": 0,
	}
}

