func (srv *Server) handleSearchAuditTrail(w http.ResponseWriter, r *http.Request) {
	var req struct {
		Query      string `json:"query"`
		ActorID    string `json:"actorId"`
		EntityType string `json:"entityType"`
		EntityID   string `json:"entityId"`
		Action     string `json:"action"`
		Role       string `json:"role"`
		Success    *bool  `json:"success"`
		FromTime   string `json:"fromTime"`
		ToTime     string `json:"toTime"`
		Limit      *int   `json:"limit"`
		Offset     *int   `json:"offset"`
		Order      string `json:"order"`
	}
	if _, apiErr := DecodeStrictJSON(r, &req); apiErr != nil {
		WriteError(w, apiErr)
		return
	}

	var respData map[string]interface{}
	err := srv.store.Write(r.Context(), func(s *db.State) error {
		u, sess, apiErr := AuthenticateSession(s, r)
		if apiErr != nil {
			return apiErr
		}
		_, apiErr = RequireActiveRole(s, u, sess, "search_audit_trail", "audit", "search", true, "dispatcher", "administrator")
		if apiErr != nil {
			return apiErr
		}

		limit := 500
		if req.Limit != nil {
			if *req.Limit < 1 || *req.Limit > 5000 {
				return NewErr(http.StatusBadRequest, "invalid_limit", "limit must be between 1 and 5000")
			}
			limit = *req.Limit
		}
		offset := 0
		if req.Offset != nil {
			if *req.Offset < 0 {
				return NewErr(http.StatusBadRequest, "invalid_offset", "offset must be >= 0")
			}
			offset = *req.Offset
		}
		order := req.Order
		if order == "" {
			order = "newest_first"
		}
		if order != "newest_first" && order != "oldest_first" {
			return NewErr(http.StatusBadRequest, "invalid_order", "order must be newest_first or oldest_first")
		}

		var fromT, toT time.Time
		if req.FromTime != "" {
			t, ok := ParseTime(req.FromTime)
			if !ok {
				return NewErr(http.StatusBadRequest, "invalid_time", "invalid fromTime")
			}
			fromT = t
		}
		if req.ToTime != "" {
			t, ok := ParseTime(req.ToTime)
			if !ok {
				return NewErr(http.StatusBadRequest, "invalid_time", "invalid toTime")
			}
			toT = t
		}
		if !fromT.IsZero() && !toT.IsZero() && fromT.After(toT) {
			return NewErr(http.StatusBadRequest, "invalid_time", "fromTime cannot be after toTime")
		}

		qLower := strings.ToLower(strings.TrimSpace(req.Query))
		var matched []*models.AuditEntry

		for _, entry := range s.AuditLog {
			if req.ActorID != "" && entry.ActorID != req.ActorID {
				continue
			}
			if req.EntityType != "" && entry.EntityType != req.EntityType {
				continue
			}
			if req.EntityID != "" {
				matchEntity := entry.EntityID == req.EntityID
				if !matchEntity && entry.Details != nil {
					if entry.Details["sampleId"] == req.EntityID || entry.Details["requestId"] == req.EntityID || entry.Details["journeyId"] == req.EntityID || entry.Details["assignmentId"] == req.EntityID {
						matchEntity = true
					}
				}
				if !matchEntity {
					continue
				}
			}
			if req.Action != "" && entry.Action != req.Action {
				continue
			}
			if req.Role != "" && entry.Role != req.Role {
				continue
			}
			if req.Success != nil && entry.Success != *req.Success {
				continue
			}
			if !fromT.IsZero() || !toT.IsZero() {
				et, ok := ParseTime(entry.OccurredAt)
				if !ok {
					continue
				}
				if !fromT.IsZero() && et.Before(fromT) {
					continue
				}
				if !toT.IsZero() && et.After(toT) {
					continue
				}
			}
			if qLower != "" {
				rawBytes, _ := json.Marshal(entry)
				if !strings.Contains(strings.ToLower(string(rawBytes)), qLower) {
					continue
				}
			}
			matched = append(matched, entry)
		}

		if order == "newest_first" {
			sort.Slice(matched, func(i, j int) bool {
				return matched[i].Seq > matched[j].Seq
			})
		} else {
			sort.Slice(matched, func(i, j int) bool {
				return matched[i].Seq < matched[j].Seq
			})
		}

		total := len(matched)
		var page []*models.AuditEntry
		if offset < total {
			end := offset + limit
			if end > total {
				end = total
			}
			page = matched[offset:end]
		} else {
			page = []*models.AuditEntry{}
		}

		hasMore := (offset + len(page)) < total
		respData = map[string]interface{}{
			"entries":  page,
			"total":    total,
			"returned": len(page),
			"offset":   offset,
			"limit":    limit,
			"order":    order,
			"hasMore":  hasMore,
		}
		if hasMore {
			respData["nextOffset"] = offset + len(page)
		}
		return nil
	})
	if err != nil {
		WriteError(w, err)
		return
	}
	WriteData(w, http.StatusOK, respData)
}

func (srv *Server) handleReadUIBootstrap(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodGet {
		WriteError(w, NewErr(http.StatusMethodNotAllowed, "method_not_allowed", "method not allowed"))
		return
	}

	var respData map[string]interface{}
	var handlerErr error
	srv.store.Read(func(s *db.State) {
		u, sess, apiErr := AuthenticateSession(s, r)
		if apiErr != nil {
			handlerErr = apiErr
			return
		}
		activeRole := sess.ActiveRole
		roleSelectionReq := false
		if activeRole == "" {
			if len(u.Roles) == 1 {
				activeRole = u.Roles[0]
			} else {
				roleSelectionReq = true
			}
		}

		now := time.Now().UTC()
		nowStr := models.FormatTime(now)
		roles := u.Roles
		if roles == nil {
			roles = []string{}
		}

		userObj := map[string]interface{}{
			"userId":                u.UserID,
			"username":              u.Username,
			"roles":                 roles,
			"activeRole":            activeRole,
			"roleSelectionRequired": roleSelectionReq,
		}
		if u.FullName != "" {
			userObj["fullName"] = u.FullName
		}

		reqSamples := make([]map[string]interface{}, 0)
		for _, samp := range s.Samples {
			if activeRole == "requester" && samp.RequesterID != u.UserID {
				continue
			}
			stName := ""
			if st, ok := s.SampleTypes[samp.SampleTypeID]; ok {
				stName = st.Name
			}
			sMap := buildSampleWorkItem(s, samp, now)
			sMap["sampleTypeId"] = samp.SampleTypeID
			sMap["sampleTypeName"] = stName
			sMap["origin"] = samp.Origin
			sMap["originType"] = samp.OriginType
			if samp.LatestLocation != nil {
				sMap["latestLocation"] = samp.LatestLocation
			}
			if samp.Exception != nil {
				sMap["exception"] = samp.Exception
			}
			reqSamples = append(reqSamples, sMap)
		}
		sort.Slice(reqSamples, func(i, j int) bool {
			return reqSamples[i]["sampleId"].(string) < reqSamples[j]["sampleId"].(string)
		})

		respData = map[string]interface{}{
			"user":             userObj,
			"serverTime":       nowStr,
			"requesterSamples": reqSamples,
			"operations":       buildOperationsState(s, ""),
		}
	})
	if handlerErr != nil {
		WriteError(w, handlerErr)
		return
	}
	WriteData(w, http.StatusOK, respData)
}

