func (srv *Server) handleStreamRealtimeEvents(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodGet {
		WriteError(w, NewErr(http.StatusMethodNotAllowed, "method_not_allowed", "method not allowed"))
		return
	}

	var since int64
	if sinceStr := strings.TrimSpace(r.URL.Query().Get("since")); sinceStr != "" {
		if v, err := strconv.ParseInt(sinceStr, 10, 64); err == nil && v >= 0 {
			since = v
		}
	}

	var handlerErr error
	var events []*models.RealtimeEvent
	var cursor int64
	srv.store.Read(func(s *db.State) {
		_, _, apiErr := AuthenticateSession(s, r)
		if apiErr != nil {
			handlerErr = apiErr
			return
		}
		events = make([]*models.RealtimeEvent, 0)
		for _, ev := range s.Events {
			if ev.ID > since {
				events = append(events, ev)
				if ev.ID > cursor {
					cursor = ev.ID
				}
			}
		}
		if cursor < since {
			cursor = since
		}
	})
	if handlerErr != nil {
		WriteError(w, handlerErr)
		return
	}

	if strings.EqualFold(r.Header.Get("Upgrade"), "websocket") {
		var respHeader http.Header
		if proto := strings.TrimSpace(r.Header.Get("Sec-WebSocket-Protocol")); proto != "" {
			firstProto := strings.TrimSpace(strings.Split(proto, ",")[0])
			if firstProto != "" {
				respHeader = http.Header{"Sec-WebSocket-Protocol": []string{firstProto}}
			}
		}
		conn, err := wsUpgrader.Upgrade(w, r, respHeader)
		if err != nil {
			return
		}
		defer conn.Close()

		for _, ev := range events {
			if err := conn.WriteJSON(ev); err != nil {
				return
			}
		}

		sub := srv.store.Subscribe()
		defer srv.store.Unsubscribe(sub)

		closeCh := make(chan struct{})
		go func() {
			defer close(closeCh)
			for {
				if _, _, err := conn.ReadMessage(); err != nil {
					return
				}
			}
		}()

		for {
			select {
			case <-r.Context().Done():
				return
			case <-closeCh:
				return
			case ev, ok := <-sub:
				if !ok {
					return
				}
				if err := conn.WriteJSON(ev); err != nil {
					return
				}
			}
		}
	}

	WriteData(w, http.StatusOK, map[string]interface{}{
		"events": events,
		"cursor": cursor,
	})
}

func (srv *Server) handleSystemReadiness(w http.ResponseWriter, r *http.Request) {
	if err := srv.store.Ping(r.Context()); err != nil {
		WriteJSON(w, http.StatusServiceUnavailable, map[string]string{
			"status": "starting",
		})
		return
	}
	WriteJSON(w, http.StatusOK, map[string]string{
		"status": "ready",
	})
}
