	s.mux.HandleFunc("/api/configure-laboratory-acceptance", postOnly(s.handleConfigureLaboratoryAcceptance))
	s.mux.HandleFunc("/api/configure-capacity", postOnly(s.handleConfigureCapacity))
	s.mux.HandleFunc("/api/set-worker-availability", postOnly(s.handleSetWorkerAvailability))

	s.mux.HandleFunc("/api/check-serviceability", postOnly(s.handleCheckServiceability))
