	s.mux.HandleFunc("/api/ui/bootstrap", s.handleReadUIBootstrap)
	s.mux.HandleFunc("/api/events", s.handleStreamRealtimeEvents)

	if s.mapAssetDir != "" {
		fs := http.StripPrefix("/map-assets/", http.FileServer(http.Dir(s.mapAssetDir)))
		s.mux.HandleFunc("/map-assets/", func(w http.ResponseWriter, r *http.Request) {
			w.Header().Set("Access-Control-Allow-Origin", "*")
			w.Header().Set("Accept-Ranges", "bytes")
			fs.ServeHTTP(w, r)
		})
	}

	s.mux.HandleFunc("/", s.handleStaticOrSPA)
}

func (s *Server) handleStaticOrSPA(w http.ResponseWriter, r *http.Request) {
	if strings.HasPrefix(r.URL.Path, "/api/") {
		WriteError(w, NewErr(http.StatusNotFound, "not_found", "api endpoint not found"))
		return
	}
	if s.frontendDir == "" {
		w.WriteHeader(http.StatusOK)
		_, _ = w.Write([]byte("Lab Sample Pickup & Delivery System"))
		return
	}
	cleanPath := filepath.Clean(r.URL.Path)
	if cleanPath == "/" {
		http.ServeFile(w, r, filepath.Join(s.frontendDir, "index.html"))
		return
	}
	fullPath := filepath.Join(s.frontendDir, strings.TrimPrefix(cleanPath, "/"))
	if info, err := os.Stat(fullPath); err == nil && !info.IsDir() {
		http.ServeFile(w, r, fullPath)
		return
	}
	http.ServeFile(w, r, filepath.Join(s.frontendDir, "index.html"))
}

func (s *Server) ServeHTTP(w http.ResponseWriter, r *http.Request) {
	s.mux.ServeHTTP(w, r)
}
