{"command":"create","path":"/workspace/backend/cmd/server/main.go","file_text":"package main

import (
	"context"
	"log"
	"net/http"
	"os"
	"os/signal"
	"syscall"
	"time"

	"labsample/internal/api"
	"labsample/internal/db"
)

func main() {
	ctx, cancel := context.WithCancel(context.Background())
	defer cancel()

	pool, err := db.ConnectPool(ctx)
	if err != nil {
		log.Fatalf("connect database: %v", err)
	}
	defer pool.Close()

	store, err := db.NewStore(ctx, pool)
	if err != nil {
		log.Fatalf("init store: %v", err)
	}

	frontendDir := os.Getenv("FRONTEND_DIST_DIR")
	if frontendDir == "" {
		frontendDir = "/workspace/frontend/dist"
	}
	mapAssetDir := os.Getenv("OFFLINE_MAP_ASSET_DIR")
	if mapAssetDir == "" {
		mapAssetDir = "/opt/arena/map-assets"
	}

	srv := api.NewServer(store, frontendDir, mapAssetDir)

	addr := os.Getenv("LISTEN_ADDR")
	if addr == "" {
		port := os.Getenv("PORT")
		if port == "" {
			port = "8080"
		}
		addr = "127.0.0.1:" + port
	}

	httpServer := &http.Server{
		Addr:              addr,
		Handler:           srv,
		ReadHeaderTimeout: 10 * time.Second,
	}

	sigCh := make(chan os.Signal, 1)
	signal.Notify(sigCh, syscall.SIGINT, syscall.SIGTERM)

	go func() {
		<-sigCh
		shutdownCtx, shutdownCancel := context.WithTimeout(context.Background(), 5*time.Second)
		defer shutdownCancel()
		_ = httpServer.Shutdown(shutdownCtx)
	}()

	log.Printf("Lab Sample Pickup & Delivery server listening on http://%s", addr)
	if err := httpServer.ListenAndServe(); err != nil && err != http.ErrServerClosed {
		log.Fatalf("server error: %v", err)
	}
}
