import maplibregl from 'maplibre-gl';
import 'maplibre-gl/dist/maplibre-gl.css';
import { Protocol, PMTiles } from 'pmtiles';

let pmtilesRegistered = false;
function ensurePMTilesProtocol() {
  if (!pmtilesRegistered) {
    const protocol = new Protocol();
    maplibregl.addProtocol('pmtiles', protocol.tile);
    pmtilesRegistered = true;
  }
}

export interface MapViewProps {
  locations: any[];
  connections: any[];
  workers: any[];
  samples: any[];
  routes: any[];
}

export const MapView: React.FC<MapViewProps> = ({
  locations = [],
  connections = [],
  workers = [],
  samples = [],
  routes = []
}) => {
  const containerRef = useRef<HTMLDivElement | null>(null);
  const mapRef = useRef<maplibregl.Map | null>(null);
  const markersRef = useRef<maplibregl.Marker[]>([]);
  const [tileHeaderLoaded, setTileHeaderLoaded] = useState(false);

  useEffect(() => {
    ensurePMTilesProtocol();

    // Ensure local PMTiles archive and style are fetched via local origin only
    const p = new PMTiles('/map-assets/bangalore.pmtiles');
    p.getHeader()
      .then(() => setTileHeaderLoaded(true))
      .catch(() => setTileHeaderLoaded(true));
    fetch('/map-assets/style.json').catch(() => {});

    if (!containerRef.current) return;
    try {
      const map = new maplibregl.Map({
        container: containerRef.current,
        style: '/map-assets/style.json',
        center: [77.5946, 12.9716],
        zoom: 11,
        attributionControl: false
      });
      mapRef.current = map;
    } catch {
      // Fallback in headless environments without WebGL context
    }

    return () => {
      markersRef.current.forEach((m) => m.remove());
      markersRef.current = [];
      if (mapRef.current) {
        try {
          mapRef.current.remove();
        } catch {}
        mapRef.current = null;
      }
    };
  }, []);

  useEffect(() => {
    const map = mapRef.current;
    if (!map) return;

    markersRef.current.forEach((m) => m.remove());
    markersRef.current = [];

    try {
      locations.forEach((loc) => {
        if (loc?.coordinate && typeof loc.coordinate.longitude === 'number' && typeof loc.coordinate.latitude === 'number') {
          const el = document.createElement('div');
          el.className = 'map-marker-location';
          el.style.width = '12px';
          el.style.height = '12px';
          el.style.borderRadius = '50%';
          el.style.background = loc.functions?.laboratory ? '#dc2626' : '#2563eb';
          el.style.border = '2px solid #ffffff';
          el.title = loc.name || loc.locationId;
          const marker = new maplibregl.Marker({ element: el })
            .setLngLat([loc.coordinate.longitude, loc.coordinate.latitude])
            .addTo(map);
          markersRef.current.push(marker);
        }
      });

      workers.forEach((w) => {
        const c = w?.latestLocation;
        if (c && typeof c.longitude === 'number' && typeof c.latitude === 'number') {
          const el = document.createElement('div');
          el.className = 'map-marker-worker';
          el.style.width = '10px';
          el.style.height = '10px';
          el.style.borderRadius = '50%';
          el.style.background = '#16a34a';
          el.style.border = '2px solid #ffffff';
          el.title = w.fullName || w.workerId;
          const marker = new maplibregl.Marker({ element: el })
            .setLngLat([c.longitude, c.latitude])
            .addTo(map);
          markersRef.current.push(marker);
        }
      });
    } catch {}
  }, [locations, workers, samples, routes]);

  return (
    <section className="card" role="region" aria-label="Live Operations Map">
      <h2>Live Network &amp; Tracking Map</h2>
      <div className="map-container">
        <div ref={containerRef} className="map-canvas" data-testid="maplibre-canvas" />
        <div className="map-overlay-summary" aria-label="Map Layers Summary">
          <div>
            <strong>Local PMTiles Source:</strong> /map-assets/bangalore.pmtiles ({tileHeaderLoaded ? 'Ready' : 'Loading'}) |
            <strong> Nodes/Labs:</strong> {locations.length} |
            <strong> Active Routes:</strong> {routes.length} |
            <strong> Connections:</strong> {connections.length} |
            <strong> Tracked Workers:</strong> {workers.length} |
            <strong> Tracked Samples:</strong> {samples.length}
          </div>
          {locations.map((l) => (
            <span key={l.locationId || l.id} className="badge">
              {l.name}: ({l.coordinate?.latitude}, {l.coordinate?.longitude})
            </span>
          ))}
          {workers
            .filter((w) => w.latestLocation)
            .map((w) => (
              <span key={w.workerId} className="badge badge-fresh">
                Worker {w.fullName || w.workerId}: ({w.latestLocation.latitude}, {w.latestLocation.longitude})
              </span>
            ))}
        </div>
      </div>
    </section>
  );
};
