  },
  {
    id: '00000000-0000-4000-8000-000000000003',
    name: 'Frost',
    containerType: 'cryo-box',
    temperatureMinC: -20,
    temperatureMaxC: -5
  },
  {
    id: '00000000-0000-4000-8000-000000000004',
    name: 'Pulse',
    containerType: 'stat-carrier',
    temperatureMinC: 2,
    temperatureMaxC: 8
  }
];

function makeIdempotencyKey(prefix: string): string {
  return `${prefix}-${Date.now()}-${Math.random().toString(36).slice(2, 9)}`;
}

export const App: React.FC = () => {
  const [token, setToken] = useState<string>(() => localStorage.getItem('arena_token') || '');
  const [username, setUsername] = useState('');
  const [password, setPassword] = useState('');
  const [loginError, setLoginError] = useState('');

  const [bootstrap, setBootstrap] = useState<any | null>(null);
  const [roleWork, setRoleWork] = useState<{ pending: any[]; inProgress: any[]; completed: any[] }>({
    pending: [],
    inProgress: [],
    completed: []
  });
  const [sampleDetails, setSampleDetails] = useState<Record<string, { state?: any; lifecycle?: any; journey?: any }>>({});
  const [actionAlert, setActionAlert] = useState<{ type: 'error' | 'info'; text: string } | null>(null);

  // Request & Serviceability Form State
  const [originType, setOriginType] = useState('home');
  const [originLat, setOriginLat] = useState('12.9716');
  const [originLng, setOriginLng] = useState('77.5946');
  const [sampleTypeId, setSampleTypeId] = useState(BUILTIN_SAMPLE_TYPES[0].id);
  const [containerType, setContainerType] = useState(BUILTIN_SAMPLE_TYPES[0].containerType);
  const [tempMin, setTempMin] = useState(String(BUILTIN_SAMPLE_TYPES[0].temperatureMinC));
  const [tempMax, setTempMax] = useState(String(BUILTIN_SAMPLE_TYPES[0].temperatureMaxC));
  const [requestedAt, setRequestedAt] = useState(() => new Date().toISOString());
  const [earliestAt, setEarliestAt] = useState(() => new Date().toISOString());
  const [latestAt, setLatestAt] = useState(() => new Date(Date.now() + 2 * 3600 * 1000).toISOString());
  const [deadlineAt, setDeadlineAt] = useState(() => new Date(Date.now() + 4 * 3600 * 1000).toISOString());
  const [requestFormError, setRequestFormError] = useState('');
  const [serviceabilityResult, setServiceabilityResult] = useState<any | null>(null);

  // Worker Location State
  const [workerLat, setWorkerLat] = useState('12.9725');
  const [workerLng, setWorkerLng] = useState('77.5955');
  const [workerSeq, setWorkerSeq] = useState<Record<string, number>>({});

  // Capacity Edit State
  const [selectedCapLocId, setSelectedCapLocId] = useState('');
  const [capRegularUnits, setCapRegularUnits] = useState('10');
  const [capCooledUnits, setCapCooledUnits] = useState('5');

  // Audit Search State
  const [auditQuery, setAuditQuery] = useState('');
  const [auditEntries, setAuditEntries] = useState<any[]>([]);
  const [auditTotal, setAuditTotal] = useState(0);

  const apiFetch = useCallback(
    async (path: string, options: RequestInit = {}, overrideToken?: string) => {
      const activeTok = overrideToken !== undefined ? overrideToken : token;
      const headers: Record<string, string> = {
        'Content-Type': 'application/json',
        ...(options.headers as Record<string, string>)
      };
      if (activeTok) {
        headers['Authorization'] = `Bearer ${activeTok}`;
      }
      const res = await fetch(path, { ...options, headers });
      let json: any = null;
      try {
        json = await res.json();
      } catch {}
      return { status: res.status, ok: res.ok, json };
    },
    [token]
  );

  const loadSampleDetails = useCallback(
    async (sampleIds: string[], activeTok?: string) => {
      const nextDetails: Record<string, { state?: any; lifecycle?: any; journey?: any }> = {};
      for (const sid of sampleIds) {
        if (!sid) continue;
        const [stRes, lcRes] = await Promise.all([
          apiFetch(`/api/read-sample-state/${sid}`, { method: 'GET' }, activeTok),
          apiFetch('/api/read-sample-lifecycle', { method: 'POST', body: JSON.stringify({ sampleId: sid }) }, activeTok)
        ]);
        const entry: { state?: any; lifecycle?: any; journey?: any } = {};
        if (stRes.ok && stRes.json?.data) {
          entry.state = stRes.json.data;
        }
        if (lcRes.ok && lcRes.json?.data) {
          entry.lifecycle = lcRes.json.data;
        }
        const jid = entry.lifecycle?.activeJourneyId || entry.state?.activeJourneyId;
        if (jid) {
          const jRes = await apiFetch(
            '/api/read-journey-plan',
            { method: 'POST', body: JSON.stringify({ journeyId: jid }) },
            activeTok
          );
          if (jRes.ok && jRes.json?.data) {
            entry.journey = jRes.json.data;
          }
        }
        nextDetails[sid] = entry;
      }
      setSampleDetails((prev) => ({ ...prev, ...nextDetails }));
    },
    [apiFetch]
  );

  const loadAuditLogs = useCallback(
    async (queryText: string, activeTok?: string) => {
      const res = await apiFetch(
        '/api/search-audit-trail',
        {
          method: 'POST',
          body: JSON.stringify({ query: queryText || undefined, limit: 100, order: 'newest_first' })
        },
        activeTok
      );
      if (res.ok && res.json?.data) {
        setAuditEntries(res.json.data.entries || []);
        setAuditTotal(res.json.data.total || 0);
      }
    },
    [apiFetch]
  );

  const refreshAll = useCallback(
    async (overrideToken?: string) => {
      const activeTok = overrideToken !== undefined ? overrideToken : token;
      if (!activeTok) return;

      const bootRes = await apiFetch('/api/ui/bootstrap', { method: 'GET' }, activeTok);
      if (bootRes.status === 401) {
        localStorage.removeItem('arena_token');
        setToken('');
        setBootstrap(null);
        return;
      }
      if (!bootRes.ok || !bootRes.json?.data) return;

      const bootData = bootRes.json.data;
      setBootstrap(bootData);

      const locs = bootData.operations?.locations || [];
      if (locs.length > 0 && !selectedCapLocId) {
        setSelectedCapLocId(locs[0].locationId || locs[0].id);
      }
      // Pick first accepted sample type from any lab if not in built-ins
      for (const l of locs) {
        if (Array.isArray(l.acceptedSampleTypeIds) && l.acceptedSampleTypeIds.length > 0) {
          const firstAcc = l.acceptedSampleTypeIds[0];
          if (!BUILTIN_SAMPLE_TYPES.some((b) => b.id === firstAcc)) {
            setSampleTypeId((prev) => (prev === BUILTIN_SAMPLE_TYPES[0].id ? firstAcc : prev));
          }
        }
      }

      const activeRole = bootData.user?.activeRole;
      const sampleIdSet = new Set<string>();
      (bootData.requesterSamples || []).forEach((s: any) => sampleIdSet.add(s.sampleId));
      (bootData.operations?.samples || []).forEach((s: any) => sampleIdSet.add(s.sampleId));

      if (activeRole) {
        const workRes = await apiFetch(
          '/api/list-role-work',
          { method: 'POST', body: JSON.stringify({ role: activeRole }) },
          activeTok
        );
        if (workRes.ok && workRes.json?.data) {
          const rw = workRes.json.data;
          setRoleWork({
            pending: rw.pending || [],
            inProgress: rw.inProgress || [],
            completed: rw.completed || []
          });
          [...(rw.pending || []), ...(rw.inProgress || []), ...(rw.completed || [])].forEach((item: any) => {
            if (item.sampleId) sampleIdSet.add(item.sampleId);
          });
        }
        if (activeRole === 'dispatcher' || activeRole === 'administrator') {
          await loadAuditLogs(auditQuery, activeTok);
        }
      }

      if (sampleIdSet.size > 0) {
        await loadSampleDetails(Array.from(sampleIdSet), activeTok);
