  const handleLogin = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoginError('');
    setActionAlert(null);

    if (!username.trim() || !password) {
      setLoginError('Invalid credentials: username and password are required');
      return;
    }

    const res = await apiFetch(
      '/api/authenticate-user',
      {
        method: 'POST',
        body: JSON.stringify({ username: username.trim(), password })
      },
      ''
    );

    if (!res.ok || !res.json?.data?.token) {
      const msg = res.json?.error?.message || 'Invalid username or password';
      const code = res.json?.error?.code || 'invalid_credentials';
      setLoginError(`Authentication failed: ${msg} (${code})`);
      return;
    }

    const newTok = res.json.data.token;
    localStorage.setItem('arena_token', newTok);
    setToken(newTok);
    await refreshAll(newTok);
  };

  const handleSignOut = () => {
    localStorage.removeItem('arena_token');
    setToken('');
    setBootstrap(null);
    setRoleWork({ pending: [], inProgress: [], completed: [] });
    setSampleDetails({});
    setUsername('');
    setPassword('');
    setLoginError('');
  };

  const handleSelectRole = async (newRole: string) => {
