    }
    const res = await apiFetch('/api/check-serviceability', {
      method: 'POST',
      body: JSON.stringify({
        origin: { latitude: lat, longitude: lng },
        originType,
        sampleTypeId,
        requestedAt,
        earliestCollectionAt: earliestAt,
        latestCollectionAt: latestAt,
        deliveryDeadline: deadlineAt
      })
    });
    if (!res.ok) {
      setRequestFormError(
        `Validation Error: ${res.json?.error?.message || 'Invalid serviceability check'} (${res.json?.error?.code || 'error'})`
      );
      return;
    }
    setServiceabilityResult(res.json.data);
  };

  const handleCreateRequest = async (e: React.FormEvent) => {
    e.preventDefault();
    setRequestFormError('');
    const lat = Number(originLat);
    const lng = Number(originLng);
    const tMin = Number(tempMin);
    const tMax = Number(tempMax);

    if (
      originLat.trim() === '' ||
      originLng.trim() === '' ||
      Number.isNaN(lat) ||
      Number.isNaN(lng) ||
      lat < -90 ||
      lat > 90 ||
      lng < -180 ||
      lng > 180
    ) {
      setRequestFormError('Validation Error: Invalid origin coordinates (invalid_origin)');
      return;
    }
    if (!containerType.trim() || Number.isNaN(tMin) || Number.isNaN(tMax) || tMin > tMax) {
      setRequestFormError('Validation Error: Invalid handling or temperature range (handling_mismatch)');
      return;
    }

    const res = await apiFetch('/api/create-collection-request', {
      method: 'POST',
      body: JSON.stringify({
        origin: { latitude: lat, longitude: lng },
        originType,
        sampleTypeId,
        containerType: containerType.trim(),
        temperatureMinC: tMin,
        temperatureMaxC: tMax,
        requestedAt,
        earliestCollectionAt: earliestAt,
        latestCollectionAt: latestAt,
        deliveryDeadline: deadlineAt,
        idempotencyKey: makeIdempotencyKey('req')
      })
    });

    if (!res.ok) {
      setRequestFormError(
        `Validation Error: ${res.json?.error?.message || 'Request rejected'} (${res.json?.error?.code || 'invalid_request'})`
      );
      return;
    }
    setActionAlert({
      type: 'info',
      text: `Collection request created: Sample ${res.json.data.sampleId} (${res.json.data.serviceability})`
