      method: 'POST',
      body: JSON.stringify({
        assignmentId,
        idempotencyKey: makeIdempotencyKey('accept')
      })
    });
    if (!res.ok) {
      setActionAlert({
        type: 'error',
        text: `${res.json?.error?.message || 'Failed to accept assignment'} (${res.json?.error?.code})`
      });
      return;
    }
    setActionAlert({
      type: 'info',
      text: `Assignment ${assignmentId} accepted`
    });
    await refreshAll();
  };

  const handleDeclineAssignment = async (assignmentId: string) => {
