    const temp = sampleState ? (sampleState.temperatureMinC + sampleState.temperatureMaxC) / 2 : 5;
    const res = await apiFetch('/api/collect-and-seal-sample', {
      method: 'POST',
      body: JSON.stringify({
        sampleId: item.sampleId,
        assignmentId: item.assignmentId,
        collectedAt: new Date().toISOString(),
        containerType: cType,
        observedTemperatureC: temp,
        idempotencyKey: makeIdempotencyKey('seal')
      })
    });
    if (!res.ok) {
      setActionAlert({
        type: 'error',
        text: `${res.json?.error?.message || 'Failed to collect and seal'} (${res.json?.error?.code})`
      });
      return;
    }
    setActionAlert({
      type: 'info',
      text: `Sample ${item.sampleId} collected and sealed`
    });
    await refreshAll();
  };

  const handleUpdateProgress = async (assignmentId: string, status: string) => {
    setActionAlert(null);
    const res = await apiFetch('/api/update-assignment-progress', {
      method: 'POST',
      body: JSON.stringify({
        assignmentId,
        status,
        occurredAt: new Date().toISOString(),
        idempotencyKey: makeIdempotencyKey('prog')
      })
    });
    if (!res.ok) {
      setActionAlert({
        type: 'error',
        text: `${res.json?.error?.message || 'Failed to update progress'} (${res.json?.error?.code})`
      });
      return;
    }
    setActionAlert({
      type: 'info',
      text: `Assignment ${assignmentId} updated to ${status}`
    });
    await refreshAll();
  };

  const handleConfirmReceipt = async (item: any) => {
    setActionAlert(null);
    const res = await apiFetch('/api/confirm-laboratory-receipt', {
      method: 'POST',
      body: JSON.stringify({
        sampleId: item.sampleId,
        laboratoryId: item.laboratoryId || item.toLocationId,
        receivedAt: new Date().toISOString(),
        idempotencyKey: makeIdempotencyKey('receipt')
      })
    });
    if (!res.ok) {
      setActionAlert({
        type: 'error',
        text: `${res.json?.error?.message || 'Failed to confirm receipt'} (${res.json?.error?.code})`
      });
      return;
    }
    setActionAlert({
      type: 'info',
      text: `Sample ${item.sampleId} received at laboratory`
    });
    await refreshAll();
  };

  const handleRecordLabException = async (item: any) => {
    setActionAlert(null);
    const res = await apiFetch('/api/record-laboratory-exception', {
      method: 'POST',
      body: JSON.stringify({
        sampleId: item.sampleId,
        laboratoryId: item.laboratoryId || item.toLocationId,
        reason: 'damaged_seal_or_noncompliant',
        observedAt: new Date().toISOString(),
        idempotencyKey: makeIdempotencyKey('labexc')
      })
    });
    if (!res.ok) {
      setActionAlert({
        type: 'error',
        text: `${res.json?.error?.message || 'Failed to record exception'} (${res.json?.error?.code})`
      });
      return;
    }
    setActionAlert({
      type: 'info',
      text: `Exception recorded for sample ${item.sampleId}`
    });
    await refreshAll();
  };

  const handleConfigureCapacity = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!selectedCapLocId) return;
    const res = await apiFetch('/api/configure-capacity', {
      method: 'POST',
      body: JSON.stringify({
        resourceType: 'location',
        resourceId: selectedCapLocId,
        capacityUnits: Number(capRegularUnits),
        cooledCapacityUnits: Number(capCooledUnits)
      })
    });
    if (!res.ok) {
      setActionAlert({
        type: 'error',
        text: `${res.json?.error?.message || 'Failed to configure capacity'} (${res.json?.error?.code})`
      });
