    }
    setActionAlert({
      type: 'info',
      text: `Capacity updated for location ${selectedCapLocId}`
    });
    await refreshAll();
  };

  // Unauthenticated view
  if (!token || !bootstrap) {
    return (
      <main className="main-layout" style={{ maxWidth: 480, marginTop: '4rem' }}>
        <section className="card" aria-label="Sign In">
          <h1>Lab Sample Pickup &amp; Delivery System</h1>
          <h2>Sign In</h2>
          {loginError && (
            <div role="alert" className="alert-error">
              {loginError}
            </div>
          )}
          <form onSubmit={handleLogin} noValidate>
            <div className="form-field" style={{ marginBottom: '0.75rem' }}>
              <label htmlFor="login-username">Username</label>
              <input
                id="login-username"
                name="username"
                type="text"
                value={username}
                onChange={(e) => setUsername(e.target.value)}
                autoComplete="username"
              />
            </div>
            <div className="form-field" style={{ marginBottom: '1rem' }}>
              <label htmlFor="login-password">Password</label>
              <input
                id="login-password"
                name="password"
                type="password"
                value={password}
                onChange={(e) => setPassword(e.target.value)}
                autoComplete="current-password"
              />
            </div>
            <button type="submit" className="btn" style={{ width: '100%' }}>
              Sign In
            </button>
          </form>
        </section>
      </main>
    );
  }

  const user = bootstrap.user || {};
  const userRoles: string[] = user.roles || [];
  const activeRole: string = user.activeRole || '';
  const operations = bootstrap.operations || {};
  const locations: any[] = operations.locations || [];
  const connections: any[] = operations.connections || [];
  const workers: any[] = operations.workers || [];
  const routes: any[] = operations.routes || [];
  const opSamples: any[] = operations.samples || [];
  const exceptions: any[] = operations.exceptions || [];
  const delays: any[] = operations.delays || [];

  // Discover all sample type options (built-ins + any acceptedSampleTypeIds on labs)
  const sampleTypeOptions = [...BUILTIN_SAMPLE_TYPES];
  locations.forEach((loc) => {
    (loc.acceptedSampleTypeIds || []).forEach((stid: string) => {
      if (!sampleTypeOptions.some((o) => o.id === stid)) {
        sampleTypeOptions.push({
          id: stid,
          name: `Sample Type ${stid.slice(0, 8)}`,
          containerType: 'amber-vial',
          temperatureMinC: 2,
          temperatureMaxC: 8
        });
      }
    });
  });

  // Collect all visible samples for the current user
  const visibleSampleMap = new Map<string, any>();
  (bootstrap.requesterSamples || []).forEach((s: any) => visibleSampleMap.set(s.sampleId, s));
  if (activeRole === 'dispatcher' || activeRole === 'administrator') {
    opSamples.forEach((s: any) => {
      if (!visibleSampleMap.has(s.sampleId)) visibleSampleMap.set(s.sampleId, s);
    });
  }
  [...roleWork.pending, ...roleWork.inProgress, ...roleWork.completed].forEach((item: any) => {
    if (item.sampleId && !visibleSampleMap.has(item.sampleId)) {
      visibleSampleMap.set(item.sampleId, item);
    }
  });
  const visibleSamples = Array.from(visibleSampleMap.values());

  const collectionNodes = locations.filter((l) => l.functions?.collectionPoint || l.functions?.hub || l.functions?.transferPoint);
  const laboratories = locations.filter((l) => l.functions?.laboratory);

  return (
    <div>
      <header className="app-header">
        <div>
          <h1>Lab Sample Pickup &amp; Delivery System</h1>
          <div style={{ fontSize: '0.85rem', opacity: 0.9 }}>
            Signed in as: <strong>{user.fullName || user.username}</strong> ({user.username}) | Active Role:{' '}
            <strong data-testid="active-role-indicator">{activeRole || 'None selected'}</strong>
          </div>
        </div>
        <div className="header-controls">
          <label htmlFor="active-role-select">Active Role</label>
          <select
            id="active-role-select"
            aria-label="Active Role"
            value={activeRole}
            onChange={(e) => handleSelectRole(e.target.value)}
          >
            {!activeRole && <option value="">Select a role...</option>}
            {userRoles.map((r) => (
              <option key={r} value={r}>
                {r}
              </option>
            ))}
          </select>
          {userRoles.length > 1 &&
            userRoles.map((r) => (
              <button
                key={r}
                type="button"
                className={r === activeRole ? 'btn btn-success' : 'btn btn-secondary'}
                onClick={() => handleSelectRole(r)}
              >
                {r}
              </button>
            ))}
          <button type="button" className="btn btn-danger" onClick={handleSignOut}>
            Sign Out
          </button>
        </div>
      </header>

      <main className="main-layout">
        {actionAlert && (
          <div role="alert" className={actionAlert.type === 'error' ? 'alert-error' : 'alert-info'}>
            {actionAlert.text}
          </div>
        )}

        {user.roleSelectionRequired && !activeRole && (
          <section className="card" role="region" aria-label="Role Selection Required">
            <h2>Select Your Active Role</h2>
            <p>You hold multiple roles ({userRoles.join(', ')}). Please select a role to continue:</p>
            <div style={{ display: 'flex', gap: '0.5rem', flexWrap: 'wrap' }}>
              {userRoles.map((r) => (
                <button key={r} type="button" className="btn" onClick={() => handleSelectRole(r)}>
                  Work as {r}
                </button>
              ))}
            </div>
          </section>
        )}

        {/* Map View */}
        <MapView
          locations={locations}
          connections={connections}
          workers={workers}
          samples={opSamples}
          routes={routes}
        />

        {/* Requester / Dispatcher Request Creation & Serviceability Check */}
        {(activeRole === 'requester' || activeRole === 'dispatcher' || activeRole === 'administrator') && (
          <section className="card" role="region" aria-label="Collection Request Form">
            <h2>Create Collection Request &amp; Check Serviceability</h2>
            {requestFormError && (
              <div role="alert" className="alert-error">
                {requestFormError}
              </div>
            )}
            {serviceabilityResult && (
              <div role="status" className="alert-info">
                <strong>Serviceability Dry Run Result:</strong>{' '}
                {serviceabilityResult.serviceable ? 'Serviceable' : 'Unserviceable'} | Reason:{' '}
                <strong>{serviceabilityResult.reason}</strong> | Calculation Version:{' '}
                {serviceabilityResult.serviceabilityVersion}
                {serviceabilityResult.targetLaboratoryId &&
                  ` | Target Laboratory: ${serviceabilityResult.targetLaboratoryId}`}
              </div>
            )}
            <form onSubmit={handleCreateRequest} noValidate>
              <div className="form-grid">
                <div className="form-field">
                  <label htmlFor="req-origin-type">Origin Type</label>
                  <select
                    id="req-origin-type"
                    value={originType}
                    onChange={(e) => setOriginType(e.target.value)}
                  >
                    <option value="home">home</option>
                    <option value="clinic">clinic</option>
                    <option value="node">node</option>
                  </select>
                </div>
                <div className="form-field">
                  <label htmlFor="req-origin-lat">Origin Latitude</label>
                  <input
                    id="req-origin-lat"
                    type="text"
                    value={originLat}
                    onChange={(e) => setOriginLat(e.target.value)}
                  />
                </div>
                <div className="form-field">
                  <label htmlFor="req-origin-lng">Origin Longitude</label>
                  <input
                    id="req-origin-lng"
                    type="text"
                    value={originLng}
                    onChange={(e) => setOriginLng(e.target.value)}
                  />
                </div>
                <div className="form-field">
                  <label htmlFor="req-sample-type">Sample Type</label>
                  <select
                    id="req-sample-type"
                    value={sampleTypeId}
                    onChange={(e) => {
                      const val = e.target.value;
                      setSampleTypeId(val);
                      const found = sampleTypeOptions.find((o) => o.id === val);
                      if (found) {
                        setContainerType(found.containerType);
                        setTempMin(String(found.temperatureMinC));
                        setTempMax(String(found.temperatureMaxC));
                      }
                    }}
                  >
                    {sampleTypeOptions.map((st) => (
                      <option key={st.id} value={st.id}>
                        {st.name} ({st.id})
                      </option>
                    ))}
                  </select>
                </div>
                <div className="form-field">
                  <label htmlFor="req-container-type">Container Type</label>
                  <input
                    id="req-container-type"
                    type="text"
                    value={containerType}
                    onChange={(e) => setContainerType(e.target.value)}
                  />
                </div>
                <div className="form-field">
                  <label htmlFor="req-temp-min">Min Temperature (°C)</label>
                  <input
                    id="req-temp-min"
                    type="text"
                    value={tempMin}
                    onChange={(e) => setTempMin(e.target.value)}
                  />
                </div>
                <div className="form-field">
                  <label htmlFor="req-temp-max">Max Temperature (°C)</label>
                  <input
                    id="req-temp-max"
                    type="text"
                    value={tempMax}
                    onChange={(e) => setTempMax(e.target.value)}
                  />
                </div>
                <div className="form-field">
                  <label htmlFor="req-requested-at">Requested At</label>
                  <input
                    id="req-requested-at"
                    type="text"
                    value={requestedAt}
                    onChange={(e) => setRequestedAt(e.target.value)}
                  />
                </div>
                <div className="form-field">
                  <label htmlFor="req-earliest-at">Earliest Collection At</label>
                  <input
                    id="req-earliest-at"
                    type="text"
                    value={earliestAt}
                    onChange={(e) => setEarliestAt(e.target.value)}
                  />
                </div>
                <div className="form-field">
                  <label htmlFor="req-latest-at">Latest Collection At</label>
                  <input
                    id="req-latest-at"
                    type="text"
                    value={latestAt}
                    onChange={(e) => setLatestAt(e.target.value)}
                  />
                </div>
                <div className="form-field">
                  <label htmlFor="req-deadline-at">Delivery Deadline</label>
                  <input
                    id="req-deadline-at"
                    type="text"
                    value={deadlineAt}
                    onChange={(e) => setDeadlineAt(e.target.value)}
                  />
                </div>
              </div>
              <div style={{ display: 'flex', gap: '0.75rem', flexWrap: 'wrap' }}>
                <button type="button" className="btn btn-secondary" onClick={handleCheckServiceability}>
                  Check Serviceability
                </button>
                <button type="submit" className="btn">
                  Create Collection Request
                </button>
              </div>
            </form>
          </section>
        )}

        {/* Role Work View: Current Work & Past (Completed) Work */}
        {activeRole && (
          <div className="grid-2">
            <section className="card" role="region" aria-label="Current Work">
              <h2>Current Work ({roleWork.pending.length + roleWork.inProgress.length})</h2>
              <h3>Pending / Offered Work ({roleWork.pending.length})</h3>
              {roleWork.pending.length === 0 && <p>No pending work items.</p>}
              {roleWork.pending.map((item, idx) => (
                <div key={item.assignmentId || item.sampleId || item.journeyId || idx} className="work-item">
                  <div>
                    <span className="badge">{item.kind}</span>
                    <span className="badge">{item.status}</span>
                    <strong>ID:</strong> {item.assignmentId || item.sampleId || item.journeyId}
                    {item.sampleId && <span> | Sample: {item.sampleId}</span>}
                    {item.journeyId && <span> | Journey: {item.journeyId}</span>}
                  </div>
                  {item.destinationCapacity && (
                    <div style={{ fontSize: '0.85rem', marginTop: '0.35rem' }}>
                      <strong>Destination Capacity:</strong> Regular {item.destinationCapacity.availableUnits}/
                      {item.destinationCapacity.capacityUnits} available (Reserved:{' '}
                      {item.destinationCapacity.reservedUnits}) | Cooled{' '}
                      {item.destinationCapacity.cooledAvailableUnits}/
                      {item.destinationCapacity.cooledCapacityUnits} available (Reserved:{' '}
                      {item.destinationCapacity.cooledReservedUnits})
                    </div>
                  )}
                  {item.assignmentId && item.status === 'pending' && (
                    <div style={{ display: 'flex', gap: '0.5rem', marginTop: '0.5rem' }}>
                      <button
                        type="button"
                        className="btn btn-success"
                        onClick={() => handleAcceptAssignment(item.assignmentId)}
                      >
                        Accept Assignment
                      </button>
                      <button
                        type="button"
                        className="btn btn-danger"
                        onClick={() => handleDeclineAssignment(item.assignmentId)}
                      >
                        Decline Assignment
                      </button>
                    </div>
                  )}
                  {Array.isArray(item.history) && item.history.length > 0 && (
                    <ol className="timeline-list" aria-label="Status Timeline">
                      {item.history.map((h: any) => (
                        <li key={h.eventId}>
                          {h.action} ({h.role}) — {h.occurredAt}
                        </li>
                      ))}
                    </ol>
                  )}
                </div>
              ))}

              <h3>In Progress Work ({roleWork.inProgress.length})</h3>
              {roleWork.inProgress.length === 0 && <p>No in-progress work items.</p>}
              {roleWork.inProgress.map((item, idx) => (
                <div key={item.assignmentId || item.sampleId || item.journeyId || idx} className="work-item">
                  <div>
                    <span className="badge">{item.kind}</span>
                    <span className="badge badge-fresh">{item.status}</span>
                    <strong>ID:</strong> {item.assignmentId || item.sampleId || item.journeyId}
                    {item.sampleId && <span> | Sample: {item.sampleId}</span>}
                  </div>
                  {item.destinationCapacity && (
                    <div style={{ fontSize: '0.85rem', marginTop: '0.35rem' }}>
                      <strong>Destination Capacity:</strong> Regular {item.destinationCapacity.availableUnits}/
                      {item.destinationCapacity.capacityUnits} available (Reserved:{' '}
                      {item.destinationCapacity.reservedUnits}) | Cooled{' '}
                      {item.destinationCapacity.cooledAvailableUnits}/
                      {item.destinationCapacity.cooledCapacityUnits} available (Reserved:{' '}
                      {item.destinationCapacity.cooledReservedUnits})
                    </div>
                  )}

                  {item.assignmentId && (
                    <div style={{ marginTop: '0.5rem', display: 'flex', flexDirection: 'column', gap: '0.5rem' }}>
                      <div style={{ display: 'flex', gap: '0.5rem', alignItems: 'center', flexWrap: 'wrap' }}>
                        <label htmlFor={`lat-${item.assignmentId}`}>Latitude</label>
                        <input
                          id={`lat-${item.assignmentId}`}
                          aria-label="Latitude"
                          type="text"
                          style={{ width: 95 }}
                          value={workerLat}
                          onChange={(e) => setWorkerLat(e.target.value)}
                        />
                        <label htmlFor={`lng-${item.assignmentId}`}>Longitude</label>
                        <input
                          id={`lng-${item.assignmentId}`}
                          aria-label="Longitude"
                          type="text"
                          style={{ width: 95 }}
                          value={workerLng}
                          onChange={(e) => setWorkerLng(e.target.value)}
                        />
                        <button
                          type="button"
                          className="btn"
                          onClick={() => handleRecordLocation(item.assignmentId)}
                        >
                          Record Location
                        </button>
                      </div>

                      <div style={{ display: 'flex', gap: '0.5rem', flexWrap: 'wrap' }}>
                        {item.kind === 'collection' && (
                          <button
                            type="button"
                            className="btn btn-success"
                            onClick={() => handleCollectAndSeal(item)}
                          >
                            Collect and Seal Sample
                          </button>
                        )}
                        {item.kind === 'transport' && (
                          <>
                            <button
                              type="button"
                              className="btn btn-secondary"
                              onClick={() => handleUpdateProgress(item.assignmentId, 'picked_up')}
                            >
                              Picked Up
                            </button>
                            <button
                              type="button"
                              className="btn btn-secondary"
                              onClick={() => handleUpdateProgress(item.assignmentId, 'in_transit')}
                            >
                              In Transit
                            </button>
                            <button
                              type="button"
                              className="btn btn-secondary"
                              onClick={() => handleUpdateProgress(item.assignmentId, 'arrived')}
                            >
                              Arrived
                            </button>
                          </>
                        )}
                        {item.kind === 'laboratory' && (
                          <>
                            <button
                              type="button"
                              className="btn btn-success"
                              onClick={() => handleConfirmReceipt(item)}
                            >
                              Confirm Laboratory Receipt
                            </button>
                            <button
                              type="button"
                              className="btn btn-danger"
                              onClick={() => handleRecordLabException(item)}
                            >
                              Record Laboratory Exception
                            </button>
                          </>
                        )}
                      </div>
                    </div>
                  )}

                  {Array.isArray(item.history) && item.history.length > 0 && (
                    <ol className="timeline-list" aria-label="Status Timeline">
                      {item.history.map((h: any) => (
                        <li key={h.eventId}>
                          {h.action} ({h.role}) — {h.occurredAt}
                        </li>
                      ))}
                    </ol>
                  )}
                </div>
              ))}
            </section>

            <section className="card" role="region" aria-label="Past Work">
              <h2>Past Work / Completed Work ({roleWork.completed.length})</h2>
              {roleWork.completed.length === 0 && <p>No completed work items yet.</p>}
              {roleWork.completed.map((item, idx) => (
                <div key={item.assignmentId || item.sampleId || item.journeyId || idx} className="work-item">
                  <div>
                    <span className="badge">{item.kind}</span>
                    <span className="badge">{item.status}</span>
                    <strong>ID:</strong> {item.assignmentId || item.sampleId || item.journeyId}
                    {item.sampleId && <span> | Sample: {item.sampleId}</span>}
                  </div>
                  {Array.isArray(item.history) && item.history.length > 0 && (
                    <ol className="timeline-list" aria-label="Status Timeline">
                      {item.history.map((h: any) => (
                        <li key={h.eventId}>
                          {h.action} ({h.role}) — {h.occurredAt}
                        </li>
                      ))}
                    </ol>
                  )}
                </div>
              ))}
            </section>
          </div>
        )}

        {/* Sample Details, Custodian, Freshness, Progress, Exception Flag & Status Timeline */}
        <section className="card" role="region" aria-label="Samples and Lifecycle Tracking">
          <h2>Samples &amp; Lifecycle Tracking ({visibleSamples.length})</h2>
          {visibleSamples.length === 0 && <p>No samples to display for current role.</p>}
          {visibleSamples.map((samp) => {
            const sid = samp.sampleId;
            const detail = sampleDetails[sid] || {};
            const st = detail.state || samp;
            const lc = detail.lifecycle || samp;
            const journey = detail.journey;

            const isStale = Boolean(lc.locationStale ?? st.locationStale ?? samp.locationStale);
            const loc = lc.latestLocation || st.latestLocation || samp.latestLocation || st.origin || samp.origin;
            const locTime = lc.locationRecordedAt || st.locationRecordedAt || samp.locationRecordedAt || st.requestedAt;
            const custodian = lc.currentHolderId || samp.currentHolderId || 'Pending Collection';
            const statusStr = lc.status || st.state?.status || samp.status;
            const exc = lc.exception || samp.exception;
            const timeline: any[] = lc.timeline || st.timeline || samp.history || [];
            const completedLegs: string[] = lc.completedLegIds || [];
            const totalLegs = journey?.legs?.length || journey?.assignments?.length || 1;
            const stops: any[] = journey?.orderedStops || [];

            return (
              <article key={sid} className="work-item" aria-label={`Sample ${sid}`}>
                <div style={{ display: 'flex', justifyContent: 'space-between', flexWrap: 'wrap', gap: '0.5rem' }}>
                  <div>
                    <strong>Sample ID:</strong> {sid} | <strong>Status:</strong>{' '}
                    <span className="badge">{statusStr}</span> | <strong>Serviceability:</strong>{' '}
                    <span className="badge">{st.serviceability || samp.serviceability || 'serviceable'}</span>
                  </div>
                  <div>
                    <span className={isStale ? 'badge badge-stale' : 'badge badge-fresh'}>
                      {isStale ? 'Stale Location' : 'Fresh Location'}
                    </span>
                    {(statusStr === 'exception' || exc) && (
                      <span role="alert" className="badge badge-exception">
                        Exception Flag: {exc?.reason || 'exception'}
                      </span>
                    )}
                  </div>
                </div>

                <div style={{ marginTop: '0.5rem', fontSize: '0.9rem' }}>
                  <div>
                    <strong>Current Custodian:</strong> {custodian}
                  </div>
                  <div>
                    <strong>Current Location:</strong>{' '}
                    {loc ? `${loc.latitude}, ${loc.longitude}` : 'Unknown'} |{' '}
                    <strong>Last Updated:</strong> {locTime || 'N/A'} |{' '}
                    <strong>Location Freshness:</strong> {isStale ? 'Stale (locationStale: true)' : 'Fresh (locationStale: false)'}
                  </div>
                  <div>
                    <strong>Route Progress:</strong> {completedLegs.length} of {totalLegs} legs completed
                    {journey?.routeMode ? ` (Mode: ${journey.routeMode}, Plan v${journey.planVersion})` : ''}
                  </div>
                  {stops.length > 0 && (
                    <div>
                      <strong>Route Stops:</strong>{' '}
                      {stops.map((stop: any) => `${stop.sequence}. ${stop.stopType} (${stop.locationId})`).join(' -> ')}
                    </div>
                  )}
                </div>

                <div style={{ marginTop: '0.5rem' }}>
                  <strong>Ordered Status History ({timeline.length} events):</strong>
                  <ol className="timeline-list" aria-label={`Status History for ${sid}`}>
                    {timeline.map((entry: any, idx: number) => (
                      <li key={entry.eventId || idx}>
                        <strong>{entry.action}</strong> — Role: {entry.role} — Time: {entry.occurredAt}
                      </li>
                    ))}
                  </ol>
                </div>
              </article>
            );
          })}
        </section>

        {/* Laboratory & Node Capacity View */}
        {(activeRole === 'laboratory_team' ||
          activeRole === 'node_handler' ||
          activeRole === 'dispatcher' ||
          activeRole === 'administrator') && (
          <section className="card" role="region" aria-label="Laboratory and Node Capacity">
            <h2>Laboratory &amp; Node Capacity</h2>
            {locations.map((loc) => {
              const cap = loc.capacity || {};
              return (
                <div key={loc.locationId || loc.id} className="work-item">
                  <strong>{loc.name}</strong> ({loc.locationId}) —{' '}
                  {loc.functions?.laboratory ? 'Laboratory' : 'Collection/Transfer Node'}
                  <div>
                    <strong>Regular Capacity:</strong> Configured: {cap.capacityUnits ?? 0} | Reserved:{' '}
                    {cap.reservedUnits ?? 0} | Available: {cap.availableUnits ?? 0}
                  </div>
                  <div>
                    <strong>Cooled Capacity:</strong> Configured: {cap.cooledCapacityUnits ?? 0} | Reserved:{' '}
                    {cap.cooledReservedUnits ?? 0} | Available: {cap.cooledAvailableUnits ?? 0}
                  </div>
                </div>
              );
            })}
            <form onSubmit={handleConfigureCapacity} style={{ marginTop: '0.75rem' }}>
              <div className="form-grid">
                <div className="form-field">
                  <label htmlFor="cap-location-select">Facility Location</label>
                  <select
                    id="cap-location-select"
                    value={selectedCapLocId}
                    onChange={(e) => setSelectedCapLocId(e.target.value)}
                  >
                    {locations.map((l) => (
                      <option key={l.locationId || l.id} value={l.locationId || l.id}>
                        {l.name} ({l.locationId || l.id})
                      </option>
                    ))}
                  </select>
                </div>
                <div className="form-field">
                  <label htmlFor="cap-regular-input">Regular Capacity Units</label>
                  <input
                    id="cap-regular-input"
                    type="number"
                    value={capRegularUnits}
                    onChange={(e) => setCapRegularUnits(e.target.value)}
                  />
                </div>
                <div className="form-field">
                  <label htmlFor="cap-cooled-input">Cooled Capacity Units</label>
                  <input
                    id="cap-cooled-input"
                    type="number"
                    value={capCooledUnits}
                    onChange={(e) => setCapCooledUnits(e.target.value)}
                  />
                </div>
              </div>
              <button type="submit" className="btn">
                Update Capacity
              </button>
            </form>
          </section>
        )}

        {/* Dispatcher & Administrator Operations Monitor Dashboard */}
        {(activeRole === 'dispatcher' || activeRole === 'administrator') && (
          <section className="card" role="region" aria-label="Operations Monitor Dashboard">
            <h2>Operations Monitor Dashboard</h2>
            <div className="grid-2">
              <div className="work-item" role="region" aria-label="Monitor Samples">
                <h3>Samples ({opSamples.length})</h3>
                {opSamples.map((s) => (
                  <div key={s.sampleId}>
                    Sample {s.sampleId}: Status <strong>{s.status}</strong> | Holder:{' '}
                    {s.currentHolderId || 'None'} | Stale: {s.locationStale ? 'Yes' : 'No'}
                  </div>
                ))}
              </div>

              <div className="work-item" role="region" aria-label="Monitor Workers">
                <h3>Workers ({workers.length})</h3>
                {workers.map((w) => (
                  <div key={w.workerId}>
                    {w.fullName || w.workerId} ({(w.roles || []).join(', ')}):{' '}
                    <strong>{w.status}</strong> | Assignments: {w.assignmentCount} | Capacity:{' '}
                    {w.capacityUnits}
                  </div>
                ))}
              </div>

              <div className="work-item" role="region" aria-label="Monitor Collection Nodes">
                <h3>Collection Nodes ({collectionNodes.length})</h3>
                {collectionNodes.map((n) => (
                  <div key={n.locationId}>
                    {n.name} ({n.locationId}): {n.active ? 'Active' : 'Inactive'} | Coverage:{' '}
                    {n.coverageKm} km | Available Capacity: {n.capacity?.availableUnits ?? 0}
                  </div>
                ))}
              </div>

              <div className="work-item" role="region" aria-label="Monitor Laboratories">
                <h3>Laboratories ({laboratories.length})</h3>
                {laboratories.map((lab) => (
                  <div key={lab.locationId}>
                    {lab.name} ({lab.locationId}): {lab.active ? 'Active' : 'Inactive'} | Available
                    Capacity: {lab.capacity?.availableUnits ?? 0} | Cooled:{' '}
                    {lab.capacity?.cooledAvailableUnits ?? 0}
                  </div>
                ))}
              </div>

              <div className="work-item" role="region" aria-label="Monitor Routes">
                <h3>Routes ({routes.length} active plans, {connections.length} connections)</h3>
                {routes.map((rt) => (
                  <div key={rt.journeyId}>
                    Journey {rt.journeyId}: Mode <strong>{rt.routeMode}</strong> | Status:{' '}
                    {rt.status} | Plan v{rt.planVersion}
                  </div>
                ))}
                {connections.map((c) => (
                  <div key={c.connectionId}>
                    Connection {c.connectionId}: {c.fromLocationId} -&gt; {c.toLocationId} ({c.travelMinutes}m)
                  </div>
                ))}
              </div>

              <div className="work-item" role="region" aria-label="Monitor Exceptions">
                <h3>Exceptions ({exceptions.length}) &amp; Delays ({delays.length})</h3>
                {exceptions.length === 0 && delays.length === 0 && <p>No active exceptions or delays.</p>}
                {exceptions.map((ex, i) => (
                  <div key={ex.exceptionId || i} className="badge badge-exception">
                    Exception on Sample {ex.sampleId}: {ex.reason}
                  </div>
                ))}
                {delays.map((d, i) => (
                  <div key={d.sampleId || i} className="badge badge-stale">
                    Delayed/Expired Sample {d.sampleId}: {d.status}
                  </div>
                ))}
              </div>
            </div>
          </section>
        )}

        {/* Dispatcher & Administrator Audit Trail View */}
        {(activeRole === 'dispatcher' || activeRole === 'administrator') && (
          <section className="card" role="region" aria-label="Audit Trail">
            <h2>Audit Trail &amp; History Search ({auditTotal} records)</h2>
            <form
              onSubmit={(e) => {
                e.preventDefault();
                loadAuditLogs(auditQuery);
              }}
              style={{ display: 'flex', gap: '0.5rem', marginBottom: '0.75rem', flexWrap: 'wrap' }}
            >
              <label htmlFor="audit-search-input" style={{ alignSelf: 'center', fontWeight: 600 }}>
                Search Audit Logs
              </label>
              <input
                id="audit-search-input"
                aria-label="Search Audit Logs"
                type="text"
                placeholder="Search action, user, role, sample or request ID..."
                style={{ flex: 1, minWidth: 240, padding: '0.4rem 0.6rem' }}
                value={auditQuery}
                onChange={(e) => {
                  setAuditQuery(e.target.value);
                  loadAuditLogs(e.target.value);
                }}
              />
              <button type="submit" className="btn">
                Search Audit
              </button>
            </form>
            <div style={{ maxHeight: 320, overflowY: 'auto' }}>
              <ol className="timeline-list" aria-label="Audit Results">
                {auditEntries.map((ae) => (
                  <li key={ae.auditId}>
                    <strong>{ae.action}</strong> | Actor: {ae.actorId || 'anonymous'} | Role:{' '}
                    {ae.role || 'none'} | Entity: {ae.entityType}:{ae.entityId} | Time:{' '}
                    {ae.occurredAt} | Outcome: {ae.success ? 'Success' : 'Denied'}
                  </li>
                ))}
              </ol>
            </div>
          </section>
        )}
      </main>
    </div>
  );
};
