func TestPresealedBatchReplanAndDurability(t *testing.T) {
	ts, _, cleanup := setupTestServer(t)
	defer cleanup()

	_, loginResp := doReq(t, ts, http.MethodPost, "/api/authenticate-user", "", map[string]interface{}{
		"username": "initadmin",
		"password": "initpass123",
	})
	adminToken := loginResp["data"].(map[string]interface{})["sessionToken"].(string)

	// Create CP, HubA, HubB, Lab
	_, cpResp := doReq(t, ts, http.MethodPost, "/api/create-location", adminToken, map[string]interface{}{
		"name": "CP1", "coordinate": map[string]interface{}{"latitude": 12.9716, "longitude": 77.5946},
		"coverageKm": 5.0, "handlingMinutes": 5, "active": true,
		"functions": []string{"collection_point", "transfer_point"},
	})
	cpID := cpResp["data"].(map[string]interface{})["locationId"].(string)

	_, hubAResp := doReq(t, ts, http.MethodPost, "/api/create-location", adminToken, map[string]interface{}{
		"name": "HubA", "coordinate": map[string]interface{}{"latitude": 12.9800, "longitude": 77.6000},
		"coverageKm": 5.0, "handlingMinutes": 5, "active": true,
		"functions": []string{"transfer_point", "hub"},
	})
	hubAID := hubAResp["data"].(map[string]interface{})["locationId"].(string)

	_, hubBResp := doReq(t, ts, http.MethodPost, "/api/create-location", adminToken, map[string]interface{}{
		"name": "HubB", "coordinate": map[string]interface{}{"latitude": 12.9850, "longitude": 77.6050},
		"coverageKm": 5.0, "handlingMinutes": 5, "active": true,
		"functions": []string{"transfer_point", "hub"},
	})
	hubBID := hubBResp["data"].(map[string]interface{})["locationId"].(string)

	_, labResp := doReq(t, ts, http.MethodPost, "/api/create-location", adminToken, map[string]interface{}{
		"name": "LabMain", "coordinate": map[string]interface{}{"latitude": 12.9900, "longitude": 77.6100},
		"coverageKm": 5.0, "handlingMinutes": 5, "active": true,
		"functions": []string{"laboratory"},
	})
	labID := labResp["data"].(map[string]interface{})["locationId"].(string)

	// Connections: CP1->HubA->LabMain (fast) and CP1->HubB->LabMain (backup)
	for _, c := range []map[string]interface{}{
		{"fromLocationId": cpID, "toLocationId": hubAID, "travelMinutes": 10, "costUnits": 2, "cooled": true, "active": true},
		{"fromLocationId": hubAID, "toLocationId": labID, "travelMinutes": 10, "costUnits": 2, "cooled": true, "active": true},
		{"fromLocationId": cpID, "toLocationId": hubBID, "travelMinutes": 20, "costUnits": 5, "cooled": true, "active": true},
		{"fromLocationId": hubBID, "toLocationId": labID, "travelMinutes": 20, "costUnits": 5, "cooled": true, "active": true},
	} {
		st, _ := doReq(t, ts, http.MethodPost, "/api/create-connection", adminToken, c)
		require.Equal(t, http.StatusCreated, st)
	}

	// Accept all 4 default sample types at LabMain
	amberID := "00000000-0000-4000-8000-000000000001"
	indigoID := "00000000-0000-4000-8000-000000000002"
	frostID := "00000000-0000-4000-8000-000000000003"
	pulseID := "00000000-0000-4000-8000-000000000004"
	for _, stID := range []string{amberID, indigoID, frostID, pulseID} {
		st, _ := doReq(t, ts, http.MethodPost, "/api/configure-laboratory-acceptance", adminToken, map[string]interface{}{
			"laboratoryId": labID, "sampleTypeId": stID, "accepts": true,
		})
		require.Equal(t, http.StatusOK, st)
	}

	// Create node handler at HubA and courier
	_, nhResp := doReq(t, ts, http.MethodPost, "/api/create-user", adminToken, map[string]interface{}{
		"username": "nh_huba", "initialPassword": "password123", "roles": []string{"node_handler"},
		"assignedLocationId": hubAID, "active": true,
	})
	nhID := nhResp["data"].(map[string]interface{})["userId"].(string)
	_, nhLogin := doReq(t, ts, http.MethodPost, "/api/authenticate-user", "", map[string]interface{}{
		"username": "nh_huba", "password": "password123",
	})
	nhToken := nhLogin["data"].(map[string]interface{})["sessionToken"].(string)

	_, _ = doReq(t, ts, http.MethodPost, "/api/create-user", adminToken, map[string]interface{}{
		"username": "courier_all", "initialPassword": "password123", "roles": []string{"delivery_partner"},
		"active": true,
	})
	_, _ = doReq(t, ts, http.MethodPost, "/api/create-user", adminToken, map[string]interface{}{
		"username": "lab_main", "initialPassword": "password123", "roles": []string{"laboratory_team"},
		"assignedLocationId": labID, "active": true,
	})

	baseTime := time.Now().UTC().Truncate(time.Second)

	// 1. Pre-sealed sample with home origin must be rejected
	st, errPre := doReq(t, ts, http.MethodPost, "/api/register-presealed-sample", nhToken, map[string]interface{}{
		"holderId":              nhID,
		"origin":                map[string]interface{}{"latitude": 12.9800, "longitude": 77.6000},
		"originType":            "home",
		"originLocationId":      hubAID,
		"sampleTypeId":          amberID,
		"containerType":         "amber-vial",
		"temperatureMinC":       2.0,
		"temperatureMaxC":       8.0,
		"observedTemperatureC":  4.0,
		"sealedAt":              baseTime.Format(time.RFC3339),
		"deliveryDeadline":      baseTime.Add(120 * time.Minute).Format(time.RFC3339),
		"idempotencyKey":        "pre-home-bad",
	})
	require.Equal(t, http.StatusBadRequest, st)
	require.Equal(t, "invalid_presealed_origin", errPre["code"])

	// 2. Pre-sealed sample at HubA creates only HubA -> LabMain leg (no collection assignment, no CP1->HubA leg)
	st, okPre := doReq(t, ts, http.MethodPost, "/api/register-presealed-sample", nhToken, map[string]interface{}{
		"holderId":              nhID,
		"origin":                map[string]interface{}{"latitude": 12.9800, "longitude": 77.6000},
		"originType":            "node",
		"originLocationId":      hubAID,
		"sampleTypeId":          amberID,
		"containerType":         "amber-vial",
		"temperatureMinC":       2.0,
		"temperatureMaxC":       8.0,
		"observedTemperatureC":  4.0,
		"sealedAt":              baseTime.Format(time.RFC3339),
		"deliveryDeadline":      baseTime.Add(120 * time.Minute).Format(time.RFC3339),
		"idempotencyKey":        "pre-node-ok",
	})
	require.Equal(t, http.StatusCreated, st)
	preSampleID := okPre["data"].(map[string]interface{})["sampleId"].(string)
	preJourneyID := okPre["data"].(map[string]interface{})["journeyId"].(string)
	require.Equal(t, nhID, okPre["data"].(map[string]interface{})["currentHolderId"])

	st, prePlan := doReq(t, ts, http.MethodPost, "/api/read-journey-plan", adminToken, map[string]interface{}{
		"journeyId": preJourneyID,
	})
	require.Equal(t, http.StatusOK, st)
	require.Empty(t, prePlan["data"].(map[string]interface{})["collectionAssignmentIds"].([]interface{}))
	require.Len(t, prePlan["data"].(map[string]interface{})["legs"].([]interface{}), 1)

	// 3. Register a second pre-sealed Indigo sample and verify Amber + Indigo batching is rejected
	st, indigoPre := doReq(t, ts, http.MethodPost, "/api/register-presealed-sample", nhToken, map[string]interface{}{
		"holderId":              nhID,
		"origin":                map[string]interface{}{"latitude": 12.9800, "longitude": 77.6000},
		"originType":            "node",
		"originLocationId":      hubAID,
		"sampleTypeId":          indigoID,
		"containerType":         "indigo-vial",
		"temperatureMinC":       2.0,
		"temperatureMaxC":       8.0,
		"observedTemperatureC":  4.0,
		"sealedAt":              baseTime.Format(time.RFC3339),
		"deliveryDeadline":      baseTime.Add(120 * time.Minute).Format(time.RFC3339),
		"idempotencyKey":        "pre-indigo",
	})
	require.Equal(t, http.StatusCreated, st)
	indigoSampleID := indigoPre["data"].(map[string]interface{})["sampleId"].(string)

	st, batchIncompat := doReq(t, ts, http.MethodPost, "/api/plan-batch-journey", adminToken, map[string]interface{}{
		"sampleIds":       []string{preSampleID, indigoSampleID},
		"sharedContainer": true,
		"plannedAt":       baseTime.Add(2 * time.Minute).Format(time.RFC3339),
		"idempotencyKey":  "batch-amber-indigo",
	})
	require.Equal(t, http.StatusConflict, st)
	require.Equal(t, "incompatible_samples", batchIncompat["code"])

	// 4. Out-of-range temperature checkpoint marks sample as exception
	nodeAssignID := prePlan["data"].(map[string]interface{})["nodeAssignmentIds"].([]interface{})[0].(string)
	_, _ = doReq(t, ts, http.MethodPost, "/api/accept-assignment", nhToken, map[string]interface{}{
		"assignmentId": nodeAssignID, "idempotencyKey": "acc-nh-pre",
	})
	st, badTempResp := doReq(t, ts, http.MethodPost, "/api/record-handling-checkpoint", nhToken, map[string]interface{}{
		"sampleId":             preSampleID,
		"assignmentId":         nodeAssignID,
		"locationId":           hubAID,
		"containerType":        "amber-vial",
		"observedTemperatureC": 19.5, // outside [2, 8]
		"recordedAt":           baseTime.Add(5 * time.Minute).Format(time.RFC3339),
		"idempotencyKey":       "bad-temp-cp",
	})
	require.Equal(t, http.StatusCreated, st)
	require.Equal(t, false, badTempResp["data"].(map[string]interface{})["compliant"])

	st, lcCheck := doReq(t, ts, http.MethodPost, "/api/read-sample-lifecycle", adminToken, map[string]interface{}{
		"sampleId": preSampleID,
	})
	require.Equal(t, http.StatusOK, st)
	require.Equal(t, "exception", lcCheck["data"].(map[string]interface{})["status"])
