{"summary":"Create Playwright E2E test suite covering all 16 UI contract scenarios","file_text":"import { test, expect } from '@playwright/test';

const API = 'http://127.0.0.1:8080/api';

async function apiPost(path: string, token: string, body: Record<string, unknown>) {
  const res = await fetch(`${API}${path}`, {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      ...(token ? { Authorization: `Bearer ${token}` } : {})
    },
    body: JSON.stringify(body)
  });
  const json = await res.json();
  return { status: res.status, body: json };
}

test.describe('Lab Sample Pickup & Delivery UI Contract Scenarios', () => {
  test('All 16 UI contract scenarios with zero console/page/5xx errors', async ({ page }) => {
    const consoleErrors: string[] = [];
    const pageErrors: string[] = [];
    const server5xx: string[] = [];
    const externalTileUrls: string[] = [];

    page.on('console', (msg) => {
      if (msg.type() === 'error') {
        consoleErrors.push(msg.text());
      }
    });
    page.on('pageerror', (err) => {
      pageErrors.push(err.message);
    });
    page.on('request', (req) => {
      const url = req.url();
      if (!url.startsWith('http://127.0.0.1:8080') && !url.startsWith('data:') && !url.startsWith('blob:')) {
        externalTileUrls.push(url);
      }
    });
    page.on('response', (res) => {
      if (res.status() >= 500) {
        server5xx.push(`${res.status()} ${res.url()}`);
      }
    });

    // 1. Seed network via API using initial admin account
    const adminLogin = await apiPost('/auth/login', '', { username: 'admin', password: 'adminpassword123' });
    expect(adminLogin.status).toBe(200);
    const adminToken = adminLogin.body.data.token as string;
    await apiPost('/auth/select-role', adminToken, { role: 'administrator' });

    const colNodeRes = await apiPost('/create-network-location', adminToken, {
      name: 'Indiranagar Clinic Node',
      coordinate: { latitude: 12.9716, longitude: 77.5946 },
      coverageKm: 5,
      handlingMinutes: 5,
      active: true,
      functions: { collectionPoint: true, transferHub: true, laboratory: false },
      capacityUnits: 20,
      cooledCapacityUnits: 10,
      idempotencyKey: 'e2e-loc-1'
    });
    const colNodeId = colNodeRes.body.data.locationId as string;

    const labNodeRes = await apiPost('/create-network-location', adminToken, {
      name: 'Central Reference Lab',
      coordinate: { latitude: 12.9916, longitude: 77.6146 },
