    await expect(page.getByRole('region', { name: 'Workers Category' })).toBeVisible();
    await expect(page.getByRole('region', { name: 'Collection Nodes Category' })).toBeVisible();
    await expect(page.getByRole('region', { name: 'Laboratories Category' })).toBeVisible();
