    await page.getByLabel('Username').fill('collector1');
    await page.getByLabel('Password').fill('password123');
    await page.getByRole('button', { name: 'Sign In' }).click();

    await expect(page.getByRole('region', { name: 'Current Work' })).toBeVisible();
    await expect(page.getByRole('region', { name: 'Past (Completed) Work' })).toBeVisible();

    // Scenario 15: accept_assignment_writes_through
    await page.getByRole('button', { name: 'Accept Assignment' }).click();
    await expect(page.getByRole('region', { name: 'Current Work' })).toContainText('accepted');

    // Scenario 16: worker_records_location_writes_through
    await page.getByRole('button', { name: 'Record Location' }).click();
    await expect(page.getByRole('status')).toContainText(/Location recorded/i);

    // Collect & seal sample, then record an out-of-range temperature checkpoint to surface exception flag (Scenario 8)
    await page.getByRole('button', { name: 'Record Collected & Sealed' }).click();
    await expect(page.getByRole('status')).toContainText(/Sample collected and sealed/i);

    await page.getByLabel('Observed Temp (°C)').fill('22');
    await page.getByRole('button', { name: 'Record Checkpoint' }).click();

    // Scenario 8: sample_view_surfaces_exception_flag
    await expect(page.getByLabel('Exception Flag')).toBeVisible();

    await page.getByRole('button', { name: 'Sign Out' }).click();

    // Scenario 14: lab_worker_views_own_capacity
    await page.getByLabel('Username').fill('lab1');
    await page.getByLabel('Password').fill('password123');
    await page.getByRole('button', { name: 'Sign In' }).click();
    const capRegion = page.getByRole('region', { name: 'Assigned Facility Capacity' });
    await expect(capRegion).toBeVisible();
    await expect(capRegion).toContainText('Regular Capacity');
    await expect(capRegion).toContainText('Cooled Capacity');

    expect(consoleErrors).toEqual([]);
    expect(pageErrors).toEqual([]);
    expect(server5xx).toEqual([]);
    expect(externalTileUrls).toEqual([]);
  });
});
