{"command":"create","file_text":"import { test, expect } from '@playwright/test';

const API = 'http://127.0.0.1:8080/api';

async function apiPost(path: string, token: string, body: Record<string, unknown>) {
  const res = await fetch(`${API}${path}`, {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      ...(token ? { Authorization: `Bearer ${token}` } : {})
    },
    body: JSON.stringify(body)
  });
  const json = await res.json();
  return { status: res.status, body: json };
}

test.describe('Lab Sample Pickup & Delivery UI Contract Scenarios', () => {
  test('All 16 UI contract scenarios with zero console/page/5xx errors', async ({ page }) => {
    const consoleErrors: string[] = [];
    const pageErrors: string[] = [];
    const server5xx: string[] = [];
    const externalTileUrls: string[] = [];

    page.on('console', (msg) => {
      if (msg.type() === 'error') {
        consoleErrors.push(msg.text());
      }
    });
    page.on('pageerror', (err) => {
      pageErrors.push(err.message);
    });
    page.on('request', (req) => {
      const url = req.url();
      if (!url.startsWith('http://127.0.0.1:8080') && !url.startsWith('data:') && !url.startsWith('blob:')) {
        externalTileUrls.push(url);
      }
    });
    page.on('response', (res) => {
      if (res.status() >= 500) {
        server5xx.push(`${res.status()} ${res.url()}`);
      }
    });

    // 1. Seed network via API using initial admin account
    const adminLogin = await apiPost('/authenticate-user', '', { username: 'admin', password: 'adminpassword123' });
    expect(adminLogin.status).toBe(200);
    const adminToken = adminLogin.body.data.sessionToken as string;
    await apiPost('/select-active-role', adminToken, { role: 'administrator' });

    const colNodeRes = await apiPost('/create-location', adminToken, {
      name: 'Indiranagar Clinic Node',
      coordinate: { latitude: 12.9716, longitude: 77.5946 },
      coverageKm: 5,
      handlingMinutes: 5,
      active: true,
      functions: ['collection_point', 'transfer_point']
    });
    expect(colNodeRes.status).toBe(201);
    const colNodeId = colNodeRes.body.data.locationId as string;

    const labNodeRes = await apiPost('/create-location', adminToken, {
      name: 'Central Reference Lab',
      coordinate: { latitude: 12.9916, longitude: 77.6146 },
      coverageKm: 5,
      handlingMinutes: 5,
      active: true,
      functions: ['laboratory']
    });
    expect(labNodeRes.status).toBe(201);
    const labNodeId = labNodeRes.body.data.locationId as string;

    const connRes = await apiPost('/create-connection', adminToken, {
      fromLocationId: colNodeId,
      toLocationId: labNodeId,
      travelMinutes: 15,
      costUnits: 10,
      cooled: true,
      active: true
    });
    expect(connRes.status).toBe(201);
    const connId = connRes.body.data.connectionId as string;

    for (const resId of [colNodeId, labNodeId, connId]) {
      const capRes = await apiPost('/configure-capacity', adminToken, {
        resourceId: resId,
        capacityUnits: 20,
        cooledCapacityUnits: 10
      });
      expect(capRes.status).toBe(200);
    }

    const amberId = '00000000-0000-4000-8000-000000000001';
    const accRes = await apiPost('/configure-laboratory-acceptance', adminToken, {
      laboratoryId: labNodeId,
      sampleTypeId: amberId,
      accepts: true
    });
    expect(accRes.status).toBe(200);

    // Create multi-role user & specialized workers
    await apiPost('/create-user', adminToken, {
      username: 'req1',
      initialPassword: 'password123',
      fullName: 'Requester Dispatcher',
      roles: ['requester', 'dispatcher'],
      active: true
    });
    await apiPost('/create-user', adminToken, {
      username: 'collector1',
      initialPassword: 'password123',
      fullName: 'Certified Collector',
      roles: ['collection_professional'],
      qualifications: ['collector-amber', 'Amber'],
      active: true
    });
    await apiPost('/create-user', adminToken, {
      username: 'courier1',
      initialPassword: 'password123',
      fullName: 'Relay Courier',
      roles: ['delivery_partner'],
      active: true
    });
    await apiPost('/create-user', adminToken, {
      username: 'lab1',
      initialPassword: 'password123',
      fullName: 'Lab Operator',
      roles: ['laboratory_team'],
      assignedLocationId: labNodeId,
      active: true
    });

    // Scenario 1: login_rejects_invalid_credentials
    await page.goto('/');
    await page.getByLabel('Username').fill('admin');
    await page.getByLabel('Password').fill('wrong-password');
    await page.getByRole('button', { name: 'Sign In' }).click();
    await expect(page.getByRole('alert')).toContainText(/invalid/i);

    // Sign in as multi-role user req1 (requester + dispatcher)
    await page.getByLabel('Username').fill('req1');
    await page.getByLabel('Password').fill('password123');
    await page.getByRole('button', { name: 'Sign In' }).click();

    // Scenario 2: role_switch_control_lists_and_applies_role
    const roleSelect = page.getByLabel('Active Role');
    await expect(roleSelect).toBeVisible();
    await roleSelect.selectOption('requester');
    await expect(page.getByRole('region', { name: 'Collection Request Form' })).toBeVisible();

    // Scenario 7: map_renders_local_tiles_only
    const mapCanvas = page.locator('canvas.maplibregl-canvas');
    await expect(mapCanvas).toBeVisible();
    const box = await mapCanvas.boundingBox();
    expect(box?.width).toBeGreaterThan(200);
    expect(box?.height).toBeGreaterThan(200);
    expect(externalTileUrls).toEqual([]);

    // Scenario 13: serviceability_dry_run_creates_nothing
    await page.getByRole('button', { name: 'Check Serviceability' }).click();
    await expect(page.getByRole('status')).toContainText(/Serviceable/i);
    await expect(page.getByRole('region', { name: 'Samples and Lifecycle Tracking' })).toContainText(
      'No samples to display for current role.'
    );

    // Scenario 12: request_form_surfaces_validation_error
    const origDeadline = await page.getByLabel('Delivery Deadline').inputValue();
    await page.getByLabel('Delivery Deadline').fill('2020-01-01T00:00:00Z');
    await page.getByRole('button', { name: 'Create Collection Request' }).click();
    await expect(page.getByRole('alert')).toBeVisible();

    // Create valid collection request
    await page.getByLabel('Delivery Deadline').fill(origDeadline);
    await page.getByRole('button', { name: 'Create Collection Request' }).click();

    // Scenario 4, 5, 6: sample_view_shows_ordered_status_history, sample_freshness_visible_to_owner, sample_view_shows_location_custodian_progress
    const sampleSection = page.getByRole('region', { name: 'Samples and Lifecycle Tracking' });
    await expect(sampleSection).toBeVisible();
    await expect(sampleSection).toContainText(/Fresh Location|Stale Location/);
    await expect(sampleSection).toContainText('Current Custodian:');
    await expect(sampleSection).toContainText('Route Progress:');
    await expect(sampleSection).toContainText('Current Location:');
    await expect(sampleSection).toContainText('Ordered Status History');

    // Scenario 9 & 10: Switch role to dispatcher -> monitor_dashboard_renders_categories & audit_view_renders_and_searches
    await roleSelect.selectOption('dispatcher');
    await expect(page.getByRole('region', { name: 'Operations Monitor Dashboard' })).toBeVisible();
    await expect(page.getByRole('region', { name: 'Monitor Samples' })).toBeVisible();
    await expect(page.getByRole('region', { name: 'Monitor Workers' })).toBeVisible();
    await expect(page.getByRole('region', { name: 'Monitor Collection Nodes' })).toBeVisible();
    await expect(page.getByRole('region', { name: 'Monitor Laboratories' })).toBeVisible();
    await expect(page.getByRole('region', { name: 'Monitor Routes' })).toBeVisible();
    await expect(page.getByRole('region', { name: 'Monitor Exceptions' })).toBeVisible();

    const auditRegion = page.getByRole('region', { name: 'Audit Trail' });
    await expect(auditRegion).toBeVisible();
    await page.getByLabel('Search Audit Logs').fill('create_collection_request');
    await page.getByRole('button', { name: 'Search Audit' }).click();
    await expect(page.getByRole('list', { name: 'Audit Results' })).toContainText('create_collection_request');

    // Scenario 11: sign_out_ends_authenticated_session
    await page.getByRole('button', { name: 'Sign Out' }).click();
    await expect(page.getByRole('button', { name: 'Sign In' })).toBeVisible();

    // Scenario 3, 15, 16: collector1 logs in, sees Current Work and Past Work, accepts assignment, records location
    await page.getByLabel('Username').fill('collector1');
    await page.getByLabel('Password').fill('password123');
    await page.getByRole('button', { name: 'Sign In' }).click();

    await expect(page.getByRole('region', { name: 'Current Work' })).toBeVisible();
    await expect(page.getByRole('region', { name: 'Past Work' })).toBeVisible();

    // Scenario 15: accept_assignment_writes_through
    await page.getByRole('button', { name: 'Accept Assignment' }).click();
    await expect(page.getByRole('region', { name: 'Current Work' })).toContainText('accepted');

    // Scenario 16: worker_records_location_writes_through
    await page.getByRole('button', { name: 'Record Location' }).click();
    await expect(page.getByRole('alert')).toContainText(/Location recorded/i);

    // Collect & seal sample
    await page.getByRole('button', { name: 'Collect and Seal Sample' }).click();
    await expect(page.getByRole('alert')).toContainText(/collected and sealed/i);

    // Trigger an out-of-range temperature checkpoint via collector1's session token or UI to verify Scenario 8 (sample_view_surfaces_exception_flag)
    const colLogin = await apiPost('/authenticate-user', '', { username: 'collector1', password: 'password123' });
    const colToken = colLogin.body.data.sessionToken as string;
    const rw = await apiPost('/list-role-work', colToken, {});
    const sampleId = rw.body.data.completed[0].sampleId as string;
    const assignmentId = rw.body.data.completed[0].assignmentId as string;
    await apiPost('/record-handling-checkpoint', colToken, {
      sampleId,
      assignmentId,
      locationId: colNodeId,
      containerType: 'amber-vial',
      observedTemperatureC: 25,
      recordedAt: new Date().toISOString(),
      idempotencyKey: 'e2e-cp-bad'
    });

    // Scenario 8: sample_view_surfaces_exception_flag
    await expect(page.getByRole('region', { name: 'Samples and Lifecycle Tracking' })).toContainText(/Exception Flag/i);

    await page.getByRole('button', { name: 'Sign Out' }).click();

    // Scenario 14: lab_worker_views_own_capacity
    await page.getByLabel('Username').fill('lab1');
    await page.getByLabel('Password').fill('password123');
    await page.getByRole('button', { name: 'Sign In' }).click();
    const capRegion = page.getByRole('region', { name: 'Laboratory and Node Capacity' });
    await expect(capRegion).toBeVisible();
    await expect(capRegion).toContainText('Regular Capacity:');
    await expect(capRegion).toContainText('Cooled Capacity:');

    expect(consoleErrors).toEqual([]);
    expect(pageErrors).toEqual([]);
    expect(server5xx).toEqual([]);
    expect(externalTileUrls).toEqual([]);
  });
});
